INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u6-C1','math',3,2,'u6',2,'표와 ◯ 그래프 되짚기 — 표는 수를 정확히 알 수 있고 합계로 전체를 알며, ◯ 그래프는 가장 많은 것을 한눈에 알 수 있음을 알고, 합계에서 아는 수를 빼어 모르는 수를 구하기',ARRAY['4수04-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u6-C2','math',3,2,'u6',2,'그림그래프 읽기 — 조사한 수를 그림으로 나타낸 그래프를 그림그래프라 하고, 큰 그림과 작은 그림이 나타내는 수(단위)를 먼저 보아 큰 그림부터 세고 작은 그림을 더해 수를 읽기',ARRAY['4수04-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u6-C3','math',3,2,'u6',2,'그림그래프로 많고 적음 견주기 — 큰 그림이 많은 것부터 보고 큰 그림이 같으면 작은 그림을 견주며, 그림의 개수가 같아도 크기가 다르면 나타내는 수가 다름을 알고 차와 합계를 구하기',ARRAY['4수04-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u6-C4','math',3,2,'u6',3,'그림그래프로 나타내기 — 제목·그림과 단위·항목·그림 네 가지를 갖추어, 수를 큰 그림 몇 개와 작은 그림 몇 개로 나누어 큰 그림부터 그리고, 큰 수는 100·10·1 세 가지 그림으로도 나타내기',ARRAY['4수04-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u6-C5','math',3,2,'u6',3,'그림그래프로 해석하고 정하기 — 그림그래프에서 가장 많은 것·가장 적은 것을 찾아 급식·교육 같은 일을 정하고, 자료에 맞는 까닭을 대기',ARRAY['4수04-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u6-C6','math',3,2,'u6',4,'자료 수집 계획과 표로 정리 — 직접 모을 수 있고 분명한 주제·조사 대상·항목(4~6개)을 정하고, 손 들기·투표하기·붙임딱지 붙이기·돌아다니며 묻기 가운데 알맞은 방법으로 모아 표로 정리하기',ARRAY['4수04-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u6-C7','math',3,2,'u6',5,'모은 자료를 그림그래프로 나타내고 확인하기 — 5·1처럼 알맞은 단위를 정해 나타내고, 빠진 항목이 없는지·그림이 나타내는 수의 합이 표의 합계와 같은지 확인해 고치기',ARRAY['4수04-01']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u6-C8','math',3,2,'u6',6,'단위가 다른 두 그림그래프 견주기 — 같은 자료를 10·1과 100·10·1로 나타낸 두 그림그래프의 같은 점(그림)과 다른 점(단위의 종류)을 찾고, 단위의 종류가 늘면 큰 수를 적은 그림으로 나타내지만 크기 구분이 어려움을 알기',ARRAY['4수04-01']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u6-C9','math',3,2,'u6',6,'그림의 크기에 속지 않기 — 그림을 크게 그리면 실제보다 많아 보이고, 가로와 세로를 함께 2배로 하면 넓이는 4배가 됨을 알아 그림의 크기가 아니라 그림이 나타내는 수로 읽기',ARRAY['4수04-01']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X01','math',3,'u6',ARRAY['M3-2-u6-C2','M3-2-u6-C3','M3-2-u6-C4','M3-2-u6-C5','M3-2-u6-C7','M3-2-u6-C8']::text[],'큰 그림과 작은 그림을 가리지 않고 그림의 개수만 센다(큰 그림 2개·작은 그림 3개 → 5명)','그림마다 나타내는 수를 먼저 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X02','math',3,'u6',ARRAY['M3-2-u6-C2','M3-2-u6-C4','M3-2-u6-C5','M3-2-u6-C7','M3-2-u6-C8']::text[],'큰 그림과 작은 그림이 나타내는 수를 바꾸어 읽거나, 큰 그림을 엉뚱한 수로 읽는다(10명 그림을 1명·5명으로)','그림 뜻 줄에서 크기별 수 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X03','math',3,'u6',ARRAY['M3-2-u6-C3','M3-2-u6-C4','M3-2-u6-C7','M3-2-u6-C8']::text[],'그림의 개수가 같으면 나타내는 수도 같다고 하거나, 그림이 많을수록 수가 많다고 한다','큰 그림이 몇 개인지부터 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X04','math',3,'u6',ARRAY['M3-2-u6-C3','M3-2-u6-C4','M3-2-u6-C5','M3-2-u6-C7']::text[],'가장 많은(적은) 것을 찾을 때 큰 그림을 먼저 보지 않고 그림을 모두 센 개수로 견준다','큰 그림이 가장 많은 줄부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X05','math',3,'u6',ARRAY['M3-2-u6-C4','M3-2-u6-C7']::text[],'수를 그림으로 나타낼 때 큰 그림과 작은 그림의 개수를 바꾼다(18명 → 10명 그림 8개, 1명 그림 1개)','십의 자리는 큰 그림, 일의 자리는 작은 그림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X06','math',3,'u6',ARRAY['M3-2-u6-C4','M3-2-u6-C7','M3-2-u6-C8']::text[],'큰 그림으로 나타낸 뒤 남은 수를 작은 그림으로 그리지 않거나, 큰 그림을 쓰지 않고 작은 그림만 늘어놓는다','큰 그림부터, 남은 수는 작은 그림으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X07','math',3,'u6',ARRAY['M3-2-u6-C4','M3-2-u6-C5','M3-2-u6-C7','M3-2-u6-C8']::text[],'그림그래프에 꼭 있어야 할 제목·그림과 단위·항목을 빠뜨리거나 네 걸음을 헷갈린다','제목·단위·항목·그림 네 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X08','math',3,'u6',ARRAY['M3-2-u6-C1','M3-2-u6-C3','M3-2-u6-C6','M3-2-u6-C7']::text[],'합계로 모르는 수를 구할 때 더하거나, 차를 묻는데 두 수를 더한다(덧셈과 뺄셈을 바꾼다)','모르는 수 = 합계 − 아는 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X09','math',3,'u6',ARRAY['M3-2-u6-C1']::text[],'표와 ◯ 그래프의 좋은 점을 바꾸어 안다(표가 가장 많은 것을 한눈에 보여 준다고 한다)','표는 정확한 수, 그래프는 한눈에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X10','math',3,'u6',ARRAY['M3-2-u6-C6']::text[],'직접 조사하기 어렵거나 무엇을 조사하는지 분명하지 않은 주제를 고르고, 항목을 너무 적거나 많게 정한다','우리가 직접 물어볼 수 있는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X11','math',3,'u6',ARRAY['M3-2-u6-C6']::text[],'손 들기·투표하기·붙임딱지·돌아다니며 묻기의 방법과 좋은 점·어려운 점을 헷갈린다','방법마다 하는 일 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X12','math',3,'u6',ARRAY['M3-2-u6-C6','M3-2-u6-C7']::text[],'자료를 모아 나타내는 순서를 거꾸로 한다(그림그래프를 먼저 그리고 주제를 정한다)','주제 → 모으기 → 표 → 그림그래프') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X13','math',3,'u6',ARRAY['M3-2-u6-C4','M3-2-u6-C6','M3-2-u6-C7','M3-2-u6-C8']::text[],'다 그린 뒤 빠진 항목이나 덜(더) 그린 그림을 확인하지 않는다 — 그림이 나타내는 수의 합을 표의 합계와 견주지 않는다','그림의 합 = 표의 합계?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X14','math',3,'u6',ARRAY['M3-2-u6-C8']::text[],'단위가 다른 두 그림그래프에서 그림 개수가 다르면 나타내는 수도 다르다고 하거나, 단위가 늘 때의 좋은 점·어려운 점을 바꾸어 안다','같은 자료면 수는 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X15','math',3,'u6',ARRAY['M3-2-u6-C5','M3-2-u6-C7','M3-2-u6-C8','M3-2-u6-C9']::text[],'그림의 크기(넓이)만 보고 많고 적음을 판단하거나, 가로와 세로를 2배로 하면 넓이도 2배라고 한다','넓이 = 가로 × 세로로 생각하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X16','math',3,'u6',ARRAY['M3-2-u6-C1','M3-2-u6-C2','M3-2-u6-C3','M3-2-u6-C4','M3-2-u6-C5','M3-2-u6-C6','M3-2-u6-C7','M3-2-u6-C8','M3-2-u6-C9']::text[],'묻는 말을 거꾸로 읽는다 — 많은↔적은, 옳지 않은↔옳은, 더↔덜','물음의 「적은·옳지 않은」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X17','math',3,'u6',ARRAY['M3-2-u6-C5','M3-2-u6-C8']::text[],'그림그래프를 보고 정한 일에 자료와 맞지 않는 까닭을 대거나 까닭 없이 정한다','그래프에서 읽은 사실로 까닭 대기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X18','math',3,'u6',ARRAY['M3-2-u6-C2','M3-2-u6-C4']::text[],'그림그래프의 뜻을 「그림이 들어간 그래프」로만 알아, 그림 하나하나가 정해진 수(단위)를 나타낸다는 것을 놓친다 — 그림이 들어가기만 하면 그림그래프라고 하거나, 그림이 무엇을 얼마만큼 나타내는지 보지 않는다','그림 하나가 무엇을 몇만큼 나타내는지(그림의 단위) 먼저 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u6-X19','math',3,'u6',ARRAY['M3-2-u6-C4','M3-2-u6-C7']::text[],'그림을 예쁘게 꾸미려고 한 그림그래프 안에 여러 가지 모양을 섞어 그리거나, 조사한 내용과 상관없는 그림을 고른다 — 「더 예쁘게 여러 가지 그림으로 그리자」','무엇을 조사했는지 한눈에 보이는 그림 한 가지로, 크기만 달리하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_basic#1','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_basic','lesson_basic','M3-2-u6-C1',1,'sa','auto','준비하기 — 좋아하는 계절별 학생 수를 조사하여 나타낸 표예요. 가을을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u6-C1","difficulty":1,"kind":"sa","stem":"준비하기 — 좋아하는 계절별 학생 수를 조사하여 나타낸 표예요. 가을을 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["표의 「가을」 칸 아래 수를 읽어요.","표는 조사한 수를 정확히 알 수 있어요.","전체 학생 25명 중에서 가을을 좋아하는 학생은 6명이에요."],"asset":{"type":"picg","only":"table","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[8,7,6,4],"unit":"명","vh":"학생 수","title":"좋아하는 계절별 학생 수","total":25},"variant_rule":{"alt":[{"stem":"학생 12명이 좋아하는 과일을 조사하여 나타낸 표예요. 사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["표의 「사과」 칸 아래 수를 읽어요.","귤 3명, 바나나 3명, 사과 4명, 포도 2명 — 합계 12명이에요.","사과를 좋아하는 학생은 4명이에요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["귤","바나나","사과","포도"],"counts":[3,3,4,2],"unit":"명","vh":"학생 수","title":"좋아하는 과일별 학생 수","total":12}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_basic#2','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_basic','lesson_basic','M3-2-u6-C1',1,'sa','auto','준비하기 — 여행 가고 싶어 하는 나라별 학생 수를 나타낸 표를 완성하려고 해요. 영국에 여행을 가고 싶어 하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u6-C1","difficulty":1,"kind":"sa","stem":"준비하기 — 여행 가고 싶어 하는 나라별 학생 수를 나타낸 표를 완성하려고 해요. 영국에 여행을 가고 싶어 하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["합계 50명은 세 나라의 학생 수를 모두 더한 수예요.","모르는 수 = 합계 − 아는 수 — 미국 20명, 일본 17명을 빼요.","50 − 20 − 17 = 13 — 영국은 13명이에요."],"asset":{"type":"picg","only":"table","head":"나라","cols":["미국","영국","일본"],"counts":[20,null,17],"unit":"명","vh":"학생 수","title":"여행 가고 싶어 하는 나라별 학생 수","total":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_basic#3','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_basic','lesson_basic','M3-2-u6-C2',1,'blank','auto','조사한 자료의 수를 그림으로 나타낸 그래프를 □(이)라고 합니다. □에 알맞은 말은 무엇인가요?',ARRAY['M3-2-u6-X09','M3-2-u6-X18']::text[],false,'{"seq":3,"concept":"M3-2-u6-C2","difficulty":1,"kind":"blank","stem":"조사한 자료의 수를 그림으로 나타낸 그래프를 □(이)라고 합니다. □에 알맞은 말은 무엇인가요?","options":[{"t":"그림그래프","correct":true},{"t":"표","mis":"M3-2-u6-X09"},{"t":"◯ 그래프","mis":"M3-2-u6-X09"},{"t":"그림일기","mis":"M3-2-u6-X18"}],"explanation":["2학년 때는 자료를 표와 ◯, ×, /을 이용한 그래프로 나타냈어요.","조사한 자료의 수를 그림으로 나타낸 그래프는 그림그래프예요.","그림그래프에서는 그림 하나하나가 정해진 수를 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_basic#4','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_basic','lesson_basic','M3-2-u6-C2',1,'mc','auto','그림그래프에서 크기가 다른 그림은 각각 몇 명을 나타내나요?',ARRAY['M3-2-u6-X02','M3-2-u6-X01','M3-2-u6-X18']::text[],true,'{"seq":4,"concept":"M3-2-u6-C2","difficulty":1,"kind":"mc","stem":"그림그래프에서 크기가 다른 그림은 각각 몇 명을 나타내나요?","options":[{"t":"큰 그림 10명, 작은 그림 1명","correct":true},{"t":"큰 그림 1명, 작은 그림 10명","mis":"M3-2-u6-X02"},{"t":"큰 그림 1명, 작은 그림 1명","mis":"M3-2-u6-X01"},{"t":"큰 그림 20명, 작은 그림 1명","mis":"M3-2-u6-X18"}],"explanation":["그림그래프 아래 그림의 단위를 먼저 봐요.","큰 그림 10명, 작은 그림 1명이에요.","그림의 크기에 따라 나타내는 수가 달라요 — 그림을 읽기 전에 단위부터 확인해요."],"asset":{"type":"picg","title":"좋아하는 여가 활동별 학생 수","head":"활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[12,7,20,14],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 크기가 다른 그림은 각각 몇 회를 나타내나요?","options":[{"t":"큰 그림 5회, 작은 그림 1회","correct":true},{"t":"큰 그림 1회, 작은 그림 5회","mis":"M3-2-u6-X02"},{"t":"큰 그림 1회, 작은 그림 1회","mis":"M3-2-u6-X01"},{"t":"큰 그림 10회, 작은 그림 1회","mis":"M3-2-u6-X18"}],"explanation":["그림그래프 아래 그림의 단위를 먼저 봐요.","큰 그림 5회, 작은 그림 1회예요.","그림의 크기에 따라 나타내는 수가 달라요 — 그림을 읽기 전에 단위부터 확인해요."],"asset":{"type":"picg","title":"학생별 훌라후프를 한 횟수","head":"이름","cols":["건우","도윤","은비","지유"],"counts":[19,9,25,12],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"}},{"stem":"이번에는 다른 그림그래프예요. 그림그래프에서 크기가 다른 그림은 각각 몇 명을 나타내나요?","options":[{"t":"큰 그림 10명, 작은 그림 1명","correct":true},{"t":"큰 그림 1명, 작은 그림 10명","mis":"M3-2-u6-X02"},{"t":"큰 그림 1명, 작은 그림 1명","mis":"M3-2-u6-X01"},{"t":"큰 그림 20명, 작은 그림 1명","mis":"M3-2-u6-X18"}],"explanation":["그림그래프 아래 그림의 단위를 먼저 봐요.","큰 그림 10명, 작은 그림 1명이에요.","그림의 크기에 따라 나타내는 수가 달라요 — 그림을 읽기 전에 단위부터 확인해요."],"asset":{"type":"picg","title":"가고 싶어 하는 체험 학습 장소별 학생 수","head":"장소","cols":["과학관","놀이공원","동물원","박물관"],"counts":[7,42,30,13],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_basic#5','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_basic','lesson_basic','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 자전거 타기를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 자전거 타기를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["20"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","자전거 타기 줄은 10명 그림 2개 — 10 × 2 = 20.","자전거 타기를 좋아하는 학생은 20명이에요."],"asset":{"type":"picg","title":"좋아하는 여가 활동별 학생 수","head":"활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[12,7,20,14],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 줄넘기를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["14"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","줄넘기 줄은 10명 그림 1개와 1명 그림 4개 — 10 × 1 + 1 × 4 = 14.","줄넘기를 좋아하는 학생은 14명이에요."],"asset":{"type":"picg","title":"좋아하는 여가 활동별 학생 수","head":"활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[12,7,20,14],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_basic#6','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_basic','lesson_basic','M3-2-u6-C3',2,'mc','auto','그림그래프에서 가장 적은 학생이 좋아하는 여가 활동은 무엇인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X04']::text[],true,'{"seq":6,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"그림그래프에서 가장 적은 학생이 좋아하는 여가 활동은 무엇인가요?","options":[{"t":"산책","correct":true},{"t":"배드민턴","mis":"M3-2-u6-X03"},{"t":"자전거 타기","mis":"M3-2-u6-X04"},{"t":"줄넘기","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","배드민턴 12명, 산책 7명, 자전거 타기 20명, 줄넘기 14명.","가장 적은 것은 산책이에요."],"asset":{"type":"picg","title":"좋아하는 여가 활동별 학생 수","head":"활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[12,7,20,14],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 가장 적은 학생이 가고 싶어 하는 체험 학습 장소는 어디인가요?","options":[{"t":"과학관","correct":true},{"t":"놀이공원","mis":"M3-2-u6-X16"},{"t":"동물원","mis":"M3-2-u6-X04"},{"t":"박물관","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","과학관 7명, 놀이공원 42명, 동물원 30명, 박물관 13명.","가장 적은 것은 과학관이에요."],"asset":{"type":"picg","title":"가고 싶어 하는 체험 학습 장소별 학생 수","head":"장소","cols":["과학관","놀이공원","동물원","박물관"],"counts":[7,42,30,13],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_basic#7','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_basic','lesson_basic','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 지유가 훌라후프를 한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 지유가 훌라후프를 한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.","answer":["12"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 5회, 작은 그림 1회.","지유 줄은 5회 그림 2개와 1회 그림 2개 — 5 × 2 + 1 × 2 = 12.","지유가 훌라후프를 한 횟수는 12회예요."],"asset":{"type":"picg","title":"학생별 훌라후프를 한 횟수","head":"이름","cols":["건우","도윤","은비","지유"],"counts":[19,9,25,12],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 건우가 훌라후프를 한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.","answer":["19"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 5회, 작은 그림 1회.","건우 줄은 5회 그림 3개와 1회 그림 4개 — 5 × 3 + 1 × 4 = 19.","건우가 훌라후프를 한 횟수는 19회예요."],"asset":{"type":"picg","title":"학생별 훌라후프를 한 횟수","head":"이름","cols":["건우","도윤","은비","지유"],"counts":[19,9,25,12],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"}},{"stem":"그림그래프를 보고 도윤이 훌라후프를 한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.","answer":["9"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 5회, 작은 그림 1회.","도윤 줄은 5회 그림 1개와 1회 그림 4개 — 5 × 1 + 1 × 4 = 9.","도윤이 훌라후프를 한 횟수는 9회예요."],"asset":{"type":"picg","title":"학생별 훌라후프를 한 횟수","head":"이름","cols":["건우","도윤","은비","지유"],"counts":[19,9,25,12],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_basic#8','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_basic','lesson_basic','M3-2-u6-C3',2,'mc','auto','그림그래프에서 훌라후프를 가장 많이 한 학생은 누구인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16','M3-2-u6-X03']::text[],false,'{"seq":8,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"그림그래프에서 훌라후프를 가장 많이 한 학생은 누구인가요?","options":[{"t":"은비","correct":true},{"t":"건우","mis":"M3-2-u6-X04"},{"t":"도윤","mis":"M3-2-u6-X16"},{"t":"지유","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","건우 19회, 도윤 9회, 은비 25회, 지유 12회.","가장 많은 것은 은비예요."],"asset":{"type":"picg","title":"학생별 훌라후프를 한 횟수","head":"이름","cols":["건우","도윤","은비","지유"],"counts":[19,9,25,12],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_basic#9','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_basic','lesson_basic','M3-2-u6-C1',2,'mc','auto','3학년 학생들이 좋아하는 여가 활동을 표와 ◯를 이용한 그래프로 나타냈어요. 그래프에서는 자전거 타기의 ◯가 20개로 가장 높이 올라가 있어요. 표를 그래프로 나타내면 좋은 점은 무엇인가요?',ARRAY['M3-2-u6-X09']::text[],false,'{"seq":9,"concept":"M3-2-u6-C1","difficulty":2,"kind":"mc","stem":"3학년 학생들이 좋아하는 여가 활동을 표와 ◯를 이용한 그래프로 나타냈어요. 그래프에서는 자전거 타기의 ◯가 20개로 가장 높이 올라가 있어요. 표를 그래프로 나타내면 좋은 점은 무엇인가요?","options":[{"t":"자료의 수를 한눈에 보기 쉬워요","correct":true},{"t":"전체 학생 수(합계)를 바로 알 수 있어요","mis":"M3-2-u6-X09"},{"t":"조사한 수를 정확한 수로 알 수 있어요","mis":"M3-2-u6-X09"},{"t":"조사한 학생의 이름을 알 수 있어요","mis":"M3-2-u6-X09"}],"explanation":["표는 수로, 그래프는 ◯로 나타내었어요.","표는 정확한 수와 합계를 알기 쉽고, 그래프는 많고 적음을 한눈에 보기 쉬워요.","그래프에서는 자전거 타기를 좋아하는 학생이 가장 많다는 것이 한눈에 보여요."],"asset":{"type":"picg","only":"table","head":"활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[12,7,20,14],"unit":"명","vh":"학생 수","title":"좋아하는 여가 활동별 학생 수","total":53}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_basic#10','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_basic','lesson_basic','M3-2-u6-C2',3,'error','auto','친구들이 그림그래프가 무엇인지 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u6-X18','M3-2-u6-X16']::text[],false,'{"seq":10,"concept":"M3-2-u6-C2","difficulty":3,"kind":"error","stem":"친구들이 그림그래프가 무엇인지 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하늘 — 「그림이 들어간 그래프면 모두 그림그래프예요」","correct":true,"mis_target":"M3-2-u6-X18"},{"t":"서윤 — 「조사한 자료의 수를 그림으로 나타낸 그래프예요」","mis":"M3-2-u6-X16"},{"t":"도윤 — 「그림마다 몇을 나타내는지 먼저 봐야 해요」","mis":"M3-2-u6-X16"}],"explanation":["그림그래프는 조사한 자료의 수를 그림으로 나타낸 그래프예요.","그림이 들어가기만 한다고 그림그래프가 아니에요 — 그림 하나하나가 정해진 수를 나타내요.","그래서 그림의 단위(10명, 1명 등)를 먼저 봐야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_challenge#1','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C3',2,'mc','auto','친구와 이어 말하기 놀이를 해요. 그림그래프에서 오리를 가장 많이 기르는 농장은 어느 농장인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X03']::text[],false,'{"seq":1,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"친구와 이어 말하기 놀이를 해요. 그림그래프에서 오리를 가장 많이 기르는 농장은 어느 농장인가요?","options":[{"t":"가락","correct":true},{"t":"나눔","mis":"M3-2-u6-X04"},{"t":"다사랑","mis":"M3-2-u6-X03"},{"t":"라라","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","가락 53마리, 나눔 28마리, 다사랑 42마리, 라라 31마리.","가장 많은 것은 가락이에요."],"asset":{"type":"picg","title":"농장별 기르는 오리의 수","head":"농장","cols":["가락","나눔","다사랑","라라"],"counts":[53,28,42,31],"units":[10,1],"icon":"🐥","unit":"마리","vh":"오리의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_challenge#2','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 옷을 받고 싶어 하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 옷을 받고 싶어 하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["17"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 5명, 작은 그림 1명.","옷 줄은 5명 그림 3개와 1명 그림 2개 — 5 × 3 + 1 × 2 = 17.","옷을 받고 싶어 하는 학생은 17명이에요."],"asset":{"type":"picg","title":"받고 싶어 하는 선물별 학생 수","head":"선물","cols":["옷","인형","장난감"],"counts":[17,14,21],"units":[5,1],"icon":"🎁","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 인형을 받고 싶어 하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["14"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 5명, 작은 그림 1명.","인형 줄은 5명 그림 2개와 1명 그림 4개 — 5 × 2 + 1 × 4 = 14.","인형을 받고 싶어 하는 학생은 14명이에요."],"asset":{"type":"picg","title":"받고 싶어 하는 선물별 학생 수","head":"선물","cols":["옷","인형","장난감"],"counts":[17,14,21],"units":[5,1],"icon":"🎁","unit":"명","vh":"학생 수"}},{"stem":"그림그래프를 보고 장난감을 받고 싶어 하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["21"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 5명, 작은 그림 1명.","장난감 줄은 5명 그림 4개와 1명 그림 1개 — 5 × 4 + 1 × 1 = 21.","장난감을 받고 싶어 하는 학생은 21명이에요."],"asset":{"type":"picg","title":"받고 싶어 하는 선물별 학생 수","head":"선물","cols":["옷","인형","장난감"],"counts":[17,14,21],"units":[5,1],"icon":"🎁","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_challenge#3','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C3',3,'sa','auto','그림그래프를 보고 가락 농장에서 기르는 오리는 나눔 농장에서 기르는 오리보다 몇 마리 더 많은지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u6-C3","difficulty":3,"kind":"sa","stem":"그림그래프를 보고 가락 농장에서 기르는 오리는 나눔 농장에서 기르는 오리보다 몇 마리 더 많은지 구하세요. 숫자로 쓰세요.","answer":["25"],"explanation":["두 항목의 수를 먼저 읽어요 — 가락 53마리, 나눔 28마리.","몇 개 더 많은지는 뺄셈으로 구해요.","53 − 28 = 25 — 25마리 더 많아요."],"asset":{"type":"picg","title":"농장별 기르는 오리의 수","head":"농장","cols":["가락","나눔","다사랑","라라"],"counts":[53,28,42,31],"units":[10,1],"icon":"🐥","unit":"마리","vh":"오리의 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 다사랑 농장에서 기르는 오리는 라라 농장에서 기르는 오리보다 몇 마리 더 많은지 구하세요. 숫자로 쓰세요.","answer":["11"],"explanation":["두 항목의 수를 먼저 읽어요 — 다사랑 42마리, 라라 31마리.","몇 개 더 많은지는 뺄셈으로 구해요.","42 − 31 = 11 — 11마리 더 많아요."],"asset":{"type":"picg","title":"농장별 기르는 오리의 수","head":"농장","cols":["가락","나눔","다사랑","라라"],"counts":[53,28,42,31],"units":[10,1],"icon":"🐥","unit":"마리","vh":"오리의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_challenge#4','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C2',3,'sa','auto','그림그래프를 보고 신선 과수원에서 생산한 사과는 몇 kg인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u6-C2","difficulty":3,"kind":"sa","stem":"그림그래프를 보고 신선 과수원에서 생산한 사과는 몇 kg인지 구하세요. 숫자로 쓰세요.","answer":["230"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 100 kg, 작은 그림 10 kg.","신선 줄은 100 kg 그림 2개와 10 kg 그림 3개 — 100 × 2 + 10 × 3 = 230.","신선 과수원에서 생산한 사과는 230 kg이에요."],"asset":{"type":"picg","title":"과수원별 사과 생산량","head":"과수원","cols":["맑음","신선","푸름","햇빛"],"counts":[220,230,160,300],"units":[100,10],"icon":"🍎","unit":"kg","vh":"생산량"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 맑음 과수원에서 생산한 사과는 몇 kg인지 구하세요. 숫자로 쓰세요.","answer":["220"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 100 kg, 작은 그림 10 kg.","맑음 줄은 100 kg 그림 2개와 10 kg 그림 2개 — 100 × 2 + 10 × 2 = 220.","맑음 과수원에서 생산한 사과는 220 kg이에요."],"asset":{"type":"picg","title":"과수원별 사과 생산량","head":"과수원","cols":["맑음","신선","푸름","햇빛"],"counts":[220,230,160,300],"units":[100,10],"icon":"🍎","unit":"kg","vh":"생산량"}},{"stem":"그림그래프를 보고 햇빛 과수원에서 생산한 사과는 몇 kg인지 구하세요. 숫자로 쓰세요.","answer":["300"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 100 kg, 작은 그림 10 kg.","햇빛 줄은 100 kg 그림 3개 — 100 × 3 = 300.","햇빛 과수원에서 생산한 사과는 300 kg이에요."],"asset":{"type":"picg","title":"과수원별 사과 생산량","head":"과수원","cols":["맑음","신선","푸름","햇빛"],"counts":[220,230,160,300],"units":[100,10],"icon":"🍎","unit":"kg","vh":"생산량"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_challenge#5','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C3',3,'sa','auto','맑음 과수원은 생산한 사과를 한 상자에 5 kg씩 담아 팔았어요. 그림그래프를 보고 맑음 과수원에서 판매한 사과는 몇 상자인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M3-2-u6-C3","difficulty":3,"kind":"sa","stem":"맑음 과수원은 생산한 사과를 한 상자에 5 kg씩 담아 팔았어요. 그림그래프를 보고 맑음 과수원에서 판매한 사과는 몇 상자인지 구하세요. 숫자로 쓰세요.","answer":["44"],"explanation":["맑음 과수원 줄은 100 kg 그림 2개와 10 kg 그림 2개 — 100 × 2 + 10 × 2 = 220이에요.","220 kg을 5 kg씩 나누어 담아요.","220 ÷ 5 = 44 — 44상자예요."],"asset":{"type":"picg","title":"과수원별 사과 생산량","head":"과수원","cols":["맑음","신선","푸름","햇빛"],"counts":[220,230,160,300],"units":[100,10],"icon":"🍎","unit":"kg","vh":"생산량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_challenge#6','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C2',3,'error','auto','어느 신발 가게에서 일주일 동안 판매한 신발의 수를 조사한 그림그래프예요. 그림그래프를 보고 알 수 있는 내용으로 옳지 않은 것은 어느 것인가요?',ARRAY['M3-2-u6-X02','M3-2-u6-X16']::text[],false,'{"seq":6,"concept":"M3-2-u6-C2","difficulty":3,"kind":"error","stem":"어느 신발 가게에서 일주일 동안 판매한 신발의 수를 조사한 그림그래프예요. 그림그래프를 보고 알 수 있는 내용으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"㉠ 판매한 운동화는 31켤레예요","correct":true,"mis_target":"M3-2-u6-X02"},{"t":"㉡ 가장 적게 판매한 신발은 장화예요","mis":"M3-2-u6-X16"},{"t":"㉢ 구두보다 많이 판매한 신발은 샌들과 운동화예요","mis":"M3-2-u6-X16"}],"explanation":["그림의 단위는 큰 그림 5켤레, 작은 그림 1켤레예요.","운동화는 5켤레 그림 3개와 1켤레 그림 1개 — 5 × 3 + 1 × 1 = 16이에요.","큰 그림을 10켤레로 읽으면 31켤레라고 잘못 읽어요 — 옳지 않은 것은 ㉠이에요."],"asset":{"type":"picg","title":"종류별 판매한 신발의 수","head":"종류","cols":["구두","샌들","운동화","장화"],"counts":[10,14,16,8],"units":[5,1],"icon":"👟","unit":"켤레","vh":"신발의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_challenge#7','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C3',3,'mc','auto','좋아하는 텔레비전 프로그램별 사람 수를 나타낸 그림그래프예요. ㉠과 ㉡은 그림이 3개씩이에요. 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u6-X01','M3-2-u6-X03','M3-2-u6-X16']::text[],false,'{"seq":7,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"좋아하는 텔레비전 프로그램별 사람 수를 나타낸 그림그래프예요. ㉠과 ㉡은 그림이 3개씩이에요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"㉡은 21명, ㉠은 12명이라 ㉡을 좋아하는 사람이 더 많아요","correct":true},{"t":"그림이 3개씩이라 둘 다 3명이에요","mis":"M3-2-u6-X01"},{"t":"그림의 수가 같으니 좋아하는 사람 수도 같아요","mis":"M3-2-u6-X03"},{"t":"㉠이 ㉡보다 9명 더 많아요","mis":"M3-2-u6-X16"}],"explanation":["그림의 모양과 수가 같아도 그림의 크기에 따라 나타내는 수가 달라요.","㉠은 10명 그림 1개와 1명 그림 2개 — 12명, ㉡은 10명 그림 2개와 1명 그림 1개 — 21명이에요.","21 − 12 = 9 — ㉡이 9명 더 많아요."],"asset":{"type":"picg","title":"좋아하는 텔레비전 프로그램별 사람 수","head":"프로그램","cols":["㉠","㉡","㉢","㉣"],"counts":[12,21,14,16],"units":[10,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_challenge#8','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C2',4,'essay','teacher','3학년 학생들이 좋아하는 여가 활동을 ◯를 이용한 그래프와 그림그래프(10명·1명)로 나타냈어요. 두 그래프의 같은 점과 다른 점을 쓰고, 조사한 자료의 수를 그림으로 나타내었을 때 좋은 점을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u6-C2","difficulty":4,"kind":"essay","stem":"3학년 학생들이 좋아하는 여가 활동을 ◯를 이용한 그래프와 그림그래프(10명·1명)로 나타냈어요. 두 그래프의 같은 점과 다른 점을 쓰고, 조사한 자료의 수를 그림으로 나타내었을 때 좋은 점을 써 보세요.","answer_guide":{"answer":"같은 점: 학생 수를 비교하기 쉽다. 다른 점: 그림그래프는 크기가 다른 그림(10명, 1명)을 사용했다. 좋은 점: 자전거 타기 20명을 ◯ 20개 대신 10명 그림 2개로 나타내듯, 일일이 기호로 나타내는 번거로움이 줄어든다.","scoring_points":["같은 점(학생 수를 비교하기 쉬움)을 썼는가","다른 점(크기가 다른 그림)을 썼는가","좋은 점(일일이 기호로 나타내는 번거로움이 줄어듦)을 썼는가"]},"explanation":["◯ 그래프는 학생 한 명을 ◯ 하나로 나타내요.","그림그래프는 10명 그림과 1명 그림처럼 크기가 다른 그림을 써요.","자전거 타기 20명은 ◯ 20개 대신 10명 그림 2개 — 번거로움이 줄어요."],"asset":{"type":"picg","title":"좋아하는 여가 활동별 학생 수","head":"활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[12,7,20,14],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_challenge#9','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C3',4,'essay','teacher','친구와 함께 오리 그림그래프를 보고 이어 말하기 놀이를 해요. 그림그래프를 보고 알 수 있는 내용을 세 가지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u6-C3","difficulty":4,"kind":"essay","stem":"친구와 함께 오리 그림그래프를 보고 이어 말하기 놀이를 해요. 그림그래프를 보고 알 수 있는 내용을 세 가지 써 보세요.","answer_guide":{"answer":"예: 가락 농장 53마리, 나눔 농장 28마리, 다사랑 농장 42마리, 라라 농장 31마리를 기른다. 가장 많은 오리를 기르는 농장은 가락 농장이다. 가장 적은 오리를 기르는 농장은 나눔 농장이다(그림은 나눔 농장이 가장 많지만 작은 그림이 많아서이다). 가락 농장은 나눔 농장보다 25마리 더 많다.","scoring_points":["그림의 단위(10마리·1마리)로 수를 바르게 읽었는가","가장 많은(적은) 농장을 큰 그림부터 견주어 찾았는가","알 수 있는 내용을 세 가지 썼는가"]},"explanation":["큰 그림은 10마리, 작은 그림은 1마리예요.","가락 53, 나눔 28, 다사랑 42, 라라 31 — 가장 많은 곳은 가락 농장이에요.","나눔 농장은 그림이 10개로 가장 많지만 28마리로 가장 적어요."],"asset":{"type":"picg","title":"농장별 기르는 오리의 수","head":"농장","cols":["가락","나눔","다사랑","라라"],"counts":[53,28,42,31],"units":[10,1],"icon":"🐥","unit":"마리","vh":"오리의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L02_challenge#10','math',3,2,'u6','L02','tb_g3_2_math_u6_L02_challenge','lesson_challenge','M3-2-u6-C2',4,'sa','auto','「학생별 훌라후프를 한 횟수」 그림그래프예요. 그림그래프에 나타난 수를 모두 더하면 몇 회인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u6-C2","difficulty":4,"kind":"sa","stem":"「학생별 훌라후프를 한 횟수」 그림그래프예요. 그림그래프에 나타난 수를 모두 더하면 몇 회인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["그림의 단위를 보고 줄마다 수를 읽어요 — 건우 19회, 도윤 9회, 은비 25회, 지유 12회.","읽은 수를 모두 더해요.","19 + 9 + 25 + 12 = 65 — 모두 65회예요."],"asset":{"type":"picg","title":"학생별 훌라후프를 한 횟수","head":"이름","cols":["건우","도윤","은비","지유"],"counts":[19,9,25,12],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"「좋아하는 여가 활동별 학생 수」 그림그래프예요. 그림그래프에 나타난 수를 모두 더하면 몇 명인가요? 숫자로 쓰세요.","answer":["62"],"explanation":["그림의 단위를 보고 줄마다 수를 읽어요 — 배드민턴 13명, 산책 16명, 자전거 타기 22명, 줄넘기 11명.","읽은 수를 모두 더해요.","13 + 16 + 22 + 11 = 62 — 모두 62명이에요."],"asset":{"type":"picg","title":"좋아하는 여가 활동별 학생 수","head":"활동","cols":["배드민턴","산책","자전거 타기","줄넘기"],"counts":[13,16,22,11],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"「받고 싶어 하는 선물별 학생 수」 그림그래프예요. 그림그래프에 나타난 수를 모두 더하면 몇 명인가요? 숫자로 쓰세요.","answer":["52"],"explanation":["그림의 단위를 보고 줄마다 수를 읽어요 — 옷 17명, 인형 14명, 장난감 21명.","읽은 수를 모두 더해요.","17 + 14 + 21 = 52 — 모두 52명이에요."],"asset":{"type":"picg","title":"받고 싶어 하는 선물별 학생 수","head":"선물","cols":["옷","인형","장난감"],"counts":[17,14,21],"units":[5,1],"icon":"🎁","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_basic#1','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',1,'blank','auto','그림그래프로 나타내는 방법이에요. 「자료의 수를 나타낼 □과 단위를 정합니다.」 □에 알맞은 말은 무엇인가요?',ARRAY['M3-2-u6-X07']::text[],true,'{"seq":1,"concept":"M3-2-u6-C4","difficulty":1,"kind":"blank","stem":"그림그래프로 나타내는 방법이에요. 「자료의 수를 나타낼 □과 단위를 정합니다.」 □에 알맞은 말은 무엇인가요?","options":[{"t":"그림","correct":true},{"t":"제목","mis":"M3-2-u6-X07"},{"t":"항목","mis":"M3-2-u6-X07"},{"t":"합계","mis":"M3-2-u6-X07"}],"explanation":["그림그래프로 나타내는 방법 — ① 알맞은 제목 ② 그림과 단위 ③ 항목을 빠짐없이 ④ 자료의 수에 맞게 그림.","「자료의 수를 나타낼 □과 단위를 정합니다.」의 □는 그림이에요.","순서는 바뀌어도 돼요 — 제목은 마지막에 써도 돼요."],"variant_rule":{"alt":[{"stem":"그림그래프로 나타내는 방법이에요. 「조사한 □을 빠짐없이 씁니다.」 □에 알맞은 말은 무엇인가요?","options":[{"t":"항목","correct":true},{"t":"제목","mis":"M3-2-u6-X07"},{"t":"그림","mis":"M3-2-u6-X07"},{"t":"합계","mis":"M3-2-u6-X07"}],"explanation":["그림그래프로 나타내는 방법 — ① 알맞은 제목 ② 그림과 단위 ③ 항목을 빠짐없이 ④ 자료의 수에 맞게 그림.","「조사한 □을 빠짐없이 씁니다.」의 □는 항목이에요.","순서는 바뀌어도 돼요 — 제목은 마지막에 써도 돼요."]},{"stem":"그림그래프로 나타내는 방법이에요. 「알맞은 □을 씁니다.」 □에 알맞은 말은 무엇인가요?","options":[{"t":"제목","correct":true},{"t":"항목","mis":"M3-2-u6-X07"},{"t":"그림","mis":"M3-2-u6-X07"},{"t":"단위","mis":"M3-2-u6-X07"}],"explanation":["그림그래프로 나타내는 방법 — ① 알맞은 제목 ② 그림과 단위 ③ 항목을 빠짐없이 ④ 자료의 수에 맞게 그림.","「알맞은 □을 씁니다.」의 □는 제목이에요.","순서는 바뀌어도 돼요 — 제목은 마지막에 써도 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_basic#2','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',1,'mc','auto','당근을 좋아하는 학생은 18명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],true,'{"seq":2,"concept":"M3-2-u6-C4","difficulty":1,"kind":"mc","stem":"당근을 좋아하는 학생은 18명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"10명 그림 1개, 1명 그림 8개","correct":true},{"t":"10명 그림 8개, 1명 그림 1개","mis":"M3-2-u6-X05"},{"t":"1명 그림 18개","mis":"M3-2-u6-X06"},{"t":"10명 그림 2개, 1명 그림 8개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","18명 안에 10명이 1번 들어가요 — 남은 8명은 1명 그림으로 나타내요.","답은 10명 그림 1개, 1명 그림 8개예요."],"variant_rule":{"alt":[{"stem":"오이를 좋아하는 학생은 24명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"10명 그림 2개, 1명 그림 4개","correct":true},{"t":"10명 그림 4개, 1명 그림 2개","mis":"M3-2-u6-X05"},{"t":"1명 그림 24개","mis":"M3-2-u6-X06"},{"t":"10명 그림 3개, 1명 그림 4개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","24명 안에 10명이 2번 들어가요 — 남은 4명은 1명 그림으로 나타내요.","답은 10명 그림 2개, 1명 그림 4개예요."]},{"stem":"콩나물을 좋아하는 학생은 35명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"10명 그림 3개, 1명 그림 5개","correct":true},{"t":"10명 그림 5개, 1명 그림 3개","mis":"M3-2-u6-X05"},{"t":"1명 그림 35개","mis":"M3-2-u6-X06"},{"t":"10명 그림 4개, 1명 그림 5개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","35명 안에 10명이 3번 들어가요 — 남은 5명은 1명 그림으로 나타내요.","답은 10명 그림 3개, 1명 그림 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_basic#3','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',1,'mc','auto','표를 보고 그림그래프로 나타낼 때 어떤 그림을 먼저 그리는 것이 좋을까요?',ARRAY['M3-2-u6-X06','M3-2-u6-X12']::text[],false,'{"seq":3,"concept":"M3-2-u6-C4","difficulty":1,"kind":"mc","stem":"표를 보고 그림그래프로 나타낼 때 어떤 그림을 먼저 그리는 것이 좋을까요?","options":[{"t":"큰 수를 나타내는 그림(10명 그림)","correct":true},{"t":"작은 수를 나타내는 그림(1명 그림)","mis":"M3-2-u6-X06"},{"t":"그리기 쉬운 아무 그림이나","mis":"M3-2-u6-X06"},{"t":"그림보다 합계를 먼저","mis":"M3-2-u6-X12"}],"explanation":["그림을 그릴 때는 큰 수를 나타내는 그림을 먼저 그려요.","당근 18명은 10명 그림 1개를 먼저, 남은 8명은 1명 그림 8개로 그려요.","큰 그림부터 그리면 자료의 수를 비교하기 쉬워요."],"asset":{"type":"picg","only":"table","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[18,10,24,35],"unit":"명","vh":"학생 수","title":"좋아하는 채소별 학생 수","total":87}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_basic#4','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C2',1,'mc','auto','그림그래프에서 크기가 다른 그림은 각각 몇 명을 나타내나요?',ARRAY['M3-2-u6-X02','M3-2-u6-X01','M3-2-u6-X18']::text[],false,'{"seq":4,"concept":"M3-2-u6-C2","difficulty":1,"kind":"mc","stem":"그림그래프에서 크기가 다른 그림은 각각 몇 명을 나타내나요?","options":[{"t":"큰 그림 100명, 가운데 그림 10명, 작은 그림 1명","correct":true},{"t":"큰 그림 1명, 가운데 그림 10명, 작은 그림 100명","mis":"M3-2-u6-X02"},{"t":"큰 그림 1명, 가운데 그림 1명, 작은 그림 1명","mis":"M3-2-u6-X01"},{"t":"큰 그림 200명, 가운데 그림 10명, 작은 그림 1명","mis":"M3-2-u6-X18"}],"explanation":["그림그래프 아래 그림의 단위를 먼저 봐요.","큰 그림 100명, 가운데 그림 10명, 작은 그림 1명이에요.","그림의 크기에 따라 나타내는 수가 달라요 — 그림을 읽기 전에 단위부터 확인해요."],"asset":{"type":"picg","title":"좋아하는 우리나라 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜","잡채"],"counts":[130,115,100,26,40],"units":[100,10,1],"icon":"🍚","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_basic#5','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 식혜를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 식혜를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["26"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 100명, 가운데 그림 10명, 작은 그림 1명.","식혜 줄은 10명 그림 2개와 1명 그림 6개 — 10 × 2 + 1 × 6 = 26.","식혜를 좋아하는 학생은 26명이에요."],"asset":{"type":"picg","title":"좋아하는 우리나라 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜","잡채"],"counts":[130,115,100,26,40],"units":[100,10,1],"icon":"🍚","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 잡채를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["40"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 100명, 가운데 그림 10명, 작은 그림 1명.","잡채 줄은 10명 그림 4개 — 10 × 4 = 40.","잡채를 좋아하는 학생은 40명이에요."],"asset":{"type":"picg","title":"좋아하는 우리나라 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜","잡채"],"counts":[130,115,100,26,40],"units":[100,10,1],"icon":"🍚","unit":"명","vh":"학생 수"}},{"stem":"그림그래프를 보고 불고기를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["115"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 100명, 가운데 그림 10명, 작은 그림 1명.","불고기 줄은 100명 그림 1개, 10명 그림 1개, 1명 그림 5개 — 100 × 1 + 10 × 1 + 1 × 5 = 115.","불고기를 좋아하는 학생은 115명이에요."],"asset":{"type":"picg","title":"좋아하는 우리나라 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜","잡채"],"counts":[130,115,100,26,40],"units":[100,10,1],"icon":"🍚","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_basic#6','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C3',2,'mc','auto','그림그래프에서 불고기를 좋아하는 학생보다 더 많은 학생이 좋아하는 음식은 무엇인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X03']::text[],false,'{"seq":6,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"그림그래프에서 불고기를 좋아하는 학생보다 더 많은 학생이 좋아하는 음식은 무엇인가요?","options":[{"t":"떡국","correct":true},{"t":"식혜","mis":"M3-2-u6-X04"},{"t":"비빔밥","mis":"M3-2-u6-X03"},{"t":"잡채","mis":"M3-2-u6-X03"}],"explanation":["불고기를 좋아하는 학생은 100명 그림 1개, 10명 그림 1개, 1명 그림 5개 — 100 × 1 + 10 × 1 + 1 × 5 = 115예요.","115명보다 많은 것은 떡국 130명뿐이에요 — 식혜는 그림이 8개여도 26명이에요.","답은 떡국이에요."],"asset":{"type":"picg","title":"좋아하는 우리나라 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜","잡채"],"counts":[130,115,100,26,40],"units":[100,10,1],"icon":"🍚","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_basic#7','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',2,'sa','auto','콩나물을 좋아하는 학생은 35명이에요. 10명·1명 그림으로 나타낼 때 1명 그림은 몇 개를 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u6-C4","difficulty":2,"kind":"sa","stem":"콩나물을 좋아하는 학생은 35명이에요. 10명·1명 그림으로 나타낼 때 1명 그림은 몇 개를 그려야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["큰 수를 나타내는 그림부터 그려요.","35명 = 10명 그림 3개와 1명 그림 5개.","1명 그림은 5개예요."],"variant_rule":{"alt":[{"stem":"오이를 좋아하는 학생은 24명이에요. 10명·1명 그림으로 나타낼 때 1명 그림은 몇 개를 그려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["큰 수를 나타내는 그림부터 그려요.","24명 = 10명 그림 2개와 1명 그림 4개.","1명 그림은 4개예요."]},{"stem":"시금치를 좋아하는 학생은 10명이에요. 10명·1명 그림으로 나타낼 때 1명 그림은 몇 개를 그려야 하나요? 숫자로 쓰세요.","answer":["0"],"explanation":["큰 수를 나타내는 그림부터 그려요.","10명 = 10명 그림 1개와 1명 그림 0개.","1명 그림은 0개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_basic#8','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C5',2,'mc','auto','지유네 학교 영양 선생님께서 급식으로 우리나라 전통 음식을 한 가지 준비하려고 해요. 그림그래프를 보고 고른 음식과 까닭이 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X17']::text[],false,'{"seq":8,"concept":"M3-2-u6-C5","difficulty":2,"kind":"mc","stem":"지유네 학교 영양 선생님께서 급식으로 우리나라 전통 음식을 한 가지 준비하려고 해요. 그림그래프를 보고 고른 음식과 까닭이 알맞은 것은 어느 것인가요?","options":[{"t":"떡국 — 가장 많은 학생이 좋아하는 우리나라 전통 음식이기 때문이에요","correct":true},{"t":"식혜 — 그림이 가장 많이 그려져 있기 때문이에요","mis":"M3-2-u6-X04"},{"t":"비빔밥 — 그림이 하나뿐이라 가장 간단하기 때문이에요","mis":"M3-2-u6-X17"},{"t":"잡채 — 식혜보다 적은 학생이 좋아하기 때문이에요","mis":"M3-2-u6-X17"}],"explanation":["떡국 130명, 불고기 115명, 비빔밥 100명, 잡채 40명, 식혜 26명이에요.","떡국이 가장 많은 학생이 좋아하는 음식이에요.","그림그래프에서 읽은 사실로 까닭을 대요 — 떡국을 준비하면 좋아요."],"asset":{"type":"picg","title":"좋아하는 우리나라 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜","잡채"],"counts":[130,115,100,26,40],"units":[100,10,1],"icon":"🍚","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_basic#9','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C4',2,'mc','auto','좋아하는 채소별 학생 수를 두 가지 그림으로 나타내려고 해요. 표를 보고 그림의 단위로 가장 알맞은 것을 고르세요.',ARRAY['M3-2-u6-X02','M3-2-u6-X06']::text[],false,'{"seq":9,"concept":"M3-2-u6-C4","difficulty":2,"kind":"mc","stem":"좋아하는 채소별 학생 수를 두 가지 그림으로 나타내려고 해요. 표를 보고 그림의 단위로 가장 알맞은 것을 고르세요.","options":[{"t":"10명, 1명","correct":true},{"t":"100명, 10명","mis":"M3-2-u6-X02"},{"t":"1명 한 가지","mis":"M3-2-u6-X06"},{"t":"10명, 5명","mis":"M3-2-u6-X02"}],"explanation":["자료의 수가 모두 100보다 작은 두 자리 수예요.","10명 그림과 1명 그림이면 십의 자리는 큰 그림, 일의 자리는 작은 그림으로 나타낼 수 있어요.","100명 그림으로는 18명을 나타낼 수 없고, 1명 그림만 쓰면 콩나물은 35개나 그려야 해요."],"asset":{"type":"picg","only":"table","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[18,10,24,35],"unit":"명","vh":"학생 수","title":"좋아하는 채소별 학생 수","total":87}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_basic#10','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_basic','lesson_basic','M3-2-u6-C5',3,'mc','auto','마을별 밤 생산량을 나타낸 그림그래프예요. 밤 생산량이 ㉡ 마을보다 많고 ㉢ 마을보다 적은 곳은 어느 마을인가요?',ARRAY['M3-2-u6-X16','M3-2-u6-X04','M3-2-u6-X03']::text[],false,'{"seq":10,"concept":"M3-2-u6-C5","difficulty":3,"kind":"mc","stem":"마을별 밤 생산량을 나타낸 그림그래프예요. 밤 생산량이 ㉡ 마을보다 많고 ㉢ 마을보다 적은 곳은 어느 마을인가요?","options":[{"t":"㉠","correct":true},{"t":"㉣","mis":"M3-2-u6-X16"},{"t":"㉡","mis":"M3-2-u6-X04"},{"t":"㉢","mis":"M3-2-u6-X03"}],"explanation":["㉠ 23개, ㉡ 16개, ㉢ 31개, ㉣ 32개예요.","㉡ 16개보다 많고 ㉢ 31개보다 적은 수는 23개예요 — ㉣ 32개는 ㉢보다 많아요.","답은 ㉠ 마을이에요 — ㉡은 그림이 7개로 가장 많아도 16개예요."],"asset":{"type":"picg","title":"마을별 밤 생산량","head":"마을","cols":["㉠","㉡","㉢","㉣"],"counts":[23,16,31,32],"units":[10,1],"icon":"🌰","unit":"개","vh":"밤 생산량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_challenge#1','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C4',2,'mc','auto','시금치를 좋아하는 학생은 23명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],true,'{"seq":1,"concept":"M3-2-u6-C4","difficulty":2,"kind":"mc","stem":"시금치를 좋아하는 학생은 23명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"10명 그림 2개, 1명 그림 3개","correct":true},{"t":"10명 그림 3개, 1명 그림 2개","mis":"M3-2-u6-X05"},{"t":"1명 그림 23개","mis":"M3-2-u6-X06"},{"t":"10명 그림 3개, 1명 그림 3개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","23명 안에 10명이 2번 들어가요 — 남은 3명은 1명 그림으로 나타내요.","답은 10명 그림 2개, 1명 그림 3개예요."],"variant_rule":{"alt":[{"stem":"콩나물을 좋아하는 학생은 28명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"10명 그림 2개, 1명 그림 8개","correct":true},{"t":"10명 그림 8개, 1명 그림 2개","mis":"M3-2-u6-X05"},{"t":"1명 그림 28개","mis":"M3-2-u6-X06"},{"t":"10명 그림 3개, 1명 그림 8개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","28명 안에 10명이 2번 들어가요 — 남은 8명은 1명 그림으로 나타내요.","답은 10명 그림 2개, 1명 그림 8개예요."]},{"stem":"당근을 좋아하는 학생은 14명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"10명 그림 1개, 1명 그림 4개","correct":true},{"t":"10명 그림 4개, 1명 그림 1개","mis":"M3-2-u6-X05"},{"t":"1명 그림 14개","mis":"M3-2-u6-X06"},{"t":"10명 그림 2개, 1명 그림 4개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","14명 안에 10명이 1번 들어가요 — 남은 4명은 1명 그림으로 나타내요.","답은 10명 그림 1개, 1명 그림 4개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_challenge#2','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 파랑을 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 파랑을 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["15"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","파랑 줄은 10명 그림 1개와 1명 그림 5개 — 10 × 1 + 1 × 5 = 15.","파랑을 좋아하는 학생은 15명이에요."],"asset":{"type":"picg","title":"좋아하는 색깔별 학생 수","head":"색깔","cols":["노랑","분홍","초록","파랑"],"counts":[41,21,22,15],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 노랑을 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["41"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","노랑 줄은 10명 그림 4개와 1명 그림 1개 — 10 × 4 + 1 × 1 = 41.","노랑을 좋아하는 학생은 41명이에요."],"asset":{"type":"picg","title":"좋아하는 색깔별 학생 수","head":"색깔","cols":["노랑","분홍","초록","파랑"],"counts":[41,21,22,15],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}},{"stem":"그림그래프를 보고 분홍을 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["21"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","분홍 줄은 10명 그림 2개와 1명 그림 1개 — 10 × 2 + 1 × 1 = 21.","분홍을 좋아하는 학생은 21명이에요."],"asset":{"type":"picg","title":"좋아하는 색깔별 학생 수","head":"색깔","cols":["노랑","분홍","초록","파랑"],"counts":[41,21,22,15],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_challenge#3','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C3',3,'mc','auto','도윤이네 학교 3학년 학생들이 좋아하는 색깔을 조사한 그림그래프예요. 그림그래프를 보고 알 수 있는 내용으로 옳은 것은 어느 것인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X01','M3-2-u6-X03']::text[],false,'{"seq":3,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"도윤이네 학교 3학년 학생들이 좋아하는 색깔을 조사한 그림그래프예요. 그림그래프를 보고 알 수 있는 내용으로 옳은 것은 어느 것인가요?","options":[{"t":"초록을 좋아하는 학생은 분홍을 좋아하는 학생보다 1명 더 많아요","correct":true},{"t":"파랑을 좋아하는 학생이 가장 많아요","mis":"M3-2-u6-X04"},{"t":"노랑을 좋아하는 학생은 5명이에요","mis":"M3-2-u6-X01"},{"t":"분홍과 초록을 좋아하는 학생 수는 같아요","mis":"M3-2-u6-X03"}],"explanation":["노랑 41명, 분홍 21명, 초록 22명, 파랑 15명이에요.","22 − 21 = 1 — 초록이 분홍보다 1명 더 많아요.","파랑은 그림이 6개로 가장 많지만 15명으로 가장 적어요."],"asset":{"type":"picg","title":"좋아하는 색깔별 학생 수","head":"색깔","cols":["노랑","분홍","초록","파랑"],"counts":[41,21,22,15],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_challenge#4','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C5',3,'mc','auto','도윤이네 학교 3학년 학생들이 단체 티셔츠를 만들려고 해요. 그림그래프를 보고 어떤 색깔로 만드는 것이 좋을지 까닭과 함께 바르게 고른 것은 어느 것인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X17']::text[],false,'{"seq":4,"concept":"M3-2-u6-C5","difficulty":3,"kind":"mc","stem":"도윤이네 학교 3학년 학생들이 단체 티셔츠를 만들려고 해요. 그림그래프를 보고 어떤 색깔로 만드는 것이 좋을지 까닭과 함께 바르게 고른 것은 어느 것인가요?","options":[{"t":"노랑 — 가장 많은 학생이 좋아하는 색깔이기 때문이에요","correct":true},{"t":"파랑 — 그림이 가장 많이 그려져 있기 때문이에요","mis":"M3-2-u6-X04"},{"t":"분홍 — 초록보다 좋아하는 학생이 많기 때문이에요","mis":"M3-2-u6-X17"},{"t":"초록 — 노랑보다 좋아하는 학생이 많기 때문이에요","mis":"M3-2-u6-X17"}],"explanation":["노랑 41명이 가장 많아요.","분홍(21명)은 초록(22명)보다 적고, 초록은 노랑보다 적어요.","그림그래프에서 읽은 사실로 까닭을 대요 — 노랑으로 만들어요."],"asset":{"type":"picg","title":"좋아하는 색깔별 학생 수","head":"색깔","cols":["노랑","분홍","초록","파랑"],"counts":[41,21,22,15],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_challenge#5','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C4',3,'mc','auto','가입한 동아리별 학생 수를 표로 정리하고, 친구가 그림그래프로 나타냈어요. 잘못 그린 줄은 어느 것인가요?',ARRAY['M3-2-u6-X13']::text[],false,'{"seq":5,"concept":"M3-2-u6-C4","difficulty":3,"kind":"mc","stem":"가입한 동아리별 학생 수를 표로 정리하고, 친구가 그림그래프로 나타냈어요. 잘못 그린 줄은 어느 것인가요?","options":[{"t":"민속놀이","correct":true},{"t":"독서","mis":"M3-2-u6-X13"},{"t":"종이접기","mis":"M3-2-u6-X13"},{"t":"잘못 그린 줄이 없어요","mis":"M3-2-u6-X13"}],"explanation":["10명 그림은 십의 자리, 1명 그림은 일의 자리 수만큼 그려요.","민속놀이 24명은 10명 그림 2개, 1명 그림 4개인데 10명 그림 4개, 1명 그림 2개로 바꾸어 그렸어요 — 42명이 돼요.","다 그린 뒤 표와 같은지 줄마다 확인해요."],"asset":{"type":"picg","title":"가입한 동아리별 학생 수","head":"동아리","cols":["독서","민속놀이","종이접기"],"counts":[35,24,44],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","pieces":[[3,5],[4,2],[4,4]],"table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_challenge#6','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C3',3,'sa','auto','그림그래프를 보고 떡볶이 일 인분에 들어 있는 각설탕은 도넛 한 개에 들어 있는 각설탕보다 몇 개 더 많은지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u6-C3","difficulty":3,"kind":"sa","stem":"그림그래프를 보고 떡볶이 일 인분에 들어 있는 각설탕은 도넛 한 개에 들어 있는 각설탕보다 몇 개 더 많은지 구하세요. 숫자로 쓰세요.","answer":["12"],"explanation":["두 항목의 수를 먼저 읽어요 — 떡볶이 일 인분 17개, 도넛 한 개 5개.","몇 개 더 많은지는 뺄셈으로 구해요.","17 − 5 = 12 — 12개 더 많아요."],"asset":{"type":"picg","title":"음식별 들어 있는 각설탕의 수","head":"음식","cols":["도넛 한 개","떡볶이 일 인분","콜라 한 캔"],"counts":[5,17,9],"units":[10,1],"icon":"■","unit":"개","vh":"각설탕의 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 콜라 한 캔에 들어 있는 각설탕은 도넛 한 개에 들어 있는 각설탕보다 몇 개 더 많은지 구하세요. 숫자로 쓰세요.","answer":["4"],"explanation":["두 항목의 수를 먼저 읽어요 — 콜라 한 캔 9개, 도넛 한 개 5개.","몇 개 더 많은지는 뺄셈으로 구해요.","9 − 5 = 4 — 4개 더 많아요."],"asset":{"type":"picg","title":"음식별 들어 있는 각설탕의 수","head":"음식","cols":["도넛 한 개","떡볶이 일 인분","콜라 한 캔"],"counts":[5,17,9],"units":[10,1],"icon":"■","unit":"개","vh":"각설탕의 수"}},{"stem":"그림그래프를 보고 떡볶이 일 인분에 들어 있는 각설탕은 콜라 한 캔에 들어 있는 각설탕보다 몇 개 더 많은지 구하세요. 숫자로 쓰세요.","answer":["8"],"explanation":["두 항목의 수를 먼저 읽어요 — 떡볶이 일 인분 17개, 콜라 한 캔 9개.","몇 개 더 많은지는 뺄셈으로 구해요.","17 − 9 = 8 — 8개 더 많아요."],"asset":{"type":"picg","title":"음식별 들어 있는 각설탕의 수","head":"음식","cols":["도넛 한 개","떡볶이 일 인분","콜라 한 캔"],"counts":[5,17,9],"units":[10,1],"icon":"■","unit":"개","vh":"각설탕의 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_challenge#7','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C4',3,'mc','auto','당근을 좋아하는 학생 18명을 10명·5명·1명의 세 가지 그림으로 나타내려고 해요. 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u6-X06','M3-2-u6-X02']::text[],false,'{"seq":7,"concept":"M3-2-u6-C4","difficulty":3,"kind":"mc","stem":"당근을 좋아하는 학생 18명을 10명·5명·1명의 세 가지 그림으로 나타내려고 해요. 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10명 그림 1개, 5명 그림 1개, 1명 그림 3개","correct":true},{"t":"10명 그림 1개, 1명 그림 8개","mis":"M3-2-u6-X06"},{"t":"5명 그림 3개, 1명 그림 3개","mis":"M3-2-u6-X06"},{"t":"10명 그림 1개, 5명 그림 3개","mis":"M3-2-u6-X02"}],"explanation":["그림그래프의 그림은 3가지로 나타낼 수도 있어요 — 큰 그림부터 그려요.","18 안에 10이 1번, 남은 8 안에 5가 1번, 남은 3은 1명 그림 3개예요.","10 × 1 + 5 × 1 + 1 × 3 = 18 — 세 가지 그림을 모두 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_challenge#8','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C4',4,'sa','auto','4학년 학생은 92명이에요. 50명·10명·1명의 세 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u6-C4","difficulty":4,"kind":"sa","stem":"4학년 학생은 92명이에요. 50명·10명·1명의 세 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["큰 수를 나타내는 그림부터 그려요.","92명 = 50명 그림 1개, 10명 그림 4개, 1명 그림 2개.","1 + 4 + 2 = 7 — 그림은 모두 7개예요."],"variant_rule":{"alt":[{"stem":"3학년 학생은 110명이에요. 50명·10명·1명의 세 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["큰 수를 나타내는 그림부터 그려요.","110명 = 50명 그림 2개, 10명 그림 1개, 1명 그림 0개.","2 + 1 + 0 = 3 — 그림은 모두 3개예요."]},{"stem":"6학년 학생은 101명이에요. 50명·10명·1명의 세 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["큰 수를 나타내는 그림부터 그려요.","101명 = 50명 그림 2개, 10명 그림 0개, 1명 그림 1개.","2 + 0 + 1 = 3 — 그림은 모두 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_challenge#9','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C5',4,'essay','teacher','지유네 학교 학생들이 좋아하는 우리나라 전통 음식 그림그래프를 보고 알 수 있는 내용을 두 가지 쓰고, 학생들이 좋아하는 차례대로 음식을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u6-C5","difficulty":4,"kind":"essay","stem":"지유네 학교 학생들이 좋아하는 우리나라 전통 음식 그림그래프를 보고 알 수 있는 내용을 두 가지 쓰고, 학생들이 좋아하는 차례대로 음식을 써 보세요.","answer_guide":{"answer":"예: 가장 많은 학생이 좋아하는 음식은 떡국(130명)이다. 가장 적은 학생이 좋아하는 음식은 식혜(26명)이다. 좋아하는 차례: 떡국 130명, 불고기 115명, 비빔밥 100명, 잡채 40명, 식혜 26명.","scoring_points":["100명·10명·1명 그림으로 수를 바르게 읽었는가","알 수 있는 내용을 두 가지 썼는가","떡국, 불고기, 비빔밥, 잡채, 식혜 차례로 썼는가"]},"explanation":["그림의 단위는 100명, 10명, 1명이에요.","떡국 130, 불고기 115, 비빔밥 100, 잡채 40, 식혜 26이에요.","큰 그림부터 견주면 떡국, 불고기, 비빔밥, 잡채, 식혜 차례예요."],"asset":{"type":"picg","title":"좋아하는 우리나라 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜","잡채"],"counts":[130,115,100,26,40],"units":[100,10,1],"icon":"🍚","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L03_challenge#10','math',3,2,'u6','L03','tb_g3_2_math_u6_L03_challenge','lesson_challenge','M3-2-u6-C3',4,'sa','auto','그림그래프를 보고 떡국을 좋아하는 학생은 식혜를 좋아하는 학생보다 몇 명 더 많은지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u6-C3","difficulty":4,"kind":"sa","stem":"그림그래프를 보고 떡국을 좋아하는 학생은 식혜를 좋아하는 학생보다 몇 명 더 많은지 구하세요. 숫자로 쓰세요.","answer":["104"],"explanation":["두 항목의 수를 먼저 읽어요 — 떡국 130명, 식혜 26명.","몇 개 더 많은지는 뺄셈으로 구해요.","130 − 26 = 104 — 104명 더 많아요."],"asset":{"type":"picg","title":"좋아하는 우리나라 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜","잡채"],"counts":[130,115,100,26,40],"units":[100,10,1],"icon":"🍚","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 불고기를 좋아하는 학생은 잡채를 좋아하는 학생보다 몇 명 더 많은지 구하세요. 숫자로 쓰세요.","answer":["75"],"explanation":["두 항목의 수를 먼저 읽어요 — 불고기 115명, 잡채 40명.","몇 개 더 많은지는 뺄셈으로 구해요.","115 − 40 = 75 — 75명 더 많아요."],"asset":{"type":"picg","title":"좋아하는 우리나라 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜","잡채"],"counts":[130,115,100,26,40],"units":[100,10,1],"icon":"🍚","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_basic#1','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',1,'blank','auto','「조사 방법에는 직접 손 들기, 투표하기, □, 돌아다니며 묻기 등이 있습니다.」 □에 알맞은 것은 무엇인가요?',ARRAY['M3-2-u6-X12']::text[],false,'{"seq":1,"concept":"M3-2-u6-C6","difficulty":1,"kind":"blank","stem":"「조사 방법에는 직접 손 들기, 투표하기, □, 돌아다니며 묻기 등이 있습니다.」 □에 알맞은 것은 무엇인가요?","options":[{"t":"붙임딱지 붙이기","correct":true},{"t":"그림그래프 그리기","mis":"M3-2-u6-X12"},{"t":"표로 나타내기","mis":"M3-2-u6-X12"},{"t":"제목 쓰기","mis":"M3-2-u6-X12"}],"explanation":["조사 방법은 자료를 모으는 방법이에요.","직접 손 들기, 투표하기, 붙임딱지 붙이기, 돌아다니며 묻기 등이 있어요.","표나 그림그래프는 자료를 모은 다음에 나타내는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_basic#2','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',1,'mc','auto','자료를 수집하여 그림그래프로 나타낼 때 가장 먼저 하는 일은 무엇인가요?',ARRAY['M3-2-u6-X12']::text[],false,'{"seq":2,"concept":"M3-2-u6-C6","difficulty":1,"kind":"mc","stem":"자료를 수집하여 그림그래프로 나타낼 때 가장 먼저 하는 일은 무엇인가요?","options":[{"t":"알아보고 싶은 주제와 대상을 정하고, 그에 따른 항목을 정해요","correct":true},{"t":"표를 보고 그림그래프로 나타내요","mis":"M3-2-u6-X12"},{"t":"수집한 자료를 표로 나타내요","mis":"M3-2-u6-X12"},{"t":"조사 방법을 정해 자료를 수집해요","mis":"M3-2-u6-X12"}],"explanation":["① 주제와 대상·항목 정하기 ② 조사 방법을 정해 자료 수집하기","③ 수집한 자료를 표로 나타내기 ④ 표를 보고 그림그래프로 나타내고 해석하기","무엇을 누구에게 조사할지부터 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_basic#3','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',1,'mc','auto','건강한 생활 습관에 대해 조사할 항목을 정하려고 해요. 그림그래프로 알맞게 나타낼 수 있도록 항목은 몇 개 사이로 정하면 좋을까요?',ARRAY['M3-2-u6-X10']::text[],false,'{"seq":3,"concept":"M3-2-u6-C6","difficulty":1,"kind":"mc","stem":"건강한 생활 습관에 대해 조사할 항목을 정하려고 해요. 그림그래프로 알맞게 나타낼 수 있도록 항목은 몇 개 사이로 정하면 좋을까요?","options":[{"t":"4개에서 6개 사이","correct":true},{"t":"1개에서 2개 사이","mis":"M3-2-u6-X10"},{"t":"10개 넘게 되도록 많이","mis":"M3-2-u6-X10"},{"t":"항목은 정하지 않아도 돼요","mis":"M3-2-u6-X10"}],"explanation":["항목은 조사한 것을 나누는 칸이에요.","항목이 너무 적으면 견줄 것이 없고, 너무 많으면 그림그래프로 나타내기 어려워요.","교과서처럼 4개에서 6개 사이로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_basic#4','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',1,'mc','auto','3학년 학생들이 방과 후 음악 활동 시간에 배우고 싶어 하는 악기를 조사하여 표로 나타냈어요. 조사한 주제는 무엇인가요?',ARRAY['M3-2-u6-X10']::text[],true,'{"seq":4,"concept":"M3-2-u6-C6","difficulty":1,"kind":"mc","stem":"3학년 학생들이 방과 후 음악 활동 시간에 배우고 싶어 하는 악기를 조사하여 표로 나타냈어요. 조사한 주제는 무엇인가요?","options":[{"t":"배우고 싶어 하는 악기","correct":true},{"t":"3학년 학생들","mis":"M3-2-u6-X10"},{"t":"방과 후 음악 활동 시간","mis":"M3-2-u6-X10"},{"t":"플루트","mis":"M3-2-u6-X10"}],"explanation":["주제는 「무엇을 조사했는지」, 대상은 「누구에게 조사했는지」예요.","배우고 싶어 하는 악기를 3학년 학생들에게 조사했어요.","주제는 배우고 싶어 하는 악기, 대상은 3학년 학생들이에요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[24,25,18,30],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수","total":97},"variant_rule":{"alt":[{"stem":"3학년 학생들이 방과 후 음악 활동 시간에 배우고 싶어 하는 악기를 조사하여 표로 나타냈어요. 조사한 대상은 누구인가요?","options":[{"t":"3학년 학생들","correct":true},{"t":"배우고 싶어 하는 악기","mis":"M3-2-u6-X10"},{"t":"가야금","mis":"M3-2-u6-X10"},{"t":"음악 선생님","mis":"M3-2-u6-X10"}],"explanation":["주제는 「무엇을 조사했는지」, 대상은 「누구에게 조사했는지」예요.","배우고 싶어 하는 악기를 3학년 학생들에게 조사했어요.","대상은 3학년 학생들이에요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[24,25,18,30],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수","total":97}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_basic#5','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',2,'mc','auto','두 학생의 대화를 읽고 자료를 수집하기 위해 어떤 방법을 사용했는지 고르세요.',ARRAY['M3-2-u6-X11']::text[],false,'{"seq":5,"concept":"M3-2-u6-C6","difficulty":2,"kind":"mc","stem":"두 학생의 대화를 읽고 자료를 수집하기 위해 어떤 방법을 사용했는지 고르세요.","options":[{"t":"투표하기","correct":true},{"t":"직접 손 들기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"},{"t":"돌아다니며 묻기","mis":"M3-2-u6-X11"}],"explanation":["「여러 사람의 의견을 동시에 수집」하고 「의견을 적은 종이를 넣을 상자」를 준비했어요.","의견을 종이에 적어 상자에 넣는 방법은 투표하기예요.","투표하기는 투표용지와 연필 같은 준비물이 필요해요."],"asset":{"type":"speech","turns":[{"who":"한 친구","text":"여러 사람의 의견을 동시에 수집할 수 있으면 좋겠어."},{"who":"다른 친구","text":"3학년 교실이 있는 복도에 의견을 적은 종이를 넣을 수 있는 상자를 준비하자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_basic#6','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',2,'mc','auto','조사 주제를 정할 때 주의할 점을 생각하며, 알맞은 조사 주제를 고르세요.',ARRAY['M3-2-u6-X10']::text[],false,'{"seq":6,"concept":"M3-2-u6-C6","difficulty":2,"kind":"mc","stem":"조사 주제를 정할 때 주의할 점을 생각하며, 알맞은 조사 주제를 고르세요.","options":[{"t":"우리 모둠 학생들이 한 달 동안 운동한 횟수","correct":true},{"t":"우리나라 사람 모두가 좋아하는 음식","mis":"M3-2-u6-X10"},{"t":"건강","mis":"M3-2-u6-X10"},{"t":"다음 달에 비가 몇 번 올지","mis":"M3-2-u6-X10"}],"explanation":["직접 자료를 수집할 수 있는 주제인지 확인해요.","무엇을 조사하는지 분명하게 알 수 있는 주제를 정해요.","「건강」은 무엇을 조사하는지 분명하지 않고, 우리나라 사람 모두는 직접 물어보기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_basic#7','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',2,'mc','auto','우리 모둠 학생들이 한 달 동안 운동한 횟수를 조사하려고 해요. 교과서에서 고른 조사 방법은 무엇인가요?',ARRAY['M3-2-u6-X11']::text[],false,'{"seq":7,"concept":"M3-2-u6-C6","difficulty":2,"kind":"mc","stem":"우리 모둠 학생들이 한 달 동안 운동한 횟수를 조사하려고 해요. 교과서에서 고른 조사 방법은 무엇인가요?","options":[{"t":"돌아다니며 묻기","correct":true},{"t":"직접 손 들기","mis":"M3-2-u6-X11"},{"t":"투표하기","mis":"M3-2-u6-X11"},{"t":"붙임딱지 붙이기","mis":"M3-2-u6-X11"}],"explanation":["대상이 우리 모둠 학생들처럼 적은 사람이에요.","한 사람씩 찾아가 운동한 횟수를 직접 물어볼 수 있어요.","그래서 돌아다니며 묻기를 골랐어요 — 궁금한 점도 바로 알려 줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_basic#8','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',2,'ox','auto','「3학년 학생 전체를 대상으로 조사할 때는 직접 손 들기가 가장 알맞은 방법이다.」 맞으면 ○, 틀리면 ×를 고르세요.',ARRAY['M3-2-u6-X11']::text[],false,'{"seq":8,"concept":"M3-2-u6-C6","difficulty":2,"kind":"ox","stem":"「3학년 학생 전체를 대상으로 조사할 때는 직접 손 들기가 가장 알맞은 방법이다.」 맞으면 ○, 틀리면 ×를 고르세요.","answer":"X","reason_options":[{"t":"많은 사람을 동시에 조사하기 어려워서 투표하기·붙임딱지 붙이기 같은 다른 방법이 알맞아요","correct":true},{"t":"준비물이 없으니 언제나 직접 손 들기가 가장 좋아요","mis":"M3-2-u6-X11"}],"mis":"M3-2-u6-X11","explanation":["직접 손 들기는 준비물 없이 적절한 수의 학생들을 동시에 조사할 수 있어요.","하지만 3학년 학생, 전교생처럼 많은 사람을 동시에 조사하기는 어려워요.","많은 학생을 조사할 때는 다른 방법을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_basic#9','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',2,'match','auto','조사 방법과 그 방법의 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u6-C6","difficulty":2,"kind":"match","stem":"조사 방법과 그 방법의 특징을 알맞게 이으세요.","pairs":[{"l":"직접 손 들기","r":"준비물 없이 바로 자료를 모을 수 있어요"},{"l":"투표하기","r":"투표용지가 필요하고, 기권표나 무효표가 나올 수 있어요"},{"l":"붙임딱지 붙이기","r":"붙임딱지와 붙일 판을 미리 준비해요"},{"l":"돌아다니며 묻기","r":"궁금한 점을 바로 알려 줄 수 있지만, 많은 사람이면 시간이 오래 걸려요"}],"mis":"M3-2-u6-X11","explanation":["방법마다 하는 일을 떠올려요.","투표하기는 투표용지, 붙임딱지 붙이기는 붙임딱지와 판이 필요해요.","돌아다니며 묻기는 직접 묻는 만큼 많은 사람이면 시간이 오래 걸려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_basic#10','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_basic','lesson_basic','M3-2-u6-C6',3,'mc','auto','3학년 학생들을 대상으로 하루 동안 손을 씻는 횟수를 조사하려고 해요. 항목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u6-X10']::text[],false,'{"seq":10,"concept":"M3-2-u6-C6","difficulty":3,"kind":"mc","stem":"3학년 학생들을 대상으로 하루 동안 손을 씻는 횟수를 조사하려고 해요. 항목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"손을 씻는 횟수를 몇 회씩 묶어 4~5개로 정한 것","correct":true},{"t":"3학년 학생 모두의 이름","mis":"M3-2-u6-X10"},{"t":"비누와 물","mis":"M3-2-u6-X10"},{"t":"손을 씻는 까닭","mis":"M3-2-u6-X10"}],"explanation":["항목은 조사한 내용을 나누는 칸이에요.","손을 씻는 횟수를 항목으로 정해 횟수별 학생 수를 조사해요.","3학년 학생 모두의 이름은 항목이 너무 많아 그림그래프로 나타내기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_challenge#1','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',2,'mc','auto','모둠마다 주제·대상·조사 방법을 정했어요. 대상에 맞게 조사 방법을 알맞게 고른 모둠은 어느 것인가요?',ARRAY['M3-2-u6-X11','M3-2-u6-X12']::text[],false,'{"seq":1,"concept":"M3-2-u6-C6","difficulty":2,"kind":"mc","stem":"모둠마다 주제·대상·조사 방법을 정했어요. 대상에 맞게 조사 방법을 알맞게 고른 모둠은 어느 것인가요?","options":[{"t":"주제: 좋아하는 건강식품 — 대상: 모둠 친구들 — 방법: 직접 손 들기","correct":true},{"t":"주제: 일주일 동안 운동한 횟수 — 대상: 3학년 학생 — 방법: 직접 손 들기","mis":"M3-2-u6-X11"},{"t":"주제: 하루 동안 손을 씻는 횟수 — 대상: 3학년 학생 — 방법: 돌아다니며 묻기","mis":"M3-2-u6-X11"},{"t":"주제: 좋아하는 건강식품 — 대상: 모둠 친구들 — 방법: 아무 방법 없이 짐작하기","mis":"M3-2-u6-X12"}],"explanation":["모둠 친구들처럼 적은 사람은 직접 손 들기로 바로 모을 수 있어요.","3학년 학생처럼 많은 사람은 손 들기·돌아다니며 묻기가 어려워요 — 붙임딱지 붙이기나 투표하기가 알맞아요.","자료는 짐작하지 않고 직접 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_challenge#2','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',2,'mc','auto','「우리 반 학생들이 가장 잘 실천하고 있는 건강한 생활 습관」을 투표하기로 조사하려고 해요. 개표할 때 주의할 점으로 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u6-X11']::text[],false,'{"seq":2,"concept":"M3-2-u6-C6","difficulty":2,"kind":"mc","stem":"「우리 반 학생들이 가장 잘 실천하고 있는 건강한 생활 습관」을 투표하기로 조사하려고 해요. 개표할 때 주의할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"표를 잘못 세지 않고, 뜻을 알아보기 힘든 표는 기권표로 나누어요","correct":true},{"t":"알아보기 힘든 표는 많이 나온 습관에 넣어요","mis":"M3-2-u6-X11"},{"t":"투표용지는 세지 않고 눈으로 어림해요","mis":"M3-2-u6-X11"},{"t":"투표하기는 안내 없이 바로 시작해요","mis":"M3-2-u6-X11"}],"explanation":["투표하기는 기권이나 무효표가 많이 나올 수 있어요.","사전에 투표 방법을 자세히 안내하고, 개표할 때 표를 잘못 세지 않아요.","뜻을 알아보기 힘든 표는 기권표로 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_challenge#3','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',3,'mc','auto','「일주일 동안 운동한 횟수」를 3학년 학생들에게 붙임딱지 붙이기로 조사하려고 해요. 미리 준비할 일로 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u6-X11']::text[],false,'{"seq":3,"concept":"M3-2-u6-C6","difficulty":3,"kind":"mc","stem":"「일주일 동안 운동한 횟수」를 3학년 학생들에게 붙임딱지 붙이기로 조사하려고 해요. 미리 준비할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"조사 내용을 잘 알 수 있게 안내문을 만들고, 알맞은 수의 붙임딱지와 붙일 판을 준비해요","correct":true},{"t":"투표용지와 투표함을 준비해요","mis":"M3-2-u6-X11"},{"t":"한 사람씩 찾아가 물어볼 순서를 정해요","mis":"M3-2-u6-X11"},{"t":"손을 든 학생 수를 셀 사람을 정해요","mis":"M3-2-u6-X11"}],"explanation":["붙임딱지 붙이기는 붙임딱지와 붙임딱지를 붙일 판을 미리 준비해요.","무엇을 조사하는지 안내 사항을 미리 알려야 해요.","투표함은 투표하기, 찾아가 묻기는 돌아다니며 묻기에서 준비하는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_challenge#4','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',3,'essay','teacher','건강한 생활 습관에 대해 알아보고 싶은 주제와 대상을 정하고, 그에 따른 항목과 조사 방법을 정해 보세요. 그 방법을 고른 까닭도 써 보세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u6-C6","difficulty":3,"kind":"essay","stem":"건강한 생활 습관에 대해 알아보고 싶은 주제와 대상을 정하고, 그에 따른 항목과 조사 방법을 정해 보세요. 그 방법을 고른 까닭도 써 보세요.","answer_guide":{"answer":"예: 주제 — 한 달 동안 운동한 횟수, 대상 — 우리 모둠 학생, 항목 — 우리 모둠 학생들의 이름(건우, 서준, 은비, 지유), 방법 — 돌아다니며 묻기. 까닭: 대상이 우리 모둠 학생들이라 한 사람씩 직접 물어볼 수 있기 때문이다.","scoring_points":["직접 모을 수 있고 분명한 주제와 대상을 정했는가","항목을 4~6개 정도로 정했는가","대상에 맞는 조사 방법과 까닭을 썼는가"]},"explanation":["주제는 직접 모을 수 있고 무엇을 조사하는지 분명하게 정해요.","항목은 4개에서 6개 사이로 정해요.","대상이 적으면 손 들기·돌아다니며 묻기, 많으면 투표하기·붙임딱지 붙이기가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_challenge#5','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',3,'sa','auto','3학년 학생들이 배우고 싶어 하는 악기를 조사하여 표로 나타냈어요. 우쿨렐레를 배우고 싶어 하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M3-2-u6-C6","difficulty":3,"kind":"sa","stem":"3학년 학생들이 배우고 싶어 하는 악기를 조사하여 표로 나타냈어요. 우쿨렐레를 배우고 싶어 하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["합계 97명은 네 악기의 학생 수를 모두 더한 수예요.","모르는 수 = 합계 − 아는 수예요.","97 − 24 − 25 − 30 = 18 — 우쿨렐레는 18명이에요."],"asset":{"type":"picg","only":"table","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[24,25,null,30],"unit":"명","vh":"학생 수","title":"배우고 싶어 하는 악기별 학생 수","total":97}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_challenge#6','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',3,'mc','auto','자료를 수집하여 그림그래프로 나타내는 차례로 바른 것은 어느 것인가요?',ARRAY['M3-2-u6-X12']::text[],false,'{"seq":6,"concept":"M3-2-u6-C6","difficulty":3,"kind":"mc","stem":"자료를 수집하여 그림그래프로 나타내는 차례로 바른 것은 어느 것인가요?","options":[{"t":"주제·대상·항목 정하기 → 조사 방법 정해 자료 수집하기 → 표로 나타내기 → 그림그래프로 나타내고 해석하기","correct":true},{"t":"그림그래프로 나타내기 → 주제·대상·항목 정하기 → 자료 수집하기 → 표로 나타내기","mis":"M3-2-u6-X12"},{"t":"자료 수집하기 → 주제·대상·항목 정하기 → 그림그래프로 나타내기 → 표로 나타내기","mis":"M3-2-u6-X12"},{"t":"표로 나타내기 → 자료 수집하기 → 주제·대상·항목 정하기 → 그림그래프로 나타내기","mis":"M3-2-u6-X12"}],"explanation":["무엇을 누구에게 조사할지 먼저 정해요.","정한 방법으로 자료를 모아 표로 정리해요.","표를 보고 그림그래프로 나타내고, 알 수 있는 내용을 해석해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_challenge#7','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',3,'error','auto','모둠 친구들이 조사 주제와 항목을 정하며 이야기했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u6-X10','M3-2-u6-X16']::text[],false,'{"seq":7,"concept":"M3-2-u6-C6","difficulty":3,"kind":"error","stem":"모둠 친구들이 조사 주제와 항목을 정하며 이야기했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「항목은 많을수록 좋으니 되도록 많이 나누자」","correct":true,"mis_target":"M3-2-u6-X10"},{"t":"서윤 — 「우리가 직접 자료를 모을 수 있는 주제인지 확인하자」","mis":"M3-2-u6-X16"},{"t":"도윤 — 「무엇을 조사하는지 분명하게 알 수 있는 주제로 정하자」","mis":"M3-2-u6-X16"}],"explanation":["주제는 직접 모을 수 있고, 무엇을 조사하는지 분명해야 해요.","항목을 너무 많이 나누면 그림그래프로 알맞게 나타내기 어려워요.","잘못 말한 친구는 지아예요 — 항목은 4개에서 6개 사이로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_challenge#8','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',4,'essay','teacher','3학년 학생들을 대상으로 조사하려고 해요. 직접 손 들기와 돌아다니며 묻기가 왜 알맞지 않은지 쓰고, 어떤 방법으로 조사하면 좋을지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u6-C6","difficulty":4,"kind":"essay","stem":"3학년 학생들을 대상으로 조사하려고 해요. 직접 손 들기와 돌아다니며 묻기가 왜 알맞지 않은지 쓰고, 어떤 방법으로 조사하면 좋을지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 3학년 학생은 수가 많아서 직접 손 들기로는 동시에 모으기 어렵고, 돌아다니며 묻기는 시간이 오래 걸린다. 그래서 붙임딱지 붙이기(또는 투표하기)로 조사한다 — 판과 붙임딱지(투표용지)를 준비해 두면 여러 사람의 의견을 한꺼번에 모을 수 있기 때문이다.","scoring_points":["직접 손 들기가 많은 사람에게 어려운 까닭을 썼는가","돌아다니며 묻기는 시간이 오래 걸린다고 썼는가","붙임딱지 붙이기나 투표하기를 까닭과 함께 골랐는가"]},"explanation":["직접 손 들기는 많은 사람을 동시에 조사하기 어려워요.","돌아다니며 묻기는 많은 사람을 조사할 때 시간이 오래 걸려요.","많은 학생은 붙임딱지 붙이기나 투표하기로 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_challenge#9','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',4,'essay','teacher','돌아다니며 묻기로 자료를 모을 때 좋은 점과 어려운 점을 한 가지씩 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u6-C6","difficulty":4,"kind":"essay","stem":"돌아다니며 묻기로 자료를 모을 때 좋은 점과 어려운 점을 한 가지씩 써 보세요.","answer_guide":{"answer":"좋은 점: 자료 수집에 대해 궁금한 점이나 관련 정보를 바로 알려 줄 수 있다. 어려운 점: 3학년 학생, 전교생처럼 많은 사람을 대상으로 하면 시간이 오래 걸린다.","scoring_points":["좋은 점(궁금한 점을 바로 알려 줄 수 있음)을 썼는가","어려운 점(많은 사람이면 시간이 오래 걸림)을 썼는가","방법의 특징에 맞게 썼는가"]},"explanation":["돌아다니며 묻기는 한 사람씩 직접 물어요.","물어보는 사람이 궁금한 점을 바로 설명해 줄 수 있어요.","하지만 대상이 많으면 시간이 오래 걸려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L04_challenge#10','math',3,2,'u6','L04','tb_g3_2_math_u6_L04_challenge','lesson_challenge','M3-2-u6-C6',4,'mc','auto','학급에서 쉬는 시간에 할 활동을 정하려고 학생 몇 명에게만 물어보았어요. 이 조사의 문제로 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u6-X10','M3-2-u6-X19']::text[],false,'{"seq":10,"concept":"M3-2-u6-C6","difficulty":4,"kind":"mc","stem":"학급에서 쉬는 시간에 할 활동을 정하려고 학생 몇 명에게만 물어보았어요. 이 조사의 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"몇 명의 생각은 전체 학생이 원하는 것을 모두 담지 못해요 — 모두에게 물을 수 있으면 모두에게 물어요","correct":true},{"t":"몇 명에게만 물으면 결과가 더 정확해요","mis":"M3-2-u6-X10"},{"t":"적게 물을수록 그림그래프가 예뻐져요","mis":"M3-2-u6-X19"},{"t":"물어본 사람 수는 결과와 상관이 없어요","mis":"M3-2-u6-X10"}],"explanation":["조사 대상이 반 전체라면 반 학생 모두의 생각을 알아야 해요.","몇몇에게만 물으면 그 학생들의 생각만 담겨요.","전체에게 물을 수 있을 때는 전체에게 물어 자료를 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_basic#1','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',1,'sa','auto','우리 모둠 학생들이 한 달 동안 운동한 횟수를 조사하여 표로 나타냈어요. 4명의 학생이 한 달 동안 운동한 횟수는 모두 몇 회인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u6-C7","difficulty":1,"kind":"sa","stem":"우리 모둠 학생들이 한 달 동안 운동한 횟수를 조사하여 표로 나타냈어요. 4명의 학생이 한 달 동안 운동한 횟수는 모두 몇 회인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["합계는 조사한 수를 모두 더한 수예요.","건우 11회, 서준 22회, 은비 13회, 지유 9회예요.","11 + 22 + 13 + 9 = 55 — 모두 55회예요."],"asset":{"type":"picg","only":"table","head":"이름","cols":["건우","서준","은비","지유"],"counts":[11,22,13,9],"unit":"회","vh":"횟수","title":"학생별 한 달 동안 운동한 횟수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_basic#2','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',1,'mc','auto','서준이 한 달 동안 운동한 횟수는 22회예요. 5회·1회의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],true,'{"seq":2,"concept":"M3-2-u6-C7","difficulty":1,"kind":"mc","stem":"서준이 한 달 동안 운동한 횟수는 22회예요. 5회·1회의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"5회 그림 4개, 1회 그림 2개","correct":true},{"t":"5회 그림 2개, 1회 그림 4개","mis":"M3-2-u6-X05"},{"t":"1회 그림 22개","mis":"M3-2-u6-X06"},{"t":"5회 그림 5개, 1회 그림 2개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","22회 안에 5회가 4번 들어가요 — 남은 2회는 1회 그림으로 나타내요.","답은 5회 그림 4개, 1회 그림 2개예요."],"variant_rule":{"alt":[{"stem":"은비가 한 달 동안 운동한 횟수는 13회예요. 5회·1회의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"5회 그림 2개, 1회 그림 3개","correct":true},{"t":"5회 그림 3개, 1회 그림 2개","mis":"M3-2-u6-X05"},{"t":"1회 그림 13개","mis":"M3-2-u6-X06"},{"t":"5회 그림 3개, 1회 그림 3개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","13회 안에 5회가 2번 들어가요 — 남은 3회는 1회 그림으로 나타내요.","답은 5회 그림 2개, 1회 그림 3개예요."]},{"stem":"건우가 한 달 동안 운동한 횟수는 11회예요. 5회·1회의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"5회 그림 2개, 1회 그림 1개","correct":true},{"t":"5회 그림 1개, 1회 그림 2개","mis":"M3-2-u6-X05"},{"t":"1회 그림 11개","mis":"M3-2-u6-X06"},{"t":"5회 그림 3개, 1회 그림 1개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","11회 안에 5회가 2번 들어가요 — 남은 1회는 1회 그림으로 나타내요.","답은 5회 그림 2개, 1회 그림 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_basic#3','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',1,'mc','auto','그림그래프에서 한 달 동안 운동을 가장 적게 한 학생은 누구인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16','M3-2-u6-X03']::text[],true,'{"seq":3,"concept":"M3-2-u6-C7","difficulty":1,"kind":"mc","stem":"그림그래프에서 한 달 동안 운동을 가장 적게 한 학생은 누구인가요?","options":[{"t":"지유","correct":true},{"t":"건우","mis":"M3-2-u6-X04"},{"t":"서준","mis":"M3-2-u6-X16"},{"t":"은비","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","건우 11회, 서준 22회, 은비 13회, 지유 9회.","가장 적은 것은 지유예요."],"asset":{"type":"picg","title":"학생별 한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[11,22,13,9],"units":[5,1],"icon":"■","unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"그림그래프에서 한 달 동안 운동을 가장 많이 한 학생은 누구인가요?","options":[{"t":"서준","correct":true},{"t":"건우","mis":"M3-2-u6-X03"},{"t":"은비","mis":"M3-2-u6-X03"},{"t":"지유","mis":"M3-2-u6-X16"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","건우 11회, 서준 22회, 은비 13회, 지유 9회.","가장 많은 것은 서준이에요."],"asset":{"type":"picg","title":"학생별 한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[11,22,13,9],"units":[5,1],"icon":"■","unit":"회","vh":"횟수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_basic#4','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',1,'mc','auto','표를 보고 그림그래프로 다 나타낸 뒤 무엇을 확인해야 하나요?',ARRAY['M3-2-u6-X19','M3-2-u6-X15','M3-2-u6-X13']::text[],false,'{"seq":4,"concept":"M3-2-u6-C7","difficulty":1,"kind":"mc","stem":"표를 보고 그림그래프로 다 나타낸 뒤 무엇을 확인해야 하나요?","options":[{"t":"조사한 내용을 빠짐없이 나타냈는지, 그림이 나타내는 수의 합이 표의 합계와 같은지","correct":true},{"t":"그림을 여러 가지 색깔로 예쁘게 칠했는지","mis":"M3-2-u6-X19"},{"t":"그림을 되도록 크게 그렸는지","mis":"M3-2-u6-X15"},{"t":"확인하지 않아도 돼요","mis":"M3-2-u6-X13"}],"explanation":["그림그래프는 조사한 내용과 일치하도록 그려야 해요.","항목이 빠지지 않았는지, 그림이 나타내는 수의 합이 표의 합계와 같은지 확인해요.","그림을 예쁘게 꾸미는 것보다 수를 바르게 나타내는 것이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_basic#5','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',2,'sa','auto','그림그래프를 보고 은비가 한 달 동안 운동한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u6-C7","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 은비가 한 달 동안 운동한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.","answer":["13"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 5회, 작은 그림 1회.","은비 줄은 5회 그림 2개와 1회 그림 3개 — 5 × 2 + 1 × 3 = 13.","은비가 한 달 동안 운동한 횟수는 13회예요."],"asset":{"type":"picg","title":"학생별 한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[11,22,13,9],"units":[5,1],"icon":"■","unit":"회","vh":"횟수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 건우가 한 달 동안 운동한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.","answer":["11"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 5회, 작은 그림 1회.","건우 줄은 5회 그림 2개와 1회 그림 1개 — 5 × 2 + 1 × 1 = 11.","건우가 한 달 동안 운동한 횟수는 11회예요."],"asset":{"type":"picg","title":"학생별 한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[11,22,13,9],"units":[5,1],"icon":"■","unit":"회","vh":"횟수"}},{"stem":"그림그래프를 보고 지유가 한 달 동안 운동한 횟수는 몇 회인지 구하세요. 숫자로 쓰세요.","answer":["9"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 5회, 작은 그림 1회.","지유 줄은 5회 그림 1개와 1회 그림 4개 — 5 × 1 + 1 × 4 = 9.","지유가 한 달 동안 운동한 횟수는 9회예요."],"asset":{"type":"picg","title":"학생별 한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[11,22,13,9],"units":[5,1],"icon":"■","unit":"회","vh":"횟수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_basic#6','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',2,'mc','auto','배우고 싶어 하는 악기별 학생 수를 그림그래프로 나타냈어요. 가장 적은 학생이 배우고 싶어 하는 악기는 무엇인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X04']::text[],false,'{"seq":6,"concept":"M3-2-u6-C7","difficulty":2,"kind":"mc","stem":"배우고 싶어 하는 악기별 학생 수를 그림그래프로 나타냈어요. 가장 적은 학생이 배우고 싶어 하는 악기는 무엇인가요?","options":[{"t":"우쿨렐레","correct":true},{"t":"가야금","mis":"M3-2-u6-X03"},{"t":"오카리나","mis":"M3-2-u6-X03"},{"t":"플루트","mis":"M3-2-u6-X04"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","가야금 24명, 오카리나 25명, 우쿨렐레 18명, 플루트 30명.","가장 적은 것은 우쿨렐레예요."],"asset":{"type":"picg","title":"배우고 싶어 하는 악기별 학생 수","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[24,25,18,30],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_basic#7','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',2,'mc','auto','우쿨렐레를 배우고 싶어 하는 학생은 18명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],true,'{"seq":7,"concept":"M3-2-u6-C7","difficulty":2,"kind":"mc","stem":"우쿨렐레를 배우고 싶어 하는 학생은 18명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"10명 그림 1개, 1명 그림 8개","correct":true},{"t":"10명 그림 8개, 1명 그림 1개","mis":"M3-2-u6-X05"},{"t":"1명 그림 18개","mis":"M3-2-u6-X06"},{"t":"10명 그림 2개, 1명 그림 8개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","18명 안에 10명이 1번 들어가요 — 남은 8명은 1명 그림으로 나타내요.","답은 10명 그림 1개, 1명 그림 8개예요."],"variant_rule":{"alt":[{"stem":"가야금을 배우고 싶어 하는 학생은 24명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"10명 그림 2개, 1명 그림 4개","correct":true},{"t":"10명 그림 4개, 1명 그림 2개","mis":"M3-2-u6-X05"},{"t":"1명 그림 24개","mis":"M3-2-u6-X06"},{"t":"10명 그림 3개, 1명 그림 4개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","24명 안에 10명이 2번 들어가요 — 남은 4명은 1명 그림으로 나타내요.","답은 10명 그림 2개, 1명 그림 4개예요."]},{"stem":"오카리나를 배우고 싶어 하는 학생은 25명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"10명 그림 2개, 1명 그림 5개","correct":true},{"t":"10명 그림 5개, 1명 그림 2개","mis":"M3-2-u6-X05"},{"t":"1명 그림 25개","mis":"M3-2-u6-X06"},{"t":"10명 그림 3개, 1명 그림 5개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","25명 안에 10명이 2번 들어가요 — 남은 5명은 1명 그림으로 나타내요.","답은 10명 그림 2개, 1명 그림 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_basic#8','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',2,'mc','auto','모둠 친구가 표(건우 11회, 서준 22회, 은비 13회, 지유 9회, 합계 55회)를 보고 그림그래프로 나타냈어요. 잘못된 점은 무엇인가요?',ARRAY['M3-2-u6-X13','M3-2-u6-X02']::text[],false,'{"seq":8,"concept":"M3-2-u6-C7","difficulty":2,"kind":"mc","stem":"모둠 친구가 표(건우 11회, 서준 22회, 은비 13회, 지유 9회, 합계 55회)를 보고 그림그래프로 나타냈어요. 잘못된 점은 무엇인가요?","options":[{"t":"은비 줄이 빠졌어요 — 그림이 나타내는 수의 합 42회가 표의 합계 55회와 달라요","correct":true},{"t":"서준 줄의 그림을 잘못 그렸어요","mis":"M3-2-u6-X13"},{"t":"그림의 단위를 잘못 정했어요","mis":"M3-2-u6-X02"},{"t":"잘못된 곳이 없어요","mis":"M3-2-u6-X13"}],"explanation":["표에는 건우·서준·은비·지유 네 명이 있어요.","그림그래프에는 은비 줄이 없어요 — 11 + 22 + 9 = 42예요.","42회는 표의 합계 55회와 달라요 — 조사한 내용을 빠짐없이 나타냈는지 확인해요."],"asset":{"type":"picg","title":"학생별 한 달 동안 운동한 횟수(친구가 그린 그림그래프)","head":"이름","cols":["건우","서준","지유"],"counts":[11,22,9],"units":[5,1],"icon":"■","unit":"회","vh":"횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_basic#9','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',2,'mc','auto','좋아하는 계절별 학생 수를 조사하여 그림그래프로 나타냈어요. 가장 많은 학생이 좋아하는 계절은 언제인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X16','M3-2-u6-X04']::text[],false,'{"seq":9,"concept":"M3-2-u6-C7","difficulty":2,"kind":"mc","stem":"좋아하는 계절별 학생 수를 조사하여 그림그래프로 나타냈어요. 가장 많은 학생이 좋아하는 계절은 언제인가요?","options":[{"t":"여름","correct":true},{"t":"봄","mis":"M3-2-u6-X03"},{"t":"가을","mis":"M3-2-u6-X16"},{"t":"겨울","mis":"M3-2-u6-X04"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","봄 7명, 여름 10명, 가을 5명, 겨울 8명.","가장 많은 것은 여름이에요."],"asset":{"type":"picg","title":"좋아하는 계절별 학생 수","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,10,5,8],"units":[5,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_basic#10','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_basic','lesson_basic','M3-2-u6-C7',3,'sa','auto','표를 보고 5명·1명의 단위로 그림그래프를 그리려고 해요. 그림은 모두 몇 개 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u6-C7","difficulty":3,"kind":"sa","stem":"표를 보고 5명·1명의 단위로 그림그래프를 그리려고 해요. 그림은 모두 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["11"],"explanation":["줄마다 큰 그림부터 그림 수를 셈해요.","감 3개, 배 6개, 사과 2개예요.","3 + 6 + 2 = 11 — 모두 11개예요."],"asset":{"type":"picg","only":"table","head":"과일","cols":["감","배","사과"],"counts":[11,14,6],"unit":"명","vh":"학생 수","title":"좋아하는 과일별 학생 수","total":31},"variant_rule":{"alt":[{"stem":"표를 보고 5회·1회의 단위로 그림그래프를 그리려고 해요. 그림은 모두 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["19"],"explanation":["줄마다 큰 그림부터 그림 수를 셈해요.","건우 3개, 서준 6개, 은비 5개, 지유 5개예요.","3 + 6 + 5 + 5 = 19 — 모두 19개예요."],"asset":{"type":"picg","only":"table","head":"이름","cols":["건우","서준","은비","지유"],"counts":[11,22,13,9],"unit":"회","vh":"횟수","title":"학생별 한 달 동안 운동한 횟수","total":55}},{"stem":"이번에는 다른 그림그래프예요. 표를 보고 5명·1명의 단위로 그림그래프를 그리려고 해요. 그림은 모두 몇 개 그려야 하나요? 숫자로 쓰세요.","answer":["10"],"explanation":["줄마다 큰 그림부터 그림 수를 셈해요.","봄 3개, 여름 2개, 가을 1개, 겨울 4개예요.","3 + 2 + 1 + 4 = 10 — 모두 10개예요."],"asset":{"type":"picg","only":"table","head":"계절","cols":["봄","여름","가을","겨울"],"counts":[7,10,5,8],"unit":"명","vh":"학생 수","title":"좋아하는 계절별 학생 수","total":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_challenge#1','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',2,'mc','auto','수집한 자료를 그림그래프로 나타낼 때 그림은 어떻게 정하면 좋을까요?',ARRAY['M3-2-u6-X19','M3-2-u6-X15']::text[],false,'{"seq":1,"concept":"M3-2-u6-C7","difficulty":2,"kind":"mc","stem":"수집한 자료를 그림그래프로 나타낼 때 그림은 어떻게 정하면 좋을까요?","options":[{"t":"무엇에 대한 그림그래프인지 한눈에 알 수 있는 그림으로 정해요","correct":true},{"t":"자세하고 예쁜 여러 가지 그림을 섞어 그려요","mis":"M3-2-u6-X19"},{"t":"조사한 내용과 상관없이 그리기 쉬운 그림이면 돼요","mis":"M3-2-u6-X19"},{"t":"그림을 크게 그릴수록 좋아요","mis":"M3-2-u6-X15"}],"explanation":["그림을 보고 무엇을 조사했는지 바로 알 수 있으면 좋아요.","그림을 지나치게 세밀하게 그리는 것보다 수를 바르게 나타내는 것이 중요해요.","한 그래프에서는 같은 그림을 쓰고 크기로 단위를 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_challenge#2','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C5',2,'mc','auto','방과 후 음악 활동 시간에 배울 악기를 하나 고르려고 해요. 그림그래프를 보고 고른 악기와 까닭이 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X17']::text[],false,'{"seq":2,"concept":"M3-2-u6-C5","difficulty":2,"kind":"mc","stem":"방과 후 음악 활동 시간에 배울 악기를 하나 고르려고 해요. 그림그래프를 보고 고른 악기와 까닭이 알맞은 것은 어느 것인가요?","options":[{"t":"플루트 — 가장 많은 학생이 배우고 싶어 하는 악기이기 때문이에요","correct":true},{"t":"우쿨렐레 — 그림이 가장 많이 그려져 있기 때문이에요","mis":"M3-2-u6-X04"},{"t":"가야금 — 오카리나보다 배우고 싶어 하는 학생이 많기 때문이에요","mis":"M3-2-u6-X17"},{"t":"오카리나 — 이름이 가장 길기 때문이에요","mis":"M3-2-u6-X17"}],"explanation":["가야금 24명, 오카리나 25명, 우쿨렐레 18명, 플루트 30명이에요.","플루트가 가장 많은 학생이 배우고 싶어 하는 악기예요.","가야금(24명)은 오카리나(25명)보다 적어요 — 그림그래프에서 읽은 사실로 까닭을 대요."],"asset":{"type":"picg","title":"배우고 싶어 하는 악기별 학생 수","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[24,25,18,30],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_challenge#3','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',3,'sa','auto','그림그래프를 보고 플루트를 배우고 싶어 하는 학생은 우쿨렐레를 배우고 싶어 하는 학생보다 몇 명 더 많은지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u6-C7","difficulty":3,"kind":"sa","stem":"그림그래프를 보고 플루트를 배우고 싶어 하는 학생은 우쿨렐레를 배우고 싶어 하는 학생보다 몇 명 더 많은지 구하세요. 숫자로 쓰세요.","answer":["12"],"explanation":["두 항목의 수를 먼저 읽어요 — 플루트 30명, 우쿨렐레 18명.","몇 개 더 많은지는 뺄셈으로 구해요.","30 − 18 = 12 — 12명 더 많아요."],"asset":{"type":"picg","title":"배우고 싶어 하는 악기별 학생 수","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[24,25,18,30],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 오카리나를 배우고 싶어 하는 학생은 가야금을 배우고 싶어 하는 학생보다 몇 명 더 많은지 구하세요. 숫자로 쓰세요.","answer":["1"],"explanation":["두 항목의 수를 먼저 읽어요 — 오카리나 25명, 가야금 24명.","몇 개 더 많은지는 뺄셈으로 구해요.","25 − 24 = 1 — 1명 더 많아요."],"asset":{"type":"picg","title":"배우고 싶어 하는 악기별 학생 수","head":"악기","cols":["가야금","오카리나","우쿨렐레","플루트"],"counts":[24,25,18,30],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_challenge#4','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',3,'mc','auto','그림그래프는 자료의 수뿐만 아니라 무엇도 함께 나타낼 수 있나요? 지도에 마을별 초등학생 수를 그림으로 나타낸 그림그래프를 생각해 보세요.',ARRAY['M3-2-u6-X18']::text[],false,'{"seq":4,"concept":"M3-2-u6-C7","difficulty":3,"kind":"mc","stem":"그림그래프는 자료의 수뿐만 아니라 무엇도 함께 나타낼 수 있나요? 지도에 마을별 초등학생 수를 그림으로 나타낸 그림그래프를 생각해 보세요.","options":[{"t":"마을의 위치","correct":true},{"t":"마을 사람들의 이름","mis":"M3-2-u6-X18"},{"t":"초등학생의 키","mis":"M3-2-u6-X18"},{"t":"마을이 생긴 해","mis":"M3-2-u6-X18"}],"explanation":["지도 위에 마을별 초등학생 수를 그림으로 나타낼 수 있어요.","그러면 초등학생이 사는 마을의 위치와 초등학생 수를 함께 알 수 있어요.","그림그래프는 자료의 수뿐만 아니라 위치도 함께 나타낼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_challenge#5','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',3,'ox','auto','「한 달 동안 운동한 횟수 그림그래프에서 건우와 은비는 5회 그림이 2개씩으로 같으니 운동한 횟수도 같다.」 맞으면 ○, 틀리면 ×를 고르세요.',ARRAY['M3-2-u6-X03']::text[],false,'{"seq":5,"concept":"M3-2-u6-C7","difficulty":3,"kind":"ox","stem":"「한 달 동안 운동한 횟수 그림그래프에서 건우와 은비는 5회 그림이 2개씩으로 같으니 운동한 횟수도 같다.」 맞으면 ○, 틀리면 ×를 고르세요.","answer":"X","reason_options":[{"t":"5회 그림은 2개씩 같지만 1회 그림이 1개, 3개로 달라 11회와 13회예요","correct":true},{"t":"큰 그림의 개수가 같으면 나타내는 수도 같아요","mis":"M3-2-u6-X03"}],"mis":"M3-2-u6-X03","explanation":["건우는 5회 그림 2개와 1회 그림 1개 — 5 × 2 + 1 × 1 = 11이에요.","은비는 5회 그림 2개와 1회 그림 3개 — 5 × 2 + 1 × 3 = 13이에요.","큰 그림이 같으면 작은 그림까지 견줘요 — 은비가 2회 더 많아요."],"asset":{"type":"picg","title":"학생별 한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[11,22,13,9],"units":[5,1],"icon":"■","unit":"회","vh":"횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_challenge#6','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',3,'sa','auto','좋아하는 계절별 학생 수를 조사했더니 모두 30명이었어요. 그림그래프에 나타낸 봄·여름·가을의 학생 수가 7명, 10명, 5명이라면 겨울을 좋아하는 학생은 몇 명이어야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u6-C7","difficulty":3,"kind":"sa","stem":"좋아하는 계절별 학생 수를 조사했더니 모두 30명이었어요. 그림그래프에 나타낸 봄·여름·가을의 학생 수가 7명, 10명, 5명이라면 겨울을 좋아하는 학생은 몇 명이어야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["그림이 나타내는 수의 합은 표의 합계와 같아야 해요.","모르는 수 = 합계 − 아는 수예요.","30 − 7 − 10 − 5 = 8 — 겨울은 8명이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_challenge#7','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',3,'essay','teacher','한 달 동안 운동한 횟수 그림그래프를 보고 알 수 있는 내용을 두 가지 써 보세요.','{}'::text[],false,'{"seq":7,"concept":"M3-2-u6-C7","difficulty":3,"kind":"essay","stem":"한 달 동안 운동한 횟수 그림그래프를 보고 알 수 있는 내용을 두 가지 써 보세요.","answer_guide":{"answer":"예: 한 달 동안 운동을 가장 많이 한 학생은 서준(22회)이다. 가장 적게 한 학생은 지유(9회)이다. 서준이는 지유보다 13회 더 운동했다.","scoring_points":["5회·1회 그림으로 횟수를 바르게 읽었는가","가장 많이(적게) 한 학생을 찾았는가","알 수 있는 내용을 두 가지 썼는가"]},"explanation":["그림의 단위는 5회, 1회예요.","건우 11회, 서준 22회, 은비 13회, 지유 9회예요.","22 − 9 = 13 — 서준이가 지유보다 13회 더 많이 운동했어요."],"asset":{"type":"picg","title":"학생별 한 달 동안 운동한 횟수","head":"이름","cols":["건우","서준","은비","지유"],"counts":[11,22,13,9],"units":[5,1],"icon":"■","unit":"회","vh":"횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_challenge#8','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',4,'essay','teacher','우리 모둠 학생들이 한 달 동안 운동한 횟수(건우 11회, 서준 22회, 은비 13회, 지유 9회)를 그림그래프로 나타내려고 해요. 그림의 단위를 얼마로 하면 좋을지 정하고 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u6-C7","difficulty":4,"kind":"essay","stem":"우리 모둠 학생들이 한 달 동안 운동한 횟수(건우 11회, 서준 22회, 은비 13회, 지유 9회)를 그림그래프로 나타내려고 해요. 그림의 단위를 얼마로 하면 좋을지 정하고 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 5회와 1회로 정한다. 10회와 1회로 하면 지유는 1회 그림 9개를 그려야 하고, 5회와 1회로 하면 그림 수가 알맞아(건우 3개, 서준 6개, 은비 5개, 지유 5개) 그리기도 견주기도 쉽기 때문이다.","scoring_points":["그림의 단위(예 5회·1회)를 정했는가","자료의 수에 맞게 그림 수가 알맞다는 까닭을 썼는가","정한 단위로 그림 수를 바르게 셈했는가"]},"explanation":["자료의 수에 따라 그림이 나타내는 단위를 알맞게 정해요.","5회·1회로 하면 건우 3개, 서준 6개, 은비 5개, 지유 5개예요.","그림이 너무 많거나 적지 않게 단위를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_challenge#9','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C7',4,'sa','auto','좋아하는 계절별 학생 수(봄 7명, 여름 10명, 가을 5명, 겨울 8명)를 10명·1명으로 나타낼 때와 5명·1명으로 나타낼 때를 견주어 보세요. 5명·1명으로 나타내면 그림을 몇 개 더 적게 그릴 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u6-C7","difficulty":4,"kind":"sa","stem":"좋아하는 계절별 학생 수(봄 7명, 여름 10명, 가을 5명, 겨울 8명)를 10명·1명으로 나타낼 때와 5명·1명으로 나타낼 때를 견주어 보세요. 5명·1명으로 나타내면 그림을 몇 개 더 적게 그릴 수 있나요? 숫자로 쓰세요.","answer":["11"],"explanation":["10명·1명이면 봄 7개, 여름 1개, 가을 5개, 겨울 8개 — 7 + 1 + 5 + 8 = 21이에요.","5명·1명이면 봄 3개, 여름 2개, 가을 1개, 겨울 4개 — 3 + 2 + 1 + 4 = 10이에요.","21 − 10 = 11 — 11개 더 적게 그릴 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L05_challenge#10','math',3,2,'u6','L05','tb_g3_2_math_u6_L05_challenge','lesson_challenge','M3-2-u6-C5',4,'essay','teacher','모둠별로 조사하여 나타낸 그림그래프를 발표했어요. 조사한 내용을 바탕으로 앞으로 건강한 생활 습관을 어떻게 실천하면 좋을지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u6-C5","difficulty":4,"kind":"essay","stem":"모둠별로 조사하여 나타낸 그림그래프를 발표했어요. 조사한 내용을 바탕으로 앞으로 건강한 생활 습관을 어떻게 실천하면 좋을지 써 보세요.","answer_guide":{"answer":"예: 우리 모둠은 한 달 동안 운동한 횟수가 가장 적은 지유가 9회였다. 앞으로 모두 꾸준히 운동하는 습관을 실천해야겠다. 손 씻기를 조사한 모둠의 그림그래프를 보고 식사하기 전, 밖에서 들어온 뒤 틈틈이 손을 깨끗이 씻어야겠다.","scoring_points":["그림그래프에서 알게 된 사실을 썼는가","그 사실에 맞는 실천 방법을 썼는가","건강한 생활 습관과 이어서 썼는가"]},"explanation":["그림그래프에서 알게 된 사실을 먼저 말해요.","그 사실을 근거로 실천할 일을 정해요.","예: 규칙적인 운동, 음식 골고루 먹기, 틈틈이 손 씻기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_basic#1','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C8',1,'sa','auto','겨울의 산불 발생 건수는 268건이에요. 10건·1건 그림으로 나타낼 때 10건 그림은 몇 개를 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u6-C8","difficulty":1,"kind":"sa","stem":"겨울의 산불 발생 건수는 268건이에요. 10건·1건 그림으로 나타낼 때 10건 그림은 몇 개를 그려야 하나요? 숫자로 쓰세요.","answer":["26"],"explanation":["큰 수를 나타내는 그림부터 그려요.","268건 = 10건 그림 26개와 1건 그림 8개.","10건 그림은 26개예요."],"variant_rule":{"alt":[{"stem":"겨울의 산불 발생 건수는 268건이에요. 10건·1건 그림으로 나타낼 때 1건 그림은 몇 개를 그려야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["큰 수를 나타내는 그림부터 그려요.","268건 = 10건 그림 26개와 1건 그림 8개.","1건 그림은 8개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_basic#2','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C8',1,'sa','auto','겨울의 산불 발생 건수는 268건이에요. 100건·10건·1건 그림으로 나타낼 때 100건 그림은 몇 개를 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u6-C8","difficulty":1,"kind":"sa","stem":"겨울의 산불 발생 건수는 268건이에요. 100건·10건·1건 그림으로 나타낼 때 100건 그림은 몇 개를 그려야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["큰 수를 나타내는 그림부터 그려요.","268건 = 100건 그림 2개, 10건 그림 6개, 1건 그림 8개.","100건 그림은 2개예요."],"variant_rule":{"alt":[{"stem":"겨울의 산불 발생 건수는 268건이에요. 100건·10건·1건 그림으로 나타낼 때 10건 그림은 몇 개를 그려야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["큰 수를 나타내는 그림부터 그려요.","268건 = 100건 그림 2개, 10건 그림 6개, 1건 그림 8개.","10건 그림은 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_basic#3','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C8',1,'mc','auto','2022년 계절별 산불 발생 건수를 가(10건·1건)와 나(100건·10건·1건) 두 그림그래프로 나타냈어요. 두 그림그래프의 같은 점은 무엇인가요?',ARRAY['M3-2-u6-X14']::text[],false,'{"seq":3,"concept":"M3-2-u6-C8","difficulty":1,"kind":"mc","stem":"2022년 계절별 산불 발생 건수를 가(10건·1건)와 나(100건·10건·1건) 두 그림그래프로 나타냈어요. 두 그림그래프의 같은 점은 무엇인가요?","options":[{"t":"산불 발생 건수를 나타내는 그림이 같아요","correct":true},{"t":"단위의 종류가 같아요","mis":"M3-2-u6-X14"},{"t":"그림의 개수가 같아요","mis":"M3-2-u6-X14"},{"t":"나타내는 산불 발생 건수가 달라요","mis":"M3-2-u6-X14"}],"explanation":["두 그림그래프는 같은 표를 보고 그렸어요 — 나타내는 건수는 같아요.","산불 발생 건수를 나타내는 그림이 같아요.","가는 두 가지, 나는 세 가지 단위를 써서 그림의 개수는 달라요."],"asset":{"type":"picg","title":"2022년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"건수","units2":[100,10,1],"table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_basic#4','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C5',1,'mc','auto','2022년 계절별 산불 발생 건수 그림그래프를 보고 산불이 가장 많이 발생한 계절을 고르세요.',ARRAY['M3-2-u6-X16','M3-2-u6-X03']::text[],false,'{"seq":4,"concept":"M3-2-u6-C5","difficulty":1,"kind":"mc","stem":"2022년 계절별 산불 발생 건수 그림그래프를 보고 산불이 가장 많이 발생한 계절을 고르세요.","options":[{"t":"봄(3, 4, 5월)","correct":true},{"t":"여름(6, 7, 8월)","mis":"M3-2-u6-X16"},{"t":"겨울(12, 1, 2월)","mis":"M3-2-u6-X03"},{"t":"가을(9, 10, 11월)","mis":"M3-2-u6-X03"}],"explanation":["봄 377건, 여름 29건, 가을 82건, 겨울 268건이에요.","나 그림그래프에서 100건 그림이 가장 많은 계절이 봄이에요.","산불이 가장 많이 발생한 계절은 봄(3, 4, 5월)이에요."],"asset":{"type":"picg","title":"2022년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"건수","units2":[100,10,1],"table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_basic#5','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C8',2,'mc','auto','가와 나 그림그래프의 다른 점은 무엇인가요?',ARRAY['M3-2-u6-X14','M3-2-u6-X13']::text[],false,'{"seq":5,"concept":"M3-2-u6-C8","difficulty":2,"kind":"mc","stem":"가와 나 그림그래프의 다른 점은 무엇인가요?","options":[{"t":"단위의 종류가 달라요 — 가는 10건·1건, 나는 100건·10건·1건이에요","correct":true},{"t":"나타내는 산불 발생 건수가 달라요","mis":"M3-2-u6-X14"},{"t":"그림의 모양이 달라요","mis":"M3-2-u6-X14"},{"t":"나 그림그래프에 계절이 하나 빠졌어요","mis":"M3-2-u6-X13"}],"explanation":["두 그림그래프는 그림이 같아요.","가는 단위가 두 가지, 나는 세 가지예요.","같은 표를 나타냈으니 계절별 건수는 같아요."],"asset":{"type":"picg","title":"2022년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"건수","units2":[100,10,1],"table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_basic#6','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C8',2,'mc','auto','그림그래프에서 단위의 종류가 늘어나면 편리한 점은 무엇인가요?',ARRAY['M3-2-u6-X14']::text[],true,'{"seq":6,"concept":"M3-2-u6-C8","difficulty":2,"kind":"mc","stem":"그림그래프에서 단위의 종류가 늘어나면 편리한 점은 무엇인가요?","options":[{"t":"큰 수를 적은 그림으로 효과적으로 나타낼 수 있어요","correct":true},{"t":"그림의 크기를 구분하여 그리기 쉬워요","mis":"M3-2-u6-X14"},{"t":"그림을 더 많이 그려야 해요","mis":"M3-2-u6-X14"},{"t":"나타내는 수가 더 커져요","mis":"M3-2-u6-X14"}],"explanation":["봄 377건은 가에서 그림 44개, 나에서 그림 17개예요.","단위의 종류가 늘면 큰 수를 효과적으로 나타낼 수 있어요.","하지만 단위의 종류를 명확히 구분하여 그리기 어려운 점은 불편해요."],"asset":{"type":"picg","title":"2022년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"건수","units2":[100,10,1],"table":true},"variant_rule":{"alt":[{"stem":"그림그래프에서 단위의 종류가 늘어나면 불편한 점은 무엇인가요?","options":[{"t":"단위의 종류를 명확히 구분하여 그리기 어려워요","correct":true},{"t":"큰 수를 나타낼 수 없어요","mis":"M3-2-u6-X14"},{"t":"그림을 더 많이 그려야 해요","mis":"M3-2-u6-X14"},{"t":"나타내는 수가 달라져요","mis":"M3-2-u6-X14"}],"explanation":["단위가 세 가지면 크기가 다른 그림이 세 가지예요.","크기가 비슷하면 어느 그림인지 구분하기 어려워요.","큰 수를 효과적으로 나타내는 것은 편리한 점이에요."],"asset":{"type":"picg","title":"2022년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"건수","units2":[100,10,1],"table":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_basic#7','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C8',2,'sa','auto','봄의 산불 발생 건수는 377건이에요. 100건·10건·1건의 세 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u6-C8","difficulty":2,"kind":"sa","stem":"봄의 산불 발생 건수는 377건이에요. 100건·10건·1건의 세 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["큰 수를 나타내는 그림부터 그려요.","377건 = 100건 그림 3개, 10건 그림 7개, 1건 그림 7개.","3 + 7 + 7 = 17 — 그림은 모두 17개예요."],"variant_rule":{"alt":[{"stem":"가을의 산불 발생 건수는 82건이에요. 100건·10건·1건의 세 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["큰 수를 나타내는 그림부터 그려요.","82건 = 100건 그림 0개, 10건 그림 8개, 1건 그림 2개.","0 + 8 + 2 = 10 — 그림은 모두 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_basic#8','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C5',2,'mc','auto','학교에서 산불 예방 교육을 언제 실시하면 좋을지 정했어요. 그림그래프를 근거로 알맞게 말한 것은 어느 것인가요?',ARRAY['M3-2-u6-X16','M3-2-u6-X17']::text[],false,'{"seq":8,"concept":"M3-2-u6-C5","difficulty":2,"kind":"mc","stem":"학교에서 산불 예방 교육을 언제 실시하면 좋을지 정했어요. 그림그래프를 근거로 알맞게 말한 것은 어느 것인가요?","options":[{"t":"봄 — 봄에 산불이 가장 많이 발생했기 때문이에요","correct":true},{"t":"여름 — 여름에 산불이 가장 많이 발생했기 때문이에요","mis":"M3-2-u6-X16"},{"t":"가을 — 그림그래프와 상관없이 날씨가 좋아서예요","mis":"M3-2-u6-X17"},{"t":"겨울 — 가 그림그래프에서 그림 모양이 가장 예뻐서예요","mis":"M3-2-u6-X17"}],"explanation":["봄 377건이 가장 많고, 여름 29건이 가장 적어요.","그림그래프에 나타난 정보로 까닭을 대요.","봄에 산불이 가장 많이 발생했으므로 봄에 교육하면 좋아요(겨울이 오기 전 가을에 미리, 계절마다 하자는 의견도 그림그래프를 근거로 할 수 있어요)."],"asset":{"type":"picg","title":"2022년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"건수","units2":[100,10,1],"table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_basic#9','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C8',2,'sa','auto','그림그래프를 보고 2021년 겨울의 산불 발생 건수는 몇 건인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u6-C8","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 2021년 겨울의 산불 발생 건수는 몇 건인지 구하세요. 숫자로 쓰세요.","answer":["150"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 100건, 가운데 그림 10건, 작은 그림 1건.","겨울(12, 1, 2월) 줄은 100건 그림 1개와 10건 그림 5개 — 100 × 1 + 10 × 5 = 150.","2021년 겨울의 산불 발생 건수는 150건이에요."],"asset":{"type":"picg","title":"2021년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[158,16,25,150],"units":[100,10,1],"icon":"🔥","unit":"건","vh":"건수"},"variant_rule":{"alt":[{"stem":"그림그래프를 보고 2021년 봄의 산불 발생 건수는 몇 건인지 구하세요. 숫자로 쓰세요.","answer":["158"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 100건, 가운데 그림 10건, 작은 그림 1건.","봄(3, 4, 5월) 줄은 100건 그림 1개, 10건 그림 5개, 1건 그림 8개 — 100 × 1 + 10 × 5 + 1 × 8 = 158.","2021년 봄의 산불 발생 건수는 158건이에요."],"asset":{"type":"picg","title":"2021년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[158,16,25,150],"units":[100,10,1],"icon":"🔥","unit":"건","vh":"건수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_basic#10','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_basic','lesson_basic','M3-2-u6-C5',3,'mc','auto','2021년과 2022년 계절별 산불 발생 건수 그림그래프를 보고 우리 학교 산불 예방의 달을 정하려고 해요. 고른 달과 까닭이 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u6-X16','M3-2-u6-X17']::text[],false,'{"seq":10,"concept":"M3-2-u6-C5","difficulty":3,"kind":"mc","stem":"2021년과 2022년 계절별 산불 발생 건수 그림그래프를 보고 우리 학교 산불 예방의 달을 정하려고 해요. 고른 달과 까닭이 알맞은 것은 어느 것인가요?","options":[{"t":"3월 — 2021년과 2022년 모두 봄(3, 4, 5월)에 산불이 가장 많이 발생했기 때문이에요","correct":true},{"t":"7월 — 두 해 모두 여름에 산불이 가장 적게 발생했기 때문이에요","mis":"M3-2-u6-X16"},{"t":"10월 — 2021년에는 가을에 산불이 가장 많이 발생했기 때문이에요","mis":"M3-2-u6-X17"},{"t":"1월 — 그림그래프는 보지 않고 정했어요","mis":"M3-2-u6-X17"}],"explanation":["2021년은 봄 158건, 여름 16건, 가을 25건, 겨울 150건이에요.","2022년은 봄 377건, 여름 29건, 가을 82건, 겨울 268건이에요.","두 해 모두 봄에 가장 많이 발생했어요 — 3월을 산불 예방의 달로 정할 수 있어요."],"asset":{"type":"picg","title":"2021년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[158,16,25,150],"units":[100,10,1],"icon":"🔥","unit":"건","vh":"건수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_challenge#1','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',2,'sa','auto','여름의 산불 발생 건수는 29건이에요. 10건·1건의 두 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u6-C8","difficulty":2,"kind":"sa","stem":"여름의 산불 발생 건수는 29건이에요. 10건·1건의 두 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["큰 수를 나타내는 그림부터 그려요.","29건 = 10건 그림 2개와 1건 그림 9개.","2 + 9 = 11 — 그림은 모두 11개예요."],"variant_rule":{"alt":[{"stem":"가을의 산불 발생 건수는 82건이에요. 10건·1건의 두 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["큰 수를 나타내는 그림부터 그려요.","82건 = 10건 그림 8개와 1건 그림 2개.","8 + 2 = 10 — 그림은 모두 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_challenge#2','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',2,'mc','auto','268을 그림그래프로 나타내려고 해요. 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u6-X06','M3-2-u6-X05']::text[],false,'{"seq":2,"concept":"M3-2-u6-C8","difficulty":2,"kind":"mc","stem":"268을 그림그래프로 나타내려고 해요. 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"100 그림 2개, 10 그림 6개, 1 그림 8개 — 또는 10 그림 26개, 1 그림 8개","correct":true},{"t":"100 그림 2개, 10 그림 6개, 1 그림 8개 — 또는 10 그림 2개, 1 그림 68개","mis":"M3-2-u6-X06"},{"t":"100 그림 8개, 10 그림 6개, 1 그림 2개","mis":"M3-2-u6-X05"},{"t":"10 그림 26개만 그려요","mis":"M3-2-u6-X06"}],"explanation":["단위가 세 가지(100·10·1)면 268 = 100 그림 2개, 10 그림 6개, 1 그림 8개예요.","단위가 두 가지(10·1)면 10 그림 26개, 1 그림 8개를 그려야 해요.","100 × 2 + 10 × 6 + 1 × 8 = 268 — 단위가 늘면 그림 수가 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_challenge#3','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',3,'sa','auto','겨울의 산불 발생 건수는 268건이에요. 가(10건·1건) 그림그래프보다 나(100건·10건·1건) 그림그래프에서 그림을 몇 개 더 적게 그리나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u6-C8","difficulty":3,"kind":"sa","stem":"겨울의 산불 발생 건수는 268건이에요. 가(10건·1건) 그림그래프보다 나(100건·10건·1건) 그림그래프에서 그림을 몇 개 더 적게 그리나요? 숫자로 쓰세요.","answer":["18"],"explanation":["가: 10건 그림 26개와 1건 그림 8개 — 그림 34개예요.","나: 100건 그림 2개, 10건 그림 6개, 1건 그림 8개 — 그림 16개예요.","34 − 16 = 18 — 18개 더 적게 그려요."],"asset":{"type":"picg","title":"2022년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"건수","units2":[100,10,1],"table":true},"variant_rule":{"alt":[{"stem":"봄의 산불 발생 건수는 377건이에요. 가(10건·1건) 그림그래프보다 나(100건·10건·1건) 그림그래프에서 그림을 몇 개 더 적게 그리나요? 숫자로 쓰세요.","answer":["27"],"explanation":["가: 10건 그림 37개와 1건 그림 7개 — 그림 44개예요.","나: 100건 그림 3개, 10건 그림 7개, 1건 그림 7개 — 그림 17개예요.","44 − 17 = 27 — 27개 더 적게 그려요."],"asset":{"type":"picg","title":"2022년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"건수","units2":[100,10,1],"table":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_challenge#4','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',3,'ox','auto','「가 그림그래프와 나 그림그래프는 그림의 개수가 다르므로 나타내는 산불 발생 건수도 다르다.」 맞으면 ○, 틀리면 ×를 고르세요.',ARRAY['M3-2-u6-X14']::text[],false,'{"seq":4,"concept":"M3-2-u6-C8","difficulty":3,"kind":"ox","stem":"「가 그림그래프와 나 그림그래프는 그림의 개수가 다르므로 나타내는 산불 발생 건수도 다르다.」 맞으면 ○, 틀리면 ×를 고르세요.","answer":"X","reason_options":[{"t":"같은 표를 단위만 다르게 나타냈으니 건수는 같아요","correct":true},{"t":"그림의 개수가 다르면 나타내는 수도 달라요","mis":"M3-2-u6-X14"}],"mis":"M3-2-u6-X14","explanation":["겨울은 가에서 10건 그림 26개와 1건 그림 8개, 나에서 100건 그림 2개, 10건 그림 6개, 1건 그림 8개예요.","둘 다 268건을 나타내요.","단위의 종류가 다르면 그림 개수는 달라도 나타내는 수는 같아요."],"asset":{"type":"picg","title":"2022년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"건수","units2":[100,10,1],"table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_challenge#5','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C9',3,'mc','auto','20년 동안 쓰레기 배출량이 8억 톤에서 16억 톤으로 2배가 된 것을 그림의 가로와 세로를 각각 2배로 늘려 나타냈어요. 늘린 그림의 넓이는 처음 그림의 몇 배가 되나요?',ARRAY['M3-2-u6-X15']::text[],false,'{"seq":5,"concept":"M3-2-u6-C9","difficulty":3,"kind":"mc","stem":"20년 동안 쓰레기 배출량이 8억 톤에서 16억 톤으로 2배가 된 것을 그림의 가로와 세로를 각각 2배로 늘려 나타냈어요. 늘린 그림의 넓이는 처음 그림의 몇 배가 되나요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M3-2-u6-X15"},{"t":"8배","mis":"M3-2-u6-X15"},{"t":"같아요","mis":"M3-2-u6-X15"}],"explanation":["가로 2배, 세로 2배로 늘리면 넓이는 2 × 2 = 4배가 돼요.","배출량은 2배인데 그림은 4배로 커 보여 실제보다 더 많이 늘어난 것처럼 느껴져요.","그림그래프는 그림의 크기가 아니라 그림이 나타내는 수로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_challenge#6','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C9',3,'ox','auto','「그림그래프에서 그림을 크게 그린 항목은 언제나 수가 더 많다.」 맞으면 ○, 틀리면 ×를 고르세요.',ARRAY['M3-2-u6-X15']::text[],false,'{"seq":6,"concept":"M3-2-u6-C9","difficulty":3,"kind":"ox","stem":"「그림그래프에서 그림을 크게 그린 항목은 언제나 수가 더 많다.」 맞으면 ○, 틀리면 ×를 고르세요.","answer":"X","reason_options":[{"t":"그림이 나타내는 수(단위)와 개수를 보고 수를 읽어야 해요","correct":true},{"t":"크게 그렸으니 수가 더 많아요","mis":"M3-2-u6-X15"}],"mis":"M3-2-u6-X15","explanation":["그림의 크기만 보고 판단하면 잘못 해석할 수 있어요.","그림의 단위를 확인하고 큰 그림부터 세어 수를 읽어요.","수를 무시하고 그림을 크게 그리면 자료가 왜곡돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_challenge#7','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C5',3,'essay','teacher','2022년 계절별 산불 발생 건수 그림그래프를 보고 학교에서 산불 예방 교육을 언제 실시하면 좋을지 생각해 보고, 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":7,"concept":"M3-2-u6-C5","difficulty":3,"kind":"essay","stem":"2022년 계절별 산불 발생 건수 그림그래프를 보고 학교에서 산불 예방 교육을 언제 실시하면 좋을지 생각해 보고, 그 까닭을 써 보세요.","answer_guide":{"answer":"예 1: 봄(3, 4, 5월) — 봄에 산불이 377건으로 가장 많이 발생했기 때문이다. 예 2: 가을(9, 10, 11월) — 겨울과 봄에 산불이 많이 발생했으므로 겨울이 되기 전에 미리 교육한다. 예 3: 계절마다 — 산불은 사계절 내내 발생했기 때문이다.","scoring_points":["교육 시기를 정했는가","그림그래프에서 읽은 건수(정보)를 까닭으로 들었는가","친구의 다른 의견도 그림그래프에 근거하면 존중할 수 있음을 알았는가"]},"explanation":["봄 377건, 여름 29건, 가을 82건, 겨울 268건이에요.","그림그래프에 제시된 정보를 활용해 까닭을 대요.","봄·가을에 미리·계절마다 등 근거가 있으면 여러 의견이 될 수 있어요."],"asset":{"type":"picg","title":"2022년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"건수","units2":[100,10,1],"table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_challenge#8','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',4,'essay','teacher','가(10건·1건)와 나(100건·10건·1건) 두 그림그래프의 같은 점과 다른 점을 쓰고, 단위의 종류가 늘어나면 편리한 점과 불편한 점을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u6-C8","difficulty":4,"kind":"essay","stem":"가(10건·1건)와 나(100건·10건·1건) 두 그림그래프의 같은 점과 다른 점을 쓰고, 단위의 종류가 늘어나면 편리한 점과 불편한 점을 써 보세요.","answer_guide":{"answer":"같은 점: 산불 발생 건수를 나타내는 그림이 같다(나타내는 건수도 같다). 다른 점: 단위의 종류가 다르다(가 두 가지, 나 세 가지). 편리한 점: 큰 수를 효과적으로(적은 그림으로) 나타낼 수 있다. 불편한 점: 단위의 종류를 명확히 구분하여 그리기 어렵다.","scoring_points":["같은 점(그림이 같음)을 썼는가","다른 점(단위의 종류)을 썼는가","편리한 점과 불편한 점을 모두 썼는가"]},"explanation":["두 그림그래프는 같은 표를 나타내요.","가는 단위 두 가지, 나는 세 가지예요 — 봄은 가에서 44개, 나에서 17개예요.","단위가 늘면 그림은 줄지만 크기를 구분하기 어려워요."],"asset":{"type":"picg","title":"2022년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"건수","units2":[100,10,1],"table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_challenge#9','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C5',4,'essay','teacher','2021년과 2022년 계절별 산불 발생 건수 그림그래프를 견주어 보고, 우리 학교 산불 예방의 달을 언제로 정하면 좋을지 고르고 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u6-C5","difficulty":4,"kind":"essay","stem":"2021년과 2022년 계절별 산불 발생 건수 그림그래프를 견주어 보고, 우리 학교 산불 예방의 달을 언제로 정하면 좋을지 고르고 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 3월 — 2021년(봄 158건)과 2022년(봄 377건) 모두 봄에 산불이 가장 많이 발생했기 때문이다. / 11월 — 두 해 모두 봄과 겨울에 산불이 많이 발생했으므로 미리 예방한다. / 3월, 6월, 9월, 12월 — 두 해 모두 사계절 내내 산불이 발생했으므로 주기적으로 예방한다.","scoring_points":["두 해의 그림그래프를 모두 읽었는가","산불 예방의 달을 골랐는가","두 해를 견준 사실로 까닭을 댔는가"]},"explanation":["2021년: 봄 158, 여름 16, 가을 25, 겨울 150이에요.","2022년: 봄 377, 여름 29, 가을 82, 겨울 268이에요.","두 해 모두 봄이 가장 많고 겨울이 그다음이에요."],"asset":{"type":"picg","title":"2021년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[158,16,25,150],"units":[100,10,1],"icon":"🔥","unit":"건","vh":"건수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_L06_challenge#10','math',3,2,'u6','L06','tb_g3_2_math_u6_L06_challenge','lesson_challenge','M3-2-u6-C8',4,'sa','auto','2022년의 산불 발생 건수는 모두 756건이고, 2021년은 봄 158건, 여름 16건, 가을 25건, 겨울 150건이에요. 2022년에는 2021년보다 산불이 몇 건 더 발생했나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u6-C8","difficulty":4,"kind":"sa","stem":"2022년의 산불 발생 건수는 모두 756건이고, 2021년은 봄 158건, 여름 16건, 가을 25건, 겨울 150건이에요. 2022년에는 2021년보다 산불이 몇 건 더 발생했나요? 숫자로 쓰세요.","answer":["407"],"explanation":["2021년의 산불 발생 건수를 모두 더해요 — 158 + 16 + 25 + 150 = 349예요.","2022년은 756건이에요.","756 − 349 = 407 — 407건 더 발생했어요."],"asset":{"type":"picg","title":"2021년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[158,16,25,150],"units":[100,10,1],"icon":"🔥","unit":"건","vh":"건수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#1','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C2',1,'blank','auto','「조사한 자료의 수를 그림으로 나타낸 그래프를 □(이)라고 합니다.」 □에 알맞은 말은 무엇인가요?',ARRAY['M3-2-u6-X09','M3-2-u6-X18']::text[],false,'{"seq":1,"concept":"M3-2-u6-C2","difficulty":1,"kind":"blank","stem":"「조사한 자료의 수를 그림으로 나타낸 그래프를 □(이)라고 합니다.」 □에 알맞은 말은 무엇인가요?","options":[{"t":"그림그래프","correct":true},{"t":"표","mis":"M3-2-u6-X09"},{"t":"◯ 그래프","mis":"M3-2-u6-X09"},{"t":"그림일기","mis":"M3-2-u6-X18"}],"explanation":["정리 — 그림그래프는 조사한 자료의 수를 그림으로 나타낸 그래프예요.","자료를 수집하여 그림그래프로: ① 주제와 대상·항목 ② 조사 방법 ③ 표 ④ 그림그래프·해석.","□에 알맞은 말은 그림그래프예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#2','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C3',1,'mc','auto','어느 도넛 가게에서 하루 동안 판매한 도넛의 수를 조사한 그림그래프예요. 가장 많이 판매한 도넛의 종류는 무엇인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X04']::text[],false,'{"seq":2,"concept":"M3-2-u6-C3","difficulty":1,"kind":"mc","stem":"어느 도넛 가게에서 하루 동안 판매한 도넛의 수를 조사한 그림그래프예요. 가장 많이 판매한 도넛의 종류는 무엇인가요?","options":[{"t":"크림도넛","correct":true},{"t":"딸기도넛","mis":"M3-2-u6-X03"},{"t":"블루베리도넛","mis":"M3-2-u6-X04"},{"t":"초코도넛","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","딸기도넛 42개, 블루베리도넛 28개, 초코도넛 33개, 크림도넛 52개.","가장 많은 것은 크림도넛이에요."],"asset":{"type":"picg","title":"종류별 판매한 도넛의 수","head":"종류","cols":["딸기도넛","블루베리도넛","초코도넛","크림도넛"],"counts":[42,28,33,52],"units":[10,1],"icon":"🍩","unit":"개","vh":"도넛의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#3','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C2',1,'sa','auto','그림그래프를 보고 판매한 크림도넛은 몇 개인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u6-C2","difficulty":1,"kind":"sa","stem":"그림그래프를 보고 판매한 크림도넛은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["52"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10개, 작은 그림 1개.","크림도넛 줄은 10개 그림 5개와 1개 그림 2개 — 10 × 5 + 1 × 2 = 52.","판매한 크림도넛은 52개예요."],"asset":{"type":"picg","title":"종류별 판매한 도넛의 수","head":"종류","cols":["딸기도넛","블루베리도넛","초코도넛","크림도넛"],"counts":[42,28,33,52],"units":[10,1],"icon":"🍩","unit":"개","vh":"도넛의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#4','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C4',1,'mc','auto','장미는 23송이예요. 5송이·1송이의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],false,'{"seq":4,"concept":"M3-2-u6-C4","difficulty":1,"kind":"mc","stem":"장미는 23송이예요. 5송이·1송이의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"5송이 그림 4개, 1송이 그림 3개","correct":true},{"t":"5송이 그림 3개, 1송이 그림 4개","mis":"M3-2-u6-X05"},{"t":"1송이 그림 23개","mis":"M3-2-u6-X06"},{"t":"5송이 그림 5개, 1송이 그림 3개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","23송이 안에 5송이가 4번 들어가요 — 남은 3송이는 1송이 그림으로 나타내요.","답은 5송이 그림 4개, 1송이 그림 3개예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"종류","cols":["백합","장미","카네이션","튤립","해바라기"],"counts":[18,23,31,22,7],"units":[5,1],"icon":"🌸","unit":"송이","vh":"꽃의 수","table":true,"blank":[1]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#5','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C3',1,'error','auto','어느 꽃집에 있는 꽃의 수를 나타낸 그림그래프예요. 그림그래프를 보고 알 수 있는 내용으로 옳지 않은 것은 어느 것인가요?',ARRAY['M3-2-u6-X02','M3-2-u6-X16']::text[],false,'{"seq":5,"concept":"M3-2-u6-C3","difficulty":1,"kind":"error","stem":"어느 꽃집에 있는 꽃의 수를 나타낸 그림그래프예요. 그림그래프를 보고 알 수 있는 내용으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"㉡ 꽃의 수를 나타낼 때 장미는 튤립보다 5송이 그림을 하나 더 많이 그려요","correct":true,"mis_target":"M3-2-u6-X02"},{"t":"㉠ 큰 그림은 5송이, 작은 그림은 1송이를 나타내요","mis":"M3-2-u6-X16"},{"t":"㉢ 1송이 그림을 가장 적게 그리는 꽃은 카네이션이에요","mis":"M3-2-u6-X16"}],"explanation":["장미 23송이는 5송이 그림 4개와 1송이 그림 3개, 튤립 22송이는 5송이 그림 4개와 1송이 그림 2개예요.","장미는 튤립보다 1송이 그림을 하나 더 많이 그려요 — ㉡이 옳지 않아요.","1송이 그림은 백합 3개, 장미 3개, 카네이션 1개, 튤립 2개, 해바라기 2개 — 카네이션이 가장 적어요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"종류","cols":["백합","장미","카네이션","튤립","해바라기"],"counts":[18,23,31,22,7],"units":[5,1],"icon":"🌸","unit":"송이","vh":"꽃의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#6','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C2',1,'sa','auto','그림그래프를 보고 축구를 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u6-C2","difficulty":1,"kind":"sa","stem":"그림그래프를 보고 축구를 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["11"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 5명, 작은 그림 1명.","축구 줄은 5명 그림 2개와 1명 그림 1개 — 5 × 2 + 1 × 1 = 11.","축구를 좋아하는 사람은 11명이에요."],"asset":{"type":"picg","title":"좋아하는 운동별 사람 수","head":"운동","cols":["농구","야구","축구","탁구"],"counts":[5,7,11,6],"units":[5,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#7','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C2',1,'mc','auto','그림그래프에서 크기가 다른 그림은 각각 몇 송이를 나타내나요?',ARRAY['M3-2-u6-X02','M3-2-u6-X01','M3-2-u6-X18']::text[],false,'{"seq":7,"concept":"M3-2-u6-C2","difficulty":1,"kind":"mc","stem":"그림그래프에서 크기가 다른 그림은 각각 몇 송이를 나타내나요?","options":[{"t":"큰 그림 5송이, 작은 그림 1송이","correct":true},{"t":"큰 그림 1송이, 작은 그림 5송이","mis":"M3-2-u6-X02"},{"t":"큰 그림 1송이, 작은 그림 1송이","mis":"M3-2-u6-X01"},{"t":"큰 그림 10송이, 작은 그림 1송이","mis":"M3-2-u6-X18"}],"explanation":["그림그래프 아래 그림의 단위를 먼저 봐요.","큰 그림 5송이, 작은 그림 1송이예요.","그림의 크기에 따라 나타내는 수가 달라요 — 그림을 읽기 전에 단위부터 확인해요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"종류","cols":["백합","장미","카네이션","튤립","해바라기"],"counts":[18,23,31,22,7],"units":[5,1],"icon":"🌸","unit":"송이","vh":"꽃의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#8','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C1',1,'sa','auto','어느 꽃집에 있는 꽃의 수를 조사하여 나타낸 표예요. 꽃은 모두 몇 송이인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u6-C1","difficulty":1,"kind":"sa","stem":"어느 꽃집에 있는 꽃의 수를 조사하여 나타낸 표예요. 꽃은 모두 몇 송이인가요? 숫자로 쓰세요.","answer":["101"],"explanation":["합계는 모두 더한 수예요.","백합 18, 장미 23, 카네이션 31, 튤립 22, 해바라기 7송이예요.","18 + 23 + 31 + 22 + 7 = 101 — 모두 101송이예요."],"asset":{"type":"picg","only":"table","head":"종류","cols":["백합","장미","카네이션","튤립","해바라기"],"counts":[18,23,31,22,7],"unit":"송이","vh":"꽃의 수","title":"종류별 꽃의 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#9','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C3',2,'mc','auto','가게별 상추 판매량 그림그래프예요. 「㉮ 가게는 상추 34상자를 판매했습니다.」 ㉮ 가게는 그림그래프의 어느 가게인가요?',ARRAY['M3-2-u6-X02','M3-2-u6-X03']::text[],false,'{"seq":9,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"가게별 상추 판매량 그림그래프예요. 「㉮ 가게는 상추 34상자를 판매했습니다.」 ㉮ 가게는 그림그래프의 어느 가게인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M3-2-u6-X02"},{"t":"㉡","mis":"M3-2-u6-X03"}],"explanation":["그림의 단위는 10상자, 1상자예요.","㉠ 40상자, ㉡ 42상자, ㉢ 34상자예요.","34상자를 판매한 가게는 ㉢이에요."],"asset":{"type":"picg","title":"가게별 상추 판매량","head":"가게","cols":["㉠","㉡","㉢"],"counts":[40,42,34],"units":[10,1],"icon":"🥬","unit":"상자","vh":"상추 판매량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#10','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 장맛비 가게에서 판매한 우산은 몇 개인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 장맛비 가게에서 판매한 우산은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["91"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 50개, 가운데 그림 10개, 작은 그림 1개.","장맛비 줄은 50개 그림 1개, 10개 그림 4개, 1개 그림 1개 — 50 × 1 + 10 × 4 + 1 × 1 = 91.","장맛비 가게에서 판매한 우산은 91개예요."],"asset":{"type":"picg","title":"가게별 판매한 우산 수","head":"가게","cols":["소나기","여우비","이슬비","장맛비"],"counts":[160,105,80,91],"units":[50,10,1],"icon":"☂","unit":"개","vh":"우산의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#11','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C3',2,'mc','auto','좋아하는 민속놀이별 3학년 학생 수 그림그래프예요. 3학년 학생들이 가장 좋아하는 민속놀이는 무엇인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X04','M3-2-u6-X16']::text[],false,'{"seq":11,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"좋아하는 민속놀이별 3학년 학생 수 그림그래프예요. 3학년 학생들이 가장 좋아하는 민속놀이는 무엇인가요?","options":[{"t":"윷놀이","correct":true},{"t":"연날리기","mis":"M3-2-u6-X03"},{"t":"줄다리기","mis":"M3-2-u6-X04"},{"t":"투호","mis":"M3-2-u6-X16"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","연날리기 23명, 윷놀이 30명, 줄다리기 25명, 투호 12명.","가장 많은 것은 윷놀이예요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 3학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[23,30,25,12],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#12','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 줄다리기를 좋아하는 3학년 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 줄다리기를 좋아하는 3학년 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["25"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","줄다리기 줄은 10명 그림 2개와 1명 그림 5개 — 10 × 2 + 1 × 5 = 25.","줄다리기를 좋아하는 3학년 학생은 25명이에요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 3학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[23,30,25,12],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#13','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C3',2,'mc','auto','만화 속 좋아하는 운동별 사람 수 그림그래프예요. 가장 많은 사람이 좋아하는 운동은 무엇인가요?',ARRAY['M3-2-u6-X16','M3-2-u6-X04','M3-2-u6-X03']::text[],false,'{"seq":13,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"만화 속 좋아하는 운동별 사람 수 그림그래프예요. 가장 많은 사람이 좋아하는 운동은 무엇인가요?","options":[{"t":"축구","correct":true},{"t":"농구","mis":"M3-2-u6-X16"},{"t":"야구","mis":"M3-2-u6-X04"},{"t":"탁구","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","농구 5명, 야구 7명, 축구 11명, 탁구 6명.","가장 많은 것은 축구예요."],"asset":{"type":"picg","title":"좋아하는 운동별 사람 수","head":"운동","cols":["농구","야구","축구","탁구"],"counts":[5,7,11,6],"units":[5,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#14','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C3',2,'sa','auto','민서네 학교의 3학년은 24명씩 12반이에요. 민서네 학교의 3학년 학생은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M3-2-u6-C3","difficulty":2,"kind":"sa","stem":"민서네 학교의 3학년은 24명씩 12반이에요. 민서네 학교의 3학년 학생은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["288"],"explanation":["한 반에 24명씩 12반이에요.","곱셈으로 구해요.","24 × 12 = 288 — 모두 288명이에요."],"asset":{"type":"picg","title":"좋아하는 과일별 학생 수","head":"과일","cols":["매실","배","사과","포도","한라봉"],"counts":[6,24,null,102,72],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[2]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#15','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C8',2,'sa','auto','가을의 산불 발생 건수는 82건이에요. 100건·10건·1건의 세 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u6-C8","difficulty":2,"kind":"sa","stem":"가을의 산불 발생 건수는 82건이에요. 100건·10건·1건의 세 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["큰 수를 나타내는 그림부터 그려요.","82건 = 100건 그림 0개, 10건 그림 8개, 1건 그림 2개.","0 + 8 + 2 = 10 — 그림은 모두 10개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#16','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C7',2,'mc','auto','감을 좋아하는 학생은 11명이에요. 5명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],false,'{"seq":16,"concept":"M3-2-u6-C7","difficulty":2,"kind":"mc","stem":"감을 좋아하는 학생은 11명이에요. 5명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"5명 그림 2개, 1명 그림 1개","correct":true},{"t":"5명 그림 1개, 1명 그림 2개","mis":"M3-2-u6-X05"},{"t":"1명 그림 11개","mis":"M3-2-u6-X06"},{"t":"5명 그림 3개, 1명 그림 1개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","11명 안에 5명이 2번 들어가요 — 남은 1명은 1명 그림으로 나타내요.","답은 5명 그림 2개, 1명 그림 1개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#17','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C3',3,'essay','teacher','3학년과 4학년 학생들이 좋아하는 민속놀이를 조사하여 나타낸 두 그림그래프를 보고 같은 점과 다른 점을 써 보세요.','{}'::text[],false,'{"seq":17,"concept":"M3-2-u6-C3","difficulty":3,"kind":"essay","stem":"3학년과 4학년 학생들이 좋아하는 민속놀이를 조사하여 나타낸 두 그림그래프를 보고 같은 점과 다른 점을 써 보세요.","answer_guide":{"answer":"같은 점: 3학년과 4학년 모두 윷놀이를 좋아하는 학생이 가장 많다(두 번째는 모두 줄다리기). 다른 점: 가장 적은 학생이 좋아하는 민속놀이는 3학년은 투호(12명)이고, 4학년은 연날리기(13명)이다.","scoring_points":["두 그래프의 수를 바르게 읽었는가","같은 점을 썼는가","다른 점을 썼는가"]},"explanation":["3학년: 연날리기 23, 윷놀이 30, 줄다리기 25, 투호 12명이에요.","4학년: 연날리기 13, 윷놀이 33, 줄다리기 22, 투호 21명이에요.","두 학년 모두 윷놀이가 가장 많고, 가장 적은 것은 3학년 투호, 4학년 연날리기예요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 3학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[23,30,25,12],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#18','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C5',3,'essay','teacher','3학년과 4학년 학생들이 함께 모여 두 종류의 민속놀이를 하려고 해요. 두 그림그래프를 보고 어떤 민속놀이를 하는 것이 좋을지 고르고, 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":18,"concept":"M3-2-u6-C5","difficulty":3,"kind":"essay","stem":"3학년과 4학년 학생들이 함께 모여 두 종류의 민속놀이를 하려고 해요. 두 그림그래프를 보고 어떤 민속놀이를 하는 것이 좋을지 고르고, 그 까닭을 써 보세요.","answer_guide":{"answer":"윷놀이, 줄다리기 — 3학년과 4학년 학생들이 가장 좋아하는 민속놀이(윷놀이)와 두 번째로 좋아하는 민속놀이(줄다리기)이기 때문이다.","scoring_points":["윷놀이와 줄다리기를 골랐는가","두 학년 모두의 차례(가장·두 번째)로 까닭을 댔는가","그림그래프에서 읽은 수를 근거로 썼는가"]},"explanation":["3학년 차례: 윷놀이, 줄다리기, 연날리기, 투호예요.","4학년 차례: 윷놀이, 줄다리기, 투호, 연날리기예요.","두 학년 모두 첫째·둘째가 윷놀이·줄다리기예요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 3학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[23,30,25,12],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#19','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C1',3,'sa','auto','민서네 학교 3학년 학생 288명이 좋아하는 과일을 조사했어요. 그림그래프에서 사과 줄이 비어 있어요. 사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M3-2-u6-C1","difficulty":3,"kind":"sa","stem":"민서네 학교 3학년 학생 288명이 좋아하는 과일을 조사했어요. 그림그래프에서 사과 줄이 비어 있어요. 사과를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["매실 6명, 배 24명, 포도 102명, 한라봉 72명이에요.","사과 = 전체 학생 수 − 다른 과일을 좋아하는 학생 수예요.","288 − 6 − 24 − 102 − 72 = 84 — 10명 그림 8개, 1명 그림 4개를 붙여요."],"asset":{"type":"picg","title":"좋아하는 과일별 학생 수","head":"과일","cols":["매실","배","사과","포도","한라봉"],"counts":[6,24,null,102,72],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[2]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#20','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C3',3,'mc','auto','우산 가게 이름 찾기 — 「㉮ 가게는 우산을 두 번째로 많이 판매했습니다.」 ㉮ 가게는 어디인가요?',ARRAY['M3-2-u6-X16','M3-2-u6-X04','M3-2-u6-X03']::text[],false,'{"seq":20,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"우산 가게 이름 찾기 — 「㉮ 가게는 우산을 두 번째로 많이 판매했습니다.」 ㉮ 가게는 어디인가요?","options":[{"t":"여우비","correct":true},{"t":"소나기","mis":"M3-2-u6-X16"},{"t":"장맛비","mis":"M3-2-u6-X04"},{"t":"이슬비","mis":"M3-2-u6-X03"}],"explanation":["소나기 160개, 여우비 105개, 이슬비 80개, 장맛비 91개예요.","많은 차례는 소나기, 여우비, 장맛비, 이슬비예요.","두 번째로 많이 판매한 가게는 여우비예요."],"asset":{"type":"picg","title":"가게별 판매한 우산 수","head":"가게","cols":["소나기","여우비","이슬비","장맛비"],"counts":[160,105,80,91],"units":[50,10,1],"icon":"☂","unit":"개","vh":"우산의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#21','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C2',3,'sa','auto','그림그래프를 보고 ㉡ 프로그램을 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u6-C2","difficulty":3,"kind":"sa","stem":"그림그래프를 보고 ㉡ 프로그램을 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["21"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","㉡ 줄은 10명 그림 2개와 1명 그림 1개 — 10 × 2 + 1 × 1 = 21.","㉡ 프로그램을 좋아하는 사람은 21명이에요."],"asset":{"type":"picg","title":"좋아하는 텔레비전 프로그램별 사람 수","head":"프로그램","cols":["㉠","㉡","㉢","㉣"],"counts":[12,21,14,16],"units":[10,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#22','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C9',3,'mc','auto','쓰레기 배출량이 8억 톤에서 16억 톤으로 2배가 된 것을 그림의 가로와 세로를 각각 2배로 늘려 나타냈어요. 그림의 넓이는 몇 배가 되나요?',ARRAY['M3-2-u6-X15']::text[],false,'{"seq":22,"concept":"M3-2-u6-C9","difficulty":3,"kind":"mc","stem":"쓰레기 배출량이 8억 톤에서 16억 톤으로 2배가 된 것을 그림의 가로와 세로를 각각 2배로 늘려 나타냈어요. 그림의 넓이는 몇 배가 되나요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M3-2-u6-X15"},{"t":"8배","mis":"M3-2-u6-X15"},{"t":"같아요","mis":"M3-2-u6-X15"}],"explanation":["가로 2배, 세로 2배면 넓이는 2 × 2 = 4배예요.","그래서 배출량이 2배보다 훨씬 많이 늘어난 것처럼 느껴져요.","그림의 크기가 아니라 나타내는 수로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#23','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C4',4,'essay','teacher','만화에서 친구가 「그리는 김에 더 예쁘게 여러 가지 그림으로 그리는 것이 좋지 않겠어?」라고 했어요. 그림그래프를 그릴 때 그림은 어떻게 정해야 하는지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u6-C4","difficulty":4,"kind":"essay","stem":"만화에서 친구가 「그리는 김에 더 예쁘게 여러 가지 그림으로 그리는 것이 좋지 않겠어?」라고 했어요. 그림그래프를 그릴 때 그림은 어떻게 정해야 하는지 까닭과 함께 써 보세요.","answer_guide":{"answer":"그림그래프를 그릴 때는 자료의 수를 잘 나타낼 수 있는 그림으로 그려야 한다. 한 그래프 안에 여러 가지 모양을 섞으면 그림이 나타내는 수를 알기 어렵다. 무엇을 조사했는지 한눈에 보이는 그림 한 가지를 정하고, 크기만 달리하여 단위를 나타낸다.","scoring_points":["자료의 수를 잘 나타내는 그림으로 그려야 한다고 썼는가","여러 모양을 섞으면 수를 읽기 어렵다는 까닭을 썼는가","그림의 크기로 단위를 나타낸다고 썼는가"]},"explanation":["그림그래프는 그림으로 수를 나타내요.","예쁘게 꾸미는 것보다 수를 잘 나타내는 것이 중요해요.","한 가지 그림을 정하고 크기로 단위를 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#24','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C6',4,'essay','teacher','「3학년 신문을 만들어요」 — 모둠에서 3학년 학생들이 좋아하는 과일·음식·문화유산 가운데 하나를 골라 조사하려고 해요. 조사 계획(주제·대상·항목·조사 방법)과 모둠 친구들의 역할을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u6-C6","difficulty":4,"kind":"essay","stem":"「3학년 신문을 만들어요」 — 모둠에서 3학년 학생들이 좋아하는 과일·음식·문화유산 가운데 하나를 골라 조사하려고 해요. 조사 계획(주제·대상·항목·조사 방법)과 모둠 친구들의 역할을 써 보세요.","answer_guide":{"answer":"예: 주제 — 좋아하는 우리나라 음식, 대상 — 우리 반 학생, 항목 — 떡국·불고기·비빔밥·잡채 등 4~5개, 조사 방법 — 붙임딱지 붙이기. 역할 — 자료 수집하기, 그림그래프 그리기, 해석하기.","scoring_points":["주제와 대상을 정했는가","항목과 조사 방법을 알맞게 정했는가","자료 수집·그림그래프 그리기·해석하기 같은 역할을 나누었는가"]},"explanation":["신문도 자료 수집 네 걸음으로 만들어요.","주제·대상·항목 → 조사 방법 → 표 → 그림그래프·해석.","역할을 나누어 협력해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_a#25','math',3,2,'u6','','tb_g3_2_math_u6_review_a','unit_review','M3-2-u6-C4',4,'essay','teacher','단원 핵심 질문 — 「조사한 자료의 수를 그림으로 어떻게 나타낼까요?」 이 단원에서 배운 내용으로 답을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u6-C4","difficulty":4,"kind":"essay","stem":"단원 핵심 질문 — 「조사한 자료의 수를 그림으로 어떻게 나타낼까요?」 이 단원에서 배운 내용으로 답을 써 보세요.","answer_guide":{"answer":"알맞은 제목을 쓰고, 자료의 수를 나타낼 그림과 단위(예 10명·1명)를 정하고, 조사한 항목을 빠짐없이 쓴 다음, 자료의 수에 맞게 큰 수를 나타내는 그림부터 그린다. 다 그린 뒤 그림이 나타내는 수가 표와 같은지 확인한다.","scoring_points":["제목·그림과 단위·항목·그림의 네 가지를 썼는가","큰 그림부터 그린다고 썼는가","표와 같은지 확인한다고 썼는가"]},"explanation":["그림그래프로 나타내는 방법은 네 걸음이에요.","큰 수를 나타내는 그림을 먼저 그려요.","다 그린 뒤 빠진 항목이 없는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#1','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C6',1,'blank','auto','「① 알아보고 싶은 □와/과 대상을 정하고, 그에 따른 항목을 정합니다.」 □에 알맞은 말은 무엇인가요?',ARRAY['M3-2-u6-X12','M3-2-u6-X07']::text[],false,'{"seq":1,"concept":"M3-2-u6-C6","difficulty":1,"kind":"blank","stem":"「① 알아보고 싶은 □와/과 대상을 정하고, 그에 따른 항목을 정합니다.」 □에 알맞은 말은 무엇인가요?","options":[{"t":"주제","correct":true},{"t":"그림","mis":"M3-2-u6-X12"},{"t":"합계","mis":"M3-2-u6-X12"},{"t":"제목","mis":"M3-2-u6-X07"}],"explanation":["정리 — 그림그래프는 조사한 자료의 수를 그림으로 나타낸 그래프예요.","자료를 수집하여 그림그래프로: ① 주제와 대상·항목 ② 조사 방법 ③ 표 ④ 그림그래프·해석.","□에 알맞은 말은 주제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#2','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',1,'mc','auto','과수원 4곳의 사과 생산량을 조사한 그림그래프예요. 사과를 가장 많이 생산한 과수원은 어디인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X04']::text[],false,'{"seq":2,"concept":"M3-2-u6-C3","difficulty":1,"kind":"mc","stem":"과수원 4곳의 사과 생산량을 조사한 그림그래프예요. 사과를 가장 많이 생산한 과수원은 어디인가요?","options":[{"t":"햇빛","correct":true},{"t":"맑음","mis":"M3-2-u6-X03"},{"t":"신선","mis":"M3-2-u6-X03"},{"t":"푸름","mis":"M3-2-u6-X04"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","맑음 220 kg, 신선 230 kg, 푸름 160 kg, 햇빛 300 kg.","가장 많은 것은 햇빛이에요."],"asset":{"type":"picg","title":"과수원별 사과 생산량","head":"과수원","cols":["맑음","신선","푸름","햇빛"],"counts":[220,230,160,300],"units":[100,10],"icon":"🍎","unit":"kg","vh":"생산량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#3','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C2',1,'sa','auto','그림그래프를 보고 판매한 딸기도넛은 몇 개인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u6-C2","difficulty":1,"kind":"sa","stem":"그림그래프를 보고 판매한 딸기도넛은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["42"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10개, 작은 그림 1개.","딸기도넛 줄은 10개 그림 4개와 1개 그림 2개 — 10 × 4 + 1 × 2 = 42.","판매한 딸기도넛은 42개예요."],"asset":{"type":"picg","title":"종류별 판매한 도넛의 수","head":"종류","cols":["딸기도넛","블루베리도넛","초코도넛","크림도넛"],"counts":[42,28,33,52],"units":[10,1],"icon":"🍩","unit":"개","vh":"도넛의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#4','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C4',1,'mc','auto','해바라기는 7송이예요. 5송이·1송이의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],false,'{"seq":4,"concept":"M3-2-u6-C4","difficulty":1,"kind":"mc","stem":"해바라기는 7송이예요. 5송이·1송이의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"5송이 그림 1개, 1송이 그림 2개","correct":true},{"t":"5송이 그림 2개, 1송이 그림 1개","mis":"M3-2-u6-X05"},{"t":"1송이 그림 7개","mis":"M3-2-u6-X06"},{"t":"5송이 그림 2개, 1송이 그림 2개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","7송이 안에 5송이가 1번 들어가요 — 남은 2송이는 1송이 그림으로 나타내요.","답은 5송이 그림 1개, 1송이 그림 2개예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"종류","cols":["백합","장미","카네이션","튤립","해바라기"],"counts":[18,23,31,22,7],"units":[5,1],"icon":"🌸","unit":"송이","vh":"꽃의 수","table":true,"blank":[4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#5','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',1,'error','auto','좋아하는 색깔별 학생 수 그림그래프를 보고 알 수 있는 내용으로 옳지 않은 것은 어느 것인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16']::text[],false,'{"seq":5,"concept":"M3-2-u6-C3","difficulty":1,"kind":"error","stem":"좋아하는 색깔별 학생 수 그림그래프를 보고 알 수 있는 내용으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"가장 많은 학생이 좋아하는 색깔은 그림이 가장 많은 파랑이에요","correct":true,"mis_target":"M3-2-u6-X04"},{"t":"파랑을 좋아하는 학생은 15명이에요","mis":"M3-2-u6-X16"},{"t":"초록을 좋아하는 학생은 분홍을 좋아하는 학생보다 1명 더 많아요","mis":"M3-2-u6-X16"}],"explanation":["노랑 41명, 분홍 21명, 초록 22명, 파랑 15명이에요.","가장 많은 학생이 좋아하는 색깔은 노랑이에요.","파랑은 그림이 6개로 가장 많지만 작은 그림이 많아 15명뿐이에요."],"asset":{"type":"picg","title":"좋아하는 색깔별 학생 수","head":"색깔","cols":["노랑","분홍","초록","파랑"],"counts":[41,21,22,15],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#6','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C2',1,'sa','auto','그림그래프를 보고 야구를 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u6-C2","difficulty":1,"kind":"sa","stem":"그림그래프를 보고 야구를 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["7"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 5명, 작은 그림 1명.","야구 줄은 5명 그림 1개와 1명 그림 2개 — 5 × 1 + 1 × 2 = 7.","야구를 좋아하는 사람은 7명이에요."],"asset":{"type":"picg","title":"좋아하는 운동별 사람 수","head":"운동","cols":["농구","야구","축구","탁구"],"counts":[5,7,11,6],"units":[5,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#7','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C2',1,'mc','auto','그림그래프에서 크기가 다른 그림은 각각 몇 개를 나타내나요?',ARRAY['M3-2-u6-X02','M3-2-u6-X01','M3-2-u6-X18']::text[],false,'{"seq":7,"concept":"M3-2-u6-C2","difficulty":1,"kind":"mc","stem":"그림그래프에서 크기가 다른 그림은 각각 몇 개를 나타내나요?","options":[{"t":"큰 그림 50개, 가운데 그림 10개, 작은 그림 1개","correct":true},{"t":"큰 그림 1개, 가운데 그림 10개, 작은 그림 50개","mis":"M3-2-u6-X02"},{"t":"큰 그림 1개, 가운데 그림 1개, 작은 그림 1개","mis":"M3-2-u6-X01"},{"t":"큰 그림 100개, 가운데 그림 10개, 작은 그림 1개","mis":"M3-2-u6-X18"}],"explanation":["그림그래프 아래 그림의 단위를 먼저 봐요.","큰 그림 50개, 가운데 그림 10개, 작은 그림 1개예요.","그림의 크기에 따라 나타내는 수가 달라요 — 그림을 읽기 전에 단위부터 확인해요."],"asset":{"type":"picg","title":"가게별 판매한 우산 수","head":"가게","cols":["소나기","여우비","이슬비","장맛비"],"counts":[160,105,80,91],"units":[50,10,1],"icon":"☂","unit":"개","vh":"우산의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#8','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C1',1,'sa','auto','어느 꽃집에 있는 꽃의 수를 조사하여 나타낸 표예요. 장미는 몇 송이인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u6-C1","difficulty":1,"kind":"sa","stem":"어느 꽃집에 있는 꽃의 수를 조사하여 나타낸 표예요. 장미는 몇 송이인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["합계 101송이에서 아는 수를 빼요.","모르는 수 = 합계 − 아는 수예요.","101 − 18 − 31 − 22 − 7 = 23 — 장미는 23송이예요."],"asset":{"type":"picg","only":"table","head":"종류","cols":["백합","장미","카네이션","튤립","해바라기"],"counts":[18,null,31,22,7],"unit":"송이","vh":"꽃의 수","title":"종류별 꽃의 수","total":101}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#9','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',2,'mc','auto','가게별 상추 판매량 그림그래프예요. 「㉯ 가게는 상추를 가장 많이 판매했습니다.」 ㉯ 가게는 그림그래프의 어느 가게인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X03']::text[],false,'{"seq":9,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"가게별 상추 판매량 그림그래프예요. 「㉯ 가게는 상추를 가장 많이 판매했습니다.」 ㉯ 가게는 그림그래프의 어느 가게인가요?","options":[{"t":"㉡","correct":true},{"t":"㉢","mis":"M3-2-u6-X04"},{"t":"㉠","mis":"M3-2-u6-X03"}],"explanation":["㉠ 40상자, ㉡ 42상자, ㉢ 34상자예요.","큰 그림이 4개로 같은 ㉠과 ㉡은 작은 그림으로 견줘요 — ㉡이 2상자 더 많아요.","㉢은 그림이 7개로 가장 많지만 34상자예요 — 답은 ㉡이에요."],"asset":{"type":"picg","title":"가게별 상추 판매량","head":"가게","cols":["㉠","㉡","㉢"],"counts":[40,42,34],"units":[10,1],"icon":"🥬","unit":"상자","vh":"상추 판매량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#10','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 여우비 가게에서 판매한 우산은 몇 개인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 여우비 가게에서 판매한 우산은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["105"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 50개, 가운데 그림 10개, 작은 그림 1개.","여우비 줄은 50개 그림 2개와 1개 그림 5개 — 50 × 2 + 1 × 5 = 105.","여우비 가게에서 판매한 우산은 105개예요."],"asset":{"type":"picg","title":"가게별 판매한 우산 수","head":"가게","cols":["소나기","여우비","이슬비","장맛비"],"counts":[160,105,80,91],"units":[50,10,1],"icon":"☂","unit":"개","vh":"우산의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#11','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',2,'mc','auto','좋아하는 민속놀이별 3학년 학생 수 그림그래프예요. 3학년 학생들이 두 번째로 좋아하는 민속놀이는 무엇인가요?',ARRAY['M3-2-u6-X16','M3-2-u6-X03']::text[],false,'{"seq":11,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"좋아하는 민속놀이별 3학년 학생 수 그림그래프예요. 3학년 학생들이 두 번째로 좋아하는 민속놀이는 무엇인가요?","options":[{"t":"줄다리기","correct":true},{"t":"윷놀이","mis":"M3-2-u6-X16"},{"t":"연날리기","mis":"M3-2-u6-X03"},{"t":"투호","mis":"M3-2-u6-X03"}],"explanation":["연날리기 23명, 윷놀이 30명, 줄다리기 25명, 투호 12명이에요.","좋아하는 차례는 윷놀이, 줄다리기, 연날리기, 투호예요.","두 번째는 줄다리기예요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 3학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[23,30,25,12],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#12','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 윷놀이를 좋아하는 4학년 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 윷놀이를 좋아하는 4학년 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["33"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","윷놀이 줄은 10명 그림 3개와 1명 그림 3개 — 10 × 3 + 1 × 3 = 33.","윷놀이를 좋아하는 4학년 학생은 33명이에요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 4학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[13,33,22,21],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#13','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',2,'mc','auto','만화 속 좋아하는 운동별 사람 수 그림그래프예요. 가장 적은 사람이 좋아하는 운동은 무엇인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X16']::text[],false,'{"seq":13,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"만화 속 좋아하는 운동별 사람 수 그림그래프예요. 가장 적은 사람이 좋아하는 운동은 무엇인가요?","options":[{"t":"농구","correct":true},{"t":"야구","mis":"M3-2-u6-X03"},{"t":"축구","mis":"M3-2-u6-X16"},{"t":"탁구","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","농구 5명, 야구 7명, 축구 11명, 탁구 6명.","가장 적은 것은 농구예요."],"asset":{"type":"picg","title":"좋아하는 운동별 사람 수","head":"운동","cols":["농구","야구","축구","탁구"],"counts":[5,7,11,6],"units":[5,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#14','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C2',2,'sa','auto','민서네 학교 3학년 학생들이 좋아하는 과일 그림그래프예요. 포도를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"민서네 학교 3학년 학생들이 좋아하는 과일 그림그래프예요. 포도를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["102"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","포도 줄은 10명 그림 10개와 1명 그림 2개 — 10 × 10 + 1 × 2 = 102.","포도를 좋아하는 학생은 102명이에요."],"asset":{"type":"picg","title":"좋아하는 과일별 학생 수","head":"과일","cols":["매실","배","사과","포도","한라봉"],"counts":[6,24,null,102,72],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[2]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#15','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C8',2,'sa','auto','1학년 학생은 105명이에요. 50명·10명·1명의 세 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u6-C8","difficulty":2,"kind":"sa","stem":"1학년 학생은 105명이에요. 50명·10명·1명의 세 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["큰 수를 나타내는 그림부터 그려요.","105명 = 50명 그림 2개, 10명 그림 0개, 1명 그림 5개.","2 + 0 + 5 = 7 — 그림은 모두 7개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#16','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C7',2,'mc','auto','배를 좋아하는 학생은 14명이에요. 5명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],false,'{"seq":16,"concept":"M3-2-u6-C7","difficulty":2,"kind":"mc","stem":"배를 좋아하는 학생은 14명이에요. 5명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"5명 그림 2개, 1명 그림 4개","correct":true},{"t":"5명 그림 4개, 1명 그림 2개","mis":"M3-2-u6-X05"},{"t":"1명 그림 14개","mis":"M3-2-u6-X06"},{"t":"5명 그림 3개, 1명 그림 4개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","14명 안에 5명이 2번 들어가요 — 남은 4명은 1명 그림으로 나타내요.","답은 5명 그림 2개, 1명 그림 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#17','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',3,'mc','auto','3학년과 4학년의 좋아하는 민속놀이 그림그래프에서 같은 점으로 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X01','M3-2-u6-X03']::text[],false,'{"seq":17,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"3학년과 4학년의 좋아하는 민속놀이 그림그래프에서 같은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 학년 모두 윷놀이를 좋아하는 학생이 가장 많아요","correct":true},{"t":"두 학년 모두 투호를 좋아하는 학생이 가장 적어요","mis":"M3-2-u6-X04"},{"t":"두 학년 모두 연날리기를 좋아하는 학생 수가 같아요","mis":"M3-2-u6-X01"},{"t":"두 학년 모두 줄다리기를 좋아하는 학생이 가장 많아요","mis":"M3-2-u6-X03"}],"explanation":["3학년: 윷놀이 30명이 가장 많고, 투호 12명이 가장 적어요.","4학년: 윷놀이 33명이 가장 많고, 연날리기 13명이 가장 적어요.","같은 점은 윷놀이가 가장 많다는 것이에요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 4학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[13,33,22,21],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#18','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',3,'sa','auto','3학년과 4학년 학생들이 함께 모여 민속놀이를 하려고 해요. 윷놀이를 좋아하는 3학년과 4학년 학생은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M3-2-u6-C3","difficulty":3,"kind":"sa","stem":"3학년과 4학년 학생들이 함께 모여 민속놀이를 하려고 해요. 윷놀이를 좋아하는 3학년과 4학년 학생은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["63"],"explanation":["3학년 윷놀이 30명, 4학년 윷놀이 33명이에요.","두 학년을 더해요.","30 + 33 = 63 — 모두 63명이에요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 4학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[13,33,22,21],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#19','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',3,'sa','auto','민서네 학교 3학년 과일 그림그래프에서 포도를 좋아하는 학생 수는 매실을 좋아하는 학생 수의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M3-2-u6-C3","difficulty":3,"kind":"sa","stem":"민서네 학교 3학년 과일 그림그래프에서 포도를 좋아하는 학생 수는 매실을 좋아하는 학생 수의 몇 배인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["포도는 10명 그림 10개와 1명 그림 2개 — 102명, 매실은 1명 그림 6개 — 6명이에요.","몇 배인지는 나눗셈으로 구해요.","102 ÷ 6 = 17 — 17배예요."],"asset":{"type":"picg","title":"좋아하는 과일별 학생 수","head":"과일","cols":["매실","배","사과","포도","한라봉"],"counts":[6,24,null,102,72],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[2]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#20','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',3,'mc','auto','우산 가게 이름 찾기 — 「㉯ 가게는 우산을 91개 판매했습니다.」 ㉯ 가게는 어디인가요?',ARRAY['M3-2-u6-X02','M3-2-u6-X01']::text[],false,'{"seq":20,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"우산 가게 이름 찾기 — 「㉯ 가게는 우산을 91개 판매했습니다.」 ㉯ 가게는 어디인가요?","options":[{"t":"장맛비","correct":true},{"t":"이슬비","mis":"M3-2-u6-X02"},{"t":"여우비","mis":"M3-2-u6-X01"},{"t":"소나기","mis":"M3-2-u6-X02"}],"explanation":["그림의 단위는 50개, 10개, 1개예요.","장맛비는 50개 그림 1개, 10개 그림 4개, 1개 그림 1개 — 50 × 1 + 10 × 4 + 1 × 1 = 91이에요.","91개를 판매한 가게는 장맛비예요."],"asset":{"type":"picg","title":"가게별 판매한 우산 수","head":"가게","cols":["소나기","여우비","이슬비","장맛비"],"counts":[160,105,80,91],"units":[50,10,1],"icon":"☂","unit":"개","vh":"우산의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#21','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C2',3,'sa','auto','그림그래프를 보고 ㉣ 프로그램을 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u6-C2","difficulty":3,"kind":"sa","stem":"그림그래프를 보고 ㉣ 프로그램을 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["16"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","㉣ 줄은 10명 그림 1개와 1명 그림 6개 — 10 × 1 + 1 × 6 = 16.","㉣ 프로그램을 좋아하는 사람은 16명이에요."],"asset":{"type":"picg","title":"좋아하는 텔레비전 프로그램별 사람 수","head":"프로그램","cols":["㉠","㉡","㉢","㉣"],"counts":[12,21,14,16],"units":[10,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#22','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C9',3,'ox','auto','「쓰레기 배출량이 2배가 된 것을 나타내려고 그림의 가로와 세로를 모두 2배로 그리면, 그림도 꼭 2배만큼 커 보인다.」 맞으면 ○, 틀리면 ×를 고르세요.',ARRAY['M3-2-u6-X15']::text[],false,'{"seq":22,"concept":"M3-2-u6-C9","difficulty":3,"kind":"ox","stem":"「쓰레기 배출량이 2배가 된 것을 나타내려고 그림의 가로와 세로를 모두 2배로 그리면, 그림도 꼭 2배만큼 커 보인다.」 맞으면 ○, 틀리면 ×를 고르세요.","answer":"X","reason_options":[{"t":"가로와 세로가 모두 2배면 넓이는 4배라 실제보다 더 많아 보여요","correct":true},{"t":"가로와 세로를 2배로 하면 넓이도 2배예요","mis":"M3-2-u6-X15"}],"mis":"M3-2-u6-X15","explanation":["넓이는 가로와 세로를 곱한 만큼 커져요.","2 × 2 = 4 — 그림은 4배로 커 보여요.","자료의 수치를 무시한 그림은 자료를 왜곡해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#23','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C4',4,'essay','teacher','「그림그래프에서 그림을 ◎, △, ○로 나타내어도 되나요?」라는 질문에 답을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u6-C4","difficulty":4,"kind":"essay","stem":"「그림그래프에서 그림을 ◎, △, ○로 나타내어도 되나요?」라는 질문에 답을 써 보세요.","answer_guide":{"answer":"예: 된다. 자료의 수를 비교하는 것이 목적이면 ◎, △, ○처럼 손쉽게 그릴 수 있는 그림을 써도 된다. 다만 각 그림이 나타내는 자료의 수(단위)를 분명히 하고 수에 따라 그림의 크기를 달리해야 한다. 조사한 내용(학생, 사과 등)을 그린 그림이면 무엇을 조사했는지 더 쉽게 알 수 있다.","scoring_points":["써도 된다는 답과 까닭을 썼는가","그림의 단위를 분명히 해야 한다고 썼는가","조사한 내용을 나타내는 그림의 좋은 점을 썼는가"]},"explanation":["그림그래프는 그림으로 무엇을 조사했는지 한눈에 알게 해 줘요.","간단한 기호도 그림이 나타내는 수를 분명히 하면 쓸 수 있어요.","학생 수면 학생 그림, 사과 생산량이면 사과 그림이 더 알기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#24','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C3',4,'essay','teacher','민서네 학교 3학년 과일 그림그래프를 보고, 곱셈·나눗셈·분수에서 배운 내용으로 알 수 있는 사실을 두 가지 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u6-C3","difficulty":4,"kind":"essay","stem":"민서네 학교 3학년 과일 그림그래프를 보고, 곱셈·나눗셈·분수에서 배운 내용으로 알 수 있는 사실을 두 가지 써 보세요.","answer_guide":{"answer":"예: 포도를 좋아하는 학생 수(102명)는 매실을 좋아하는 학생 수(6명)의 17배이다(102 ÷ 6 = 17). 배를 좋아하는 학생 수의 3배(24 × 3 = 72)만큼의 학생이 좋아하는 과일은 한라봉이다. 매실을 좋아하는 학생 수의 3분의 1은 2명이다.","scoring_points":["그림그래프의 수를 바르게 읽었는가","곱셈·나눗셈·분수 가운데 두 가지를 써서 사실을 찾았는가","식과 답이 맞는가"]},"explanation":["매실 6, 배 24, 사과 84, 포도 102, 한라봉 72명이에요.","102 ÷ 6 = 17, 24 × 3 = 72예요.","6의 3분의 1은 2예요."],"asset":{"type":"picg","title":"좋아하는 과일별 학생 수","head":"과일","cols":["매실","배","사과","포도","한라봉"],"counts":[6,24,84,102,72],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_b#25','math',3,2,'u6','','tb_g3_2_math_u6_review_b','unit_review','M3-2-u6-C5',4,'essay','teacher','지유네 학교 영양 선생님께서 급식으로 우리나라 전통 음식을 한 가지 준비하려고 해요. 한 친구는 떡국, 다른 친구는 식혜를 골랐어요. 두 의견의 까닭을 그림그래프를 근거로 각각 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u6-C5","difficulty":4,"kind":"essay","stem":"지유네 학교 영양 선생님께서 급식으로 우리나라 전통 음식을 한 가지 준비하려고 해요. 한 친구는 떡국, 다른 친구는 식혜를 골랐어요. 두 의견의 까닭을 그림그래프를 근거로 각각 써 보세요.","answer_guide":{"answer":"떡국: 가장 많은 학생(130명)이 좋아하는 우리나라 전통 음식이기 때문이다. 식혜: 가장 적은 학생(26명)이 좋아하지만, 급식으로 맛있게 만들어 더 많은 학생이 식혜를 좋아하게 할 수 있기 때문이다.","scoring_points":["떡국 130명이 가장 많다는 근거를 썼는가","식혜 26명이 가장 적다는 사실을 바르게 썼는가","두 의견 모두 그림그래프의 수를 근거로 썼는가"]},"explanation":["떡국 130명이 가장 많고 식혜 26명이 가장 적어요.","같은 그림그래프로도 목적에 따라 다른 결정을 할 수 있어요.","어느 의견이든 그림그래프에서 읽은 사실로 까닭을 대요."],"asset":{"type":"picg","title":"좋아하는 우리나라 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜","잡채"],"counts":[130,115,100,26,40],"units":[100,10,1],"icon":"🍚","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#1','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C6',1,'blank','auto','「② □을/를 정해 자료를 수집합니다.」 □에 알맞은 말은 무엇인가요?',ARRAY['M3-2-u6-X12']::text[],false,'{"seq":1,"concept":"M3-2-u6-C6","difficulty":1,"kind":"blank","stem":"「② □을/를 정해 자료를 수집합니다.」 □에 알맞은 말은 무엇인가요?","options":[{"t":"조사 방법","correct":true},{"t":"그림의 단위","mis":"M3-2-u6-X12"},{"t":"제목","mis":"M3-2-u6-X12"},{"t":"합계","mis":"M3-2-u6-X12"}],"explanation":["정리 — 그림그래프는 조사한 자료의 수를 그림으로 나타낸 그래프예요.","자료를 수집하여 그림그래프로: ① 주제와 대상·항목 ② 조사 방법 ③ 표 ④ 그림그래프·해석.","□에 알맞은 말은 조사 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#2','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C3',1,'mc','auto','그림그래프에서 가장 많은 학생이 가고 싶어 하는 체험 학습 장소는 어디인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X03']::text[],false,'{"seq":2,"concept":"M3-2-u6-C3","difficulty":1,"kind":"mc","stem":"그림그래프에서 가장 많은 학생이 가고 싶어 하는 체험 학습 장소는 어디인가요?","options":[{"t":"놀이공원","correct":true},{"t":"과학관","mis":"M3-2-u6-X04"},{"t":"동물원","mis":"M3-2-u6-X03"},{"t":"박물관","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","과학관 7명, 놀이공원 42명, 동물원 30명, 박물관 13명.","가장 많은 것은 놀이공원이에요."],"asset":{"type":"picg","title":"가고 싶어 하는 체험 학습 장소별 학생 수","head":"장소","cols":["과학관","놀이공원","동물원","박물관"],"counts":[7,42,30,13],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#3','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C2',1,'sa','auto','그림그래프를 보고 판매한 초코도넛은 몇 개인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u6-C2","difficulty":1,"kind":"sa","stem":"그림그래프를 보고 판매한 초코도넛은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["33"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10개, 작은 그림 1개.","초코도넛 줄은 10개 그림 3개와 1개 그림 3개 — 10 × 3 + 1 × 3 = 33.","판매한 초코도넛은 33개예요."],"asset":{"type":"picg","title":"종류별 판매한 도넛의 수","head":"종류","cols":["딸기도넛","블루베리도넛","초코도넛","크림도넛"],"counts":[42,28,33,52],"units":[10,1],"icon":"🍩","unit":"개","vh":"도넛의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#4','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C4',1,'mc','auto','카네이션은 31송이예요. 5송이·1송이의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],false,'{"seq":4,"concept":"M3-2-u6-C4","difficulty":1,"kind":"mc","stem":"카네이션은 31송이예요. 5송이·1송이의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"5송이 그림 6개, 1송이 그림 1개","correct":true},{"t":"5송이 그림 1개, 1송이 그림 6개","mis":"M3-2-u6-X05"},{"t":"1송이 그림 31개","mis":"M3-2-u6-X06"},{"t":"5송이 그림 7개, 1송이 그림 1개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","31송이 안에 5송이가 6번 들어가요 — 남은 1송이는 1송이 그림으로 나타내요.","답은 5송이 그림 6개, 1송이 그림 1개예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"종류","cols":["백합","장미","카네이션","튤립","해바라기"],"counts":[18,23,31,22,7],"units":[5,1],"icon":"🌸","unit":"송이","vh":"꽃의 수","table":true,"blank":[2]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#5','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C2',1,'error','auto','좋아하는 우리나라 전통 음식별 학생 수 그림그래프를 보고 알 수 있는 내용으로 옳지 않은 것은 어느 것인가요?',ARRAY['M3-2-u6-X01','M3-2-u6-X16']::text[],false,'{"seq":5,"concept":"M3-2-u6-C2","difficulty":1,"kind":"error","stem":"좋아하는 우리나라 전통 음식별 학생 수 그림그래프를 보고 알 수 있는 내용으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"비빔밥을 좋아하는 학생은 그림이 1개라 1명이에요","correct":true,"mis_target":"M3-2-u6-X01"},{"t":"식혜를 좋아하는 학생은 26명이에요","mis":"M3-2-u6-X16"},{"t":"불고기를 좋아하는 학생보다 더 많은 학생이 좋아하는 음식은 떡국이에요","mis":"M3-2-u6-X16"}],"explanation":["그림의 단위는 100명, 10명, 1명이에요.","비빔밥은 100명 그림 1개 — 100명이에요.","그림의 개수만 세면 안 돼요 — 옳지 않은 것은 비빔밥 1명이에요."],"asset":{"type":"picg","title":"좋아하는 우리나라 전통 음식별 학생 수","head":"음식","cols":["떡국","불고기","비빔밥","식혜","잡채"],"counts":[130,115,100,26,40],"units":[100,10,1],"icon":"🍚","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#6','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C2',1,'sa','auto','그림그래프를 보고 탁구를 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u6-C2","difficulty":1,"kind":"sa","stem":"그림그래프를 보고 탁구를 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["6"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 5명, 작은 그림 1명.","탁구 줄은 5명 그림 1개와 1명 그림 1개 — 5 × 1 + 1 × 1 = 6.","탁구를 좋아하는 사람은 6명이에요."],"asset":{"type":"picg","title":"좋아하는 운동별 사람 수","head":"운동","cols":["농구","야구","축구","탁구"],"counts":[5,7,11,6],"units":[5,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#7','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C2',1,'mc','auto','그림그래프에서 크기가 다른 그림은 각각 몇 상자를 나타내나요?',ARRAY['M3-2-u6-X02','M3-2-u6-X01','M3-2-u6-X18']::text[],false,'{"seq":7,"concept":"M3-2-u6-C2","difficulty":1,"kind":"mc","stem":"그림그래프에서 크기가 다른 그림은 각각 몇 상자를 나타내나요?","options":[{"t":"큰 그림 10상자, 작은 그림 1상자","correct":true},{"t":"큰 그림 1상자, 작은 그림 10상자","mis":"M3-2-u6-X02"},{"t":"큰 그림 1상자, 작은 그림 1상자","mis":"M3-2-u6-X01"},{"t":"큰 그림 20상자, 작은 그림 1상자","mis":"M3-2-u6-X18"}],"explanation":["그림그래프 아래 그림의 단위를 먼저 봐요.","큰 그림 10상자, 작은 그림 1상자예요.","그림의 크기에 따라 나타내는 수가 달라요 — 그림을 읽기 전에 단위부터 확인해요."],"asset":{"type":"picg","title":"가게별 상추 판매량","head":"가게","cols":["㉠","㉡","㉢"],"counts":[40,42,34],"units":[10,1],"icon":"🥬","unit":"상자","vh":"상추 판매량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#8','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C1',1,'sa','auto','좋아하는 채소별 학생 수를 조사하여 나타낸 표예요. 조사한 학생은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u6-C1","difficulty":1,"kind":"sa","stem":"좋아하는 채소별 학생 수를 조사하여 나타낸 표예요. 조사한 학생은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["87"],"explanation":["합계는 모두 더한 수예요.","당근 18명, 시금치 10명, 오이 24명, 콩나물 35명이에요.","18 + 10 + 24 + 35 = 87 — 모두 87명이에요."],"asset":{"type":"picg","only":"table","head":"채소","cols":["당근","시금치","오이","콩나물"],"counts":[18,10,24,35],"unit":"명","vh":"학생 수","title":"좋아하는 채소별 학생 수","total":null}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#9','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C3',2,'mc','auto','가게별 상추 판매량 그림그래프예요. 「㉰ 가게는 상추를 두 번째로 많이 판매했습니다.」 ㉰ 가게는 그림그래프의 어느 가게인가요?',ARRAY['M3-2-u6-X16','M3-2-u6-X04']::text[],false,'{"seq":9,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"가게별 상추 판매량 그림그래프예요. 「㉰ 가게는 상추를 두 번째로 많이 판매했습니다.」 ㉰ 가게는 그림그래프의 어느 가게인가요?","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M3-2-u6-X16"},{"t":"㉢","mis":"M3-2-u6-X04"}],"explanation":["㉠ 40상자, ㉡ 42상자, ㉢ 34상자예요.","많은 차례는 ㉡, ㉠, ㉢이에요.","두 번째로 많이 판매한 가게는 ㉠이에요."],"asset":{"type":"picg","title":"가게별 상추 판매량","head":"가게","cols":["㉠","㉡","㉢"],"counts":[40,42,34],"units":[10,1],"icon":"🥬","unit":"상자","vh":"상추 판매량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#10','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 소나기 가게에서 판매한 우산은 몇 개인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 소나기 가게에서 판매한 우산은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["160"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 50개, 가운데 그림 10개, 작은 그림 1개.","소나기 줄은 50개 그림 3개와 10개 그림 1개 — 50 × 3 + 10 × 1 = 160.","소나기 가게에서 판매한 우산은 160개예요."],"asset":{"type":"picg","title":"가게별 판매한 우산 수","head":"가게","cols":["소나기","여우비","이슬비","장맛비"],"counts":[160,105,80,91],"units":[50,10,1],"icon":"☂","unit":"개","vh":"우산의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#11','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C3',2,'mc','auto','좋아하는 민속놀이별 4학년 학생 수 그림그래프예요. 4학년 학생들이 가장 적게 좋아하는 민속놀이는 무엇인가요?',ARRAY['M3-2-u6-X16','M3-2-u6-X03','M3-2-u6-X04']::text[],false,'{"seq":11,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"좋아하는 민속놀이별 4학년 학생 수 그림그래프예요. 4학년 학생들이 가장 적게 좋아하는 민속놀이는 무엇인가요?","options":[{"t":"연날리기","correct":true},{"t":"윷놀이","mis":"M3-2-u6-X16"},{"t":"줄다리기","mis":"M3-2-u6-X03"},{"t":"투호","mis":"M3-2-u6-X04"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","연날리기 13명, 윷놀이 33명, 줄다리기 22명, 투호 21명.","가장 적은 것은 연날리기예요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 4학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[13,33,22,21],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#12','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 투호를 좋아하는 4학년 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 투호를 좋아하는 4학년 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["21"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","투호 줄은 10명 그림 2개와 1명 그림 1개 — 10 × 2 + 1 × 1 = 21.","투호를 좋아하는 4학년 학생은 21명이에요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 4학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[13,33,22,21],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#13','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C3',2,'sa','auto','그림그래프를 보고 야구를 좋아하는 사람은 탁구를 좋아하는 사람보다 몇 명 더 많은지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M3-2-u6-C3","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 야구를 좋아하는 사람은 탁구를 좋아하는 사람보다 몇 명 더 많은지 구하세요. 숫자로 쓰세요.","answer":["1"],"explanation":["두 항목의 수를 먼저 읽어요 — 야구 7명, 탁구 6명.","몇 개 더 많은지는 뺄셈으로 구해요.","7 − 6 = 1 — 1명 더 많아요."],"asset":{"type":"picg","title":"좋아하는 운동별 사람 수","head":"운동","cols":["농구","야구","축구","탁구"],"counts":[5,7,11,6],"units":[5,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#14','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C2',2,'sa','auto','민서네 학교 3학년 학생들이 좋아하는 과일 그림그래프예요. 배를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"민서네 학교 3학년 학생들이 좋아하는 과일 그림그래프예요. 배를 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["24"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","배 줄은 10명 그림 2개와 1명 그림 4개 — 10 × 2 + 1 × 4 = 24.","배를 좋아하는 학생은 24명이에요."],"asset":{"type":"picg","title":"좋아하는 과일별 학생 수","head":"과일","cols":["매실","배","사과","포도","한라봉"],"counts":[6,24,null,102,72],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[2]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#15','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C8',2,'sa','auto','1학년 학생은 105명이에요. 100명·10명·1명의 세 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u6-C8","difficulty":2,"kind":"sa","stem":"1학년 학생은 105명이에요. 100명·10명·1명의 세 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["큰 수를 나타내는 그림부터 그려요.","105명 = 100명 그림 1개, 10명 그림 0개, 1명 그림 5개.","1 + 0 + 5 = 6 — 그림은 모두 6개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#16','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C4',2,'mc','auto','독서 동아리에 가입한 학생은 35명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],false,'{"seq":16,"concept":"M3-2-u6-C4","difficulty":2,"kind":"mc","stem":"독서 동아리에 가입한 학생은 35명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"10명 그림 3개, 1명 그림 5개","correct":true},{"t":"10명 그림 5개, 1명 그림 3개","mis":"M3-2-u6-X05"},{"t":"1명 그림 35개","mis":"M3-2-u6-X06"},{"t":"10명 그림 4개, 1명 그림 5개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","35명 안에 10명이 3번 들어가요 — 남은 5명은 1명 그림으로 나타내요.","답은 10명 그림 3개, 1명 그림 5개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#17','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C3',3,'mc','auto','3학년과 4학년의 좋아하는 민속놀이 그림그래프에서 다른 점으로 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u6-X04']::text[],false,'{"seq":17,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"3학년과 4학년의 좋아하는 민속놀이 그림그래프에서 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"가장 적은 학생이 좋아하는 민속놀이가 3학년은 투호, 4학년은 연날리기예요","correct":true},{"t":"가장 많은 학생이 좋아하는 민속놀이가 3학년은 줄다리기, 4학년은 윷놀이예요","mis":"M3-2-u6-X04"},{"t":"3학년은 그림이 많은 줄다리기를 가장 좋아해요","mis":"M3-2-u6-X04"},{"t":"4학년은 투호를 가장 적게 좋아해요","mis":"M3-2-u6-X04"}],"explanation":["3학년 투호 12명이 가장 적어요.","4학년 연날리기 13명이 가장 적어요 — 투호는 21명이에요.","가장 많은 것은 두 학년 모두 윷놀이예요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 4학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[13,33,22,21],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#18','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C5',3,'mc','auto','3학년과 4학년 학생들이 모두 두 번째로 좋아하는 민속놀이는 무엇인가요?',ARRAY['M3-2-u6-X16','M3-2-u6-X04','M3-2-u6-X03']::text[],false,'{"seq":18,"concept":"M3-2-u6-C5","difficulty":3,"kind":"mc","stem":"3학년과 4학년 학생들이 모두 두 번째로 좋아하는 민속놀이는 무엇인가요?","options":[{"t":"줄다리기","correct":true},{"t":"윷놀이","mis":"M3-2-u6-X16"},{"t":"투호","mis":"M3-2-u6-X04"},{"t":"연날리기","mis":"M3-2-u6-X03"}],"explanation":["3학년: 윷놀이 30, 줄다리기 25, 연날리기 23, 투호 12명이에요.","4학년: 윷놀이 33, 줄다리기 22, 투호 21, 연날리기 13명이에요.","두 학년 모두 두 번째는 줄다리기예요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 3학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[23,30,25,12],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#19','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C3',3,'mc','auto','민서네 학교 3학년 과일 그림그래프에서 배를 좋아하는 학생 수의 3배만큼의 학생이 좋아하는 과일은 무엇인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X08']::text[],false,'{"seq":19,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"민서네 학교 3학년 과일 그림그래프에서 배를 좋아하는 학생 수의 3배만큼의 학생이 좋아하는 과일은 무엇인가요?","options":[{"t":"한라봉","correct":true},{"t":"포도","mis":"M3-2-u6-X03"},{"t":"매실","mis":"M3-2-u6-X08"},{"t":"사과","mis":"M3-2-u6-X03"}],"explanation":["배를 좋아하는 학생은 24명이에요.","24 × 3 = 72예요.","72명이 좋아하는 과일은 한라봉이에요."],"asset":{"type":"picg","title":"좋아하는 과일별 학생 수","head":"과일","cols":["매실","배","사과","포도","한라봉"],"counts":[6,24,null,102,72],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[2]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#20','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C3',3,'mc','auto','우산 가게 이름 찾기 — 「㉰ 가게는 우산을 가장 많이 판매했습니다.」 ㉰ 가게는 어디인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16','M3-2-u6-X03']::text[],false,'{"seq":20,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"우산 가게 이름 찾기 — 「㉰ 가게는 우산을 가장 많이 판매했습니다.」 ㉰ 가게는 어디인가요?","options":[{"t":"소나기","correct":true},{"t":"여우비","mis":"M3-2-u6-X04"},{"t":"이슬비","mis":"M3-2-u6-X16"},{"t":"장맛비","mis":"M3-2-u6-X03"}],"explanation":["소나기 160개, 여우비 105개, 이슬비 80개, 장맛비 91개예요.","50개 그림이 가장 많은 소나기가 가장 많아요.","여우비는 그림이 7개로 가장 많지만 105개예요."],"asset":{"type":"picg","title":"가게별 판매한 우산 수","head":"가게","cols":["소나기","여우비","이슬비","장맛비"],"counts":[160,105,80,91],"units":[50,10,1],"icon":"☂","unit":"개","vh":"우산의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#21','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C3',3,'mc','auto','좋아하는 텔레비전 프로그램별 사람 수 그림그래프예요. 그림의 모양과 개수가 같은 ㉠과 ㉡에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X01','M3-2-u6-X02']::text[],false,'{"seq":21,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"좋아하는 텔레비전 프로그램별 사람 수 그림그래프예요. 그림의 모양과 개수가 같은 ㉠과 ㉡에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"㉠은 12명, ㉡은 21명으로 그림의 크기에 따라 나타내는 수가 달라요","correct":true},{"t":"그림의 모양이 같으니 나타내는 수도 모두 같아요","mis":"M3-2-u6-X03"},{"t":"㉠과 ㉡은 그림이 3개씩이라 3명씩이에요","mis":"M3-2-u6-X01"},{"t":"㉠은 21명, ㉡은 12명이에요","mis":"M3-2-u6-X02"}],"explanation":["같은 모양의 그림이라도 크기에 따라 나타내는 수가 달라요.","㉠은 10명 그림 1개와 1명 그림 2개, ㉡은 10명 그림 2개와 1명 그림 1개예요.","그래서 ㉠은 12명, ㉡은 21명이에요."],"asset":{"type":"picg","title":"좋아하는 텔레비전 프로그램별 사람 수","head":"프로그램","cols":["㉠","㉡","㉢","㉣"],"counts":[12,21,14,16],"units":[10,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#22','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C9',3,'mc','auto','그림그래프를 그릴 때 1명을 나타내는 그림과 10명을 나타내는 그림을 어떻게 그리나요?',ARRAY['M3-2-u6-X15','M3-2-u6-X01']::text[],false,'{"seq":22,"concept":"M3-2-u6-C9","difficulty":3,"kind":"mc","stem":"그림그래프를 그릴 때 1명을 나타내는 그림과 10명을 나타내는 그림을 어떻게 그리나요?","options":[{"t":"10명 그림을 1명 그림보다 다소 크게 그리고, 수는 그림의 개수로 나타내요","correct":true},{"t":"10명 그림은 1명 그림보다 꼭 10배 넓게 그려요","mis":"M3-2-u6-X15"},{"t":"두 그림을 똑같은 크기로 그려요","mis":"M3-2-u6-X01"},{"t":"수가 많은 항목일수록 그림을 크게 그려요","mis":"M3-2-u6-X15"}],"explanation":["정확히 10배 크기의 그림을 그리기는 어려워요.","그래서 10명 그림은 다소 크게 그리고, 7명은 1명 그림 7개처럼 개수로 나타내요.","그림의 개수와 단위로 수를 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#23','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C2',4,'essay','teacher','만화에서 친구가 그림그래프를 보고 「축구를 좋아하는 사람이 21명이나 되는구나!」라고 했어요. 무엇을 잘못 읽었는지 쓰고, 축구를 좋아하는 사람은 몇 명인지 바르게 구해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u6-C2","difficulty":4,"kind":"essay","stem":"만화에서 친구가 그림그래프를 보고 「축구를 좋아하는 사람이 21명이나 되는구나!」라고 했어요. 무엇을 잘못 읽었는지 쓰고, 축구를 좋아하는 사람은 몇 명인지 바르게 구해 보세요.","answer_guide":{"answer":"그림의 단위를 잘못 읽었다 — 큰 그림을 10명으로 읽어 21명이라고 했다. 큰 그림은 5명, 작은 그림은 1명이므로 축구는 5명 그림 2개와 1명 그림 1개, 5 × 2 + 1 × 1 = 11(명)이다.","scoring_points":["그림의 단위를 잘못 읽었다고 썼는가","큰 그림 5명, 작은 그림 1명을 찾았는가","11명을 구했는가"]},"explanation":["그림의 단위는 큰 그림 5명, 작은 그림 1명이에요.","큰 그림 2개를 10명씩으로 읽으면 21명이 돼요.","5 × 2 + 1 × 1 = 11 — 축구를 좋아하는 사람은 11명이에요."],"asset":{"type":"picg","title":"좋아하는 운동별 사람 수","head":"운동","cols":["농구","야구","축구","탁구"],"counts":[5,7,11,6],"units":[5,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#24','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C8',4,'essay','teacher','같은 2022년 산불 자료를 가(10건·1건)와 나(100건·10건·1건) 그림그래프로 나타냈어요. 봄(377건)을 나타내는 그림 수를 두 그래프에서 각각 구하고, 자료의 수가 클 때 어떤 그림그래프가 알맞은지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u6-C8","difficulty":4,"kind":"essay","stem":"같은 2022년 산불 자료를 가(10건·1건)와 나(100건·10건·1건) 그림그래프로 나타냈어요. 봄(377건)을 나타내는 그림 수를 두 그래프에서 각각 구하고, 자료의 수가 클 때 어떤 그림그래프가 알맞은지 까닭과 함께 써 보세요.","answer_guide":{"answer":"가: 10건 그림 37개와 1건 그림 7개, 모두 44개. 나: 100건 그림 3개, 10건 그림 7개, 1건 그림 7개, 모두 17개. 자료의 수가 클 때는 단위의 종류가 많은 나 그림그래프가 그림을 적게 그려도 되어 알맞다(다만 그림의 크기를 잘 구분해야 한다).","scoring_points":["가 44개를 구했는가","나 17개를 구했는가","수가 클 때 단위의 종류가 많은 것이 알맞다는 까닭을 썼는가"]},"explanation":["가: 37 + 7 = 44예요.","나: 3 + 7 + 7 = 17이에요.","단위의 종류가 늘면 큰 수를 효과적으로 나타낼 수 있어요."],"asset":{"type":"picg","title":"2022년 계절별 산불 발생 건수","head":"계절","cols":["봄(3, 4, 5월)","여름(6, 7, 8월)","가을(9, 10, 11월)","겨울(12, 1, 2월)"],"counts":[377,29,82,268],"units":[10,1],"icon":"🔥","unit":"건","vh":"건수","units2":[100,10,1],"table":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_c#25','math',3,2,'u6','','tb_g3_2_math_u6_review_c','unit_review','M3-2-u6-C4',4,'essay','teacher','단원 도입 — 공원에서 「좋아하는 운동별 사람 수를 조사하여 정리해 보자」 「조사한 자료를 표가 아닌 다른 방법으로 나타낼 수도 있을까?」라고 이야기했어요. 좋아하는 운동별 사람 수(농구 5명, 야구 7명, 축구 11명, 탁구 6명)를 그림그래프로 나타내는 방법을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u6-C4","difficulty":4,"kind":"essay","stem":"단원 도입 — 공원에서 「좋아하는 운동별 사람 수를 조사하여 정리해 보자」 「조사한 자료를 표가 아닌 다른 방법으로 나타낼 수도 있을까?」라고 이야기했어요. 좋아하는 운동별 사람 수(농구 5명, 야구 7명, 축구 11명, 탁구 6명)를 그림그래프로 나타내는 방법을 써 보세요.","answer_guide":{"answer":"예: 제목을 「좋아하는 운동별 사람 수」로 쓰고, 그림과 단위를 5명·1명으로 정한다. 항목(농구, 야구, 축구, 탁구)을 빠짐없이 쓰고, 농구는 5명 그림 1개, 야구는 5명 그림 1개와 1명 그림 2개, 축구는 5명 그림 2개와 1명 그림 1개, 탁구는 5명 그림 1개와 1명 그림 1개로 그린다.","scoring_points":["제목과 그림의 단위를 정했는가","항목을 빠짐없이 썼는가","네 운동을 단위에 맞게 그림으로 나타냈는가"]},"explanation":["그림그래프로 나타내는 네 걸음을 따라요.","5명·1명이면 야구 7 = 5 + 2, 축구 11 = 5 × 2 + 1이에요.","큰 그림부터 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#1','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C7',1,'blank','auto','「③ 수집한 자료를 □(으)로 나타냅니다.」 □에 알맞은 말은 무엇인가요?',ARRAY['M3-2-u6-X12']::text[],false,'{"seq":1,"concept":"M3-2-u6-C7","difficulty":1,"kind":"blank","stem":"「③ 수집한 자료를 □(으)로 나타냅니다.」 □에 알맞은 말은 무엇인가요?","options":[{"t":"표","correct":true},{"t":"제목","mis":"M3-2-u6-X12"},{"t":"조사 방법","mis":"M3-2-u6-X12"},{"t":"주제","mis":"M3-2-u6-X12"}],"explanation":["정리 — 그림그래프는 조사한 자료의 수를 그림으로 나타낸 그래프예요.","자료를 수집하여 그림그래프로: ① 주제와 대상·항목 ② 조사 방법 ③ 표 ④ 그림그래프·해석.","□에 알맞은 말은 표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#2','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C3',1,'mc','auto','그림그래프에서 가장 많은 학생이 받고 싶어 하는 선물은 무엇인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X04']::text[],false,'{"seq":2,"concept":"M3-2-u6-C3","difficulty":1,"kind":"mc","stem":"그림그래프에서 가장 많은 학생이 받고 싶어 하는 선물은 무엇인가요?","options":[{"t":"장난감","correct":true},{"t":"옷","mis":"M3-2-u6-X03"},{"t":"인형","mis":"M3-2-u6-X04"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","옷 17명, 인형 14명, 장난감 21명.","가장 많은 것은 장난감이에요."],"asset":{"type":"picg","title":"받고 싶어 하는 선물별 학생 수","head":"선물","cols":["옷","인형","장난감"],"counts":[17,14,21],"units":[5,1],"icon":"🎁","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#3','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C2',1,'sa','auto','그림그래프를 보고 판매한 블루베리도넛은 몇 개인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u6-C2","difficulty":1,"kind":"sa","stem":"그림그래프를 보고 판매한 블루베리도넛은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["28"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10개, 작은 그림 1개.","블루베리도넛 줄은 10개 그림 2개와 1개 그림 8개 — 10 × 2 + 1 × 8 = 28.","판매한 블루베리도넛은 28개예요."],"asset":{"type":"picg","title":"종류별 판매한 도넛의 수","head":"종류","cols":["딸기도넛","블루베리도넛","초코도넛","크림도넛"],"counts":[42,28,33,52],"units":[10,1],"icon":"🍩","unit":"개","vh":"도넛의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#4','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C4',1,'mc','auto','백합은 18송이예요. 5송이·1송이의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?',ARRAY['M3-2-u6-X06','M3-2-u6-X02']::text[],false,'{"seq":4,"concept":"M3-2-u6-C4","difficulty":1,"kind":"mc","stem":"백합은 18송이예요. 5송이·1송이의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"5송이 그림 3개, 1송이 그림 3개","correct":true},{"t":"1송이 그림 18개","mis":"M3-2-u6-X06"},{"t":"5송이 그림 4개, 1송이 그림 3개","mis":"M3-2-u6-X02"},{"t":"5송이 그림 3개","mis":"M3-2-u6-X06"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","18송이 안에 5송이가 3번 들어가요 — 남은 3송이는 1송이 그림으로 나타내요.","답은 5송이 그림 3개, 1송이 그림 3개예요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"종류","cols":["백합","장미","카네이션","튤립","해바라기"],"counts":[18,23,31,22,7],"units":[5,1],"icon":"🌸","unit":"송이","vh":"꽃의 수","table":true,"blank":[0]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#5','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C3',1,'error','auto','학생별 훌라후프를 한 횟수 그림그래프를 보고 알 수 있는 내용으로 옳지 않은 것은 어느 것인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16']::text[],false,'{"seq":5,"concept":"M3-2-u6-C3","difficulty":1,"kind":"error","stem":"학생별 훌라후프를 한 횟수 그림그래프를 보고 알 수 있는 내용으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"건우는 그림이 가장 많으니 훌라후프를 가장 많이 했어요","correct":true,"mis_target":"M3-2-u6-X04"},{"t":"지유는 훌라후프를 12회 했어요","mis":"M3-2-u6-X16"},{"t":"도윤이가 훌라후프를 한 횟수는 9회예요","mis":"M3-2-u6-X16"}],"explanation":["건우 19회, 도윤 9회, 은비 25회, 지유 12회예요.","훌라후프를 가장 많이 한 학생은 5회 그림이 5개인 은비예요.","건우는 그림이 7개로 가장 많지만 19회예요 — 큰 그림부터 견줘요."],"asset":{"type":"picg","title":"학생별 훌라후프를 한 횟수","head":"이름","cols":["건우","도윤","은비","지유"],"counts":[19,9,25,12],"units":[5,1],"icon":"⭕","unit":"회","vh":"횟수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#6','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C2',1,'sa','auto','그림그래프를 보고 농구를 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u6-C2","difficulty":1,"kind":"sa","stem":"그림그래프를 보고 농구를 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["5"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 5명, 작은 그림 1명.","농구 줄은 5명 그림 1개예요.","농구를 좋아하는 사람은 5명이에요."],"asset":{"type":"picg","title":"좋아하는 운동별 사람 수","head":"운동","cols":["농구","야구","축구","탁구"],"counts":[5,7,11,6],"units":[5,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#7','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C2',1,'mc','auto','그림그래프에서 크기가 다른 그림은 각각 몇 명을 나타내나요?',ARRAY['M3-2-u6-X02','M3-2-u6-X01','M3-2-u6-X18']::text[],false,'{"seq":7,"concept":"M3-2-u6-C2","difficulty":1,"kind":"mc","stem":"그림그래프에서 크기가 다른 그림은 각각 몇 명을 나타내나요?","options":[{"t":"큰 그림 10명, 작은 그림 1명","correct":true},{"t":"큰 그림 1명, 작은 그림 10명","mis":"M3-2-u6-X02"},{"t":"큰 그림 1명, 작은 그림 1명","mis":"M3-2-u6-X01"},{"t":"큰 그림 20명, 작은 그림 1명","mis":"M3-2-u6-X18"}],"explanation":["그림그래프 아래 그림의 단위를 먼저 봐요.","큰 그림 10명, 작은 그림 1명이에요.","그림의 크기에 따라 나타내는 수가 달라요 — 그림을 읽기 전에 단위부터 확인해요."],"asset":{"type":"picg","title":"좋아하는 텔레비전 프로그램별 사람 수","head":"프로그램","cols":["㉠","㉡","㉢","㉣"],"counts":[12,21,14,16],"units":[10,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#8','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C1',1,'mc','auto','준비하기 — 좋아하는 동물별 학생 수를 ◯를 이용한 그래프로 나타냈어요. 강아지는 ◯ 6개, 고양이는 ◯ 4개, 햄스터는 ◯ 3개예요. 가장 많은 학생이 좋아하는 동물은 무엇인가요?',ARRAY['M3-2-u6-X16','M3-2-u6-X03','M3-2-u6-X09']::text[],false,'{"seq":8,"concept":"M3-2-u6-C1","difficulty":1,"kind":"mc","stem":"준비하기 — 좋아하는 동물별 학생 수를 ◯를 이용한 그래프로 나타냈어요. 강아지는 ◯ 6개, 고양이는 ◯ 4개, 햄스터는 ◯ 3개예요. 가장 많은 학생이 좋아하는 동물은 무엇인가요?","options":[{"t":"강아지","correct":true},{"t":"햄스터","mis":"M3-2-u6-X16"},{"t":"고양이","mis":"M3-2-u6-X03"},{"t":"그래프로는 알 수 없어요","mis":"M3-2-u6-X09"}],"explanation":["◯ 그래프는 ◯ 하나가 학생 한 명이에요.","강아지 6명, 고양이 4명, 햄스터 3명이에요.","◯가 가장 많은 강아지를 가장 많은 학생이 좋아해요 — 그래프는 많고 적음이 한눈에 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#9','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C3',2,'mc','auto','한 달 동안 우산 가게 4곳에서 판매한 우산의 수 그림그래프예요. 우산을 가장 많이 판매한 가게는 어디인가요?',ARRAY['M3-2-u6-X04','M3-2-u6-X16','M3-2-u6-X03']::text[],false,'{"seq":9,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"한 달 동안 우산 가게 4곳에서 판매한 우산의 수 그림그래프예요. 우산을 가장 많이 판매한 가게는 어디인가요?","options":[{"t":"소나기","correct":true},{"t":"여우비","mis":"M3-2-u6-X04"},{"t":"이슬비","mis":"M3-2-u6-X16"},{"t":"장맛비","mis":"M3-2-u6-X03"}],"explanation":["그림의 단위는 50개, 10개, 1개예요.","소나기 160개, 여우비 105개, 이슬비 80개, 장맛비 91개예요.","50개 그림이 3개인 소나기가 가장 많아요 — 여우비는 그림이 7개여도 105개예요."],"asset":{"type":"picg","title":"가게별 판매한 우산 수","head":"가게","cols":["소나기","여우비","이슬비","장맛비"],"counts":[160,105,80,91],"units":[50,10,1],"icon":"☂","unit":"개","vh":"우산의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#10','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 이슬비 가게에서 판매한 우산은 몇 개인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 이슬비 가게에서 판매한 우산은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["80"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 50개, 가운데 그림 10개, 작은 그림 1개.","이슬비 줄은 50개 그림 1개와 10개 그림 3개 — 50 × 1 + 10 × 3 = 80.","이슬비 가게에서 판매한 우산은 80개예요."],"asset":{"type":"picg","title":"가게별 판매한 우산 수","head":"가게","cols":["소나기","여우비","이슬비","장맛비"],"counts":[160,105,80,91],"units":[50,10,1],"icon":"☂","unit":"개","vh":"우산의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#11','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C3',2,'mc','auto','좋아하는 민속놀이별 3학년 학생 수 그림그래프예요. 3학년 학생들이 가장 적게 좋아하는 민속놀이는 무엇인가요?',ARRAY['M3-2-u6-X03','M3-2-u6-X04']::text[],false,'{"seq":11,"concept":"M3-2-u6-C3","difficulty":2,"kind":"mc","stem":"좋아하는 민속놀이별 3학년 학생 수 그림그래프예요. 3학년 학생들이 가장 적게 좋아하는 민속놀이는 무엇인가요?","options":[{"t":"투호","correct":true},{"t":"연날리기","mis":"M3-2-u6-X03"},{"t":"윷놀이","mis":"M3-2-u6-X04"},{"t":"줄다리기","mis":"M3-2-u6-X03"}],"explanation":["큰 그림이 몇 개인지부터 견주고, 같으면 작은 그림을 견줘요 — 그림의 개수가 아니라 나타내는 수로 견줘요.","연날리기 23명, 윷놀이 30명, 줄다리기 25명, 투호 12명.","가장 적은 것은 투호예요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 3학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[23,30,25,12],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#12','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C2',2,'sa','auto','그림그래프를 보고 연날리기를 좋아하는 3학년 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 연날리기를 좋아하는 3학년 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["23"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","연날리기 줄은 10명 그림 2개와 1명 그림 3개 — 10 × 2 + 1 × 3 = 23.","연날리기를 좋아하는 3학년 학생은 23명이에요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 3학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[23,30,25,12],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#13','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C3',2,'sa','auto','그림그래프를 보고 축구를 좋아하는 사람은 농구를 좋아하는 사람보다 몇 명 더 많은지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M3-2-u6-C3","difficulty":2,"kind":"sa","stem":"그림그래프를 보고 축구를 좋아하는 사람은 농구를 좋아하는 사람보다 몇 명 더 많은지 구하세요. 숫자로 쓰세요.","answer":["6"],"explanation":["두 항목의 수를 먼저 읽어요 — 축구 11명, 농구 5명.","몇 개 더 많은지는 뺄셈으로 구해요.","11 − 5 = 6 — 6명 더 많아요."],"asset":{"type":"picg","title":"좋아하는 운동별 사람 수","head":"운동","cols":["농구","야구","축구","탁구"],"counts":[5,7,11,6],"units":[5,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#14','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C2',2,'sa','auto','민서네 학교 3학년 학생들이 좋아하는 과일 그림그래프예요. 한라봉을 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M3-2-u6-C2","difficulty":2,"kind":"sa","stem":"민서네 학교 3학년 학생들이 좋아하는 과일 그림그래프예요. 한라봉을 좋아하는 학생은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["72"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","한라봉 줄은 10명 그림 7개와 1명 그림 2개 — 10 × 7 + 1 × 2 = 72.","한라봉을 좋아하는 학생은 72명이에요."],"asset":{"type":"picg","title":"좋아하는 과일별 학생 수","head":"과일","cols":["매실","배","사과","포도","한라봉"],"counts":[6,24,null,102,72],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[2]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#15','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C8',2,'sa','auto','겨울의 산불 발생 건수는 268건이에요. 10건·1건의 두 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u6-C8","difficulty":2,"kind":"sa","stem":"겨울의 산불 발생 건수는 268건이에요. 10건·1건의 두 가지 그림으로 나타내면 그림은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["큰 수를 나타내는 그림부터 그려요.","268건 = 10건 그림 26개와 1건 그림 8개.","26 + 8 = 34 — 그림은 모두 34개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#16','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C4',2,'mc','auto','민속놀이 동아리에 가입한 학생은 24명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?',ARRAY['M3-2-u6-X05','M3-2-u6-X06','M3-2-u6-X02']::text[],false,'{"seq":16,"concept":"M3-2-u6-C4","difficulty":2,"kind":"mc","stem":"민속놀이 동아리에 가입한 학생은 24명이에요. 10명·1명의 단위로 그림그래프에 나타내려면 그림을 어떻게 그려야 하나요?","options":[{"t":"10명 그림 2개, 1명 그림 4개","correct":true},{"t":"10명 그림 4개, 1명 그림 2개","mis":"M3-2-u6-X05"},{"t":"1명 그림 24개","mis":"M3-2-u6-X06"},{"t":"10명 그림 3개, 1명 그림 4개","mis":"M3-2-u6-X02"}],"explanation":["큰 수를 나타내는 그림을 먼저 그려요.","24명 안에 10명이 2번 들어가요 — 남은 4명은 1명 그림으로 나타내요.","답은 10명 그림 2개, 1명 그림 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#17','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C3',3,'sa','auto','좋아하는 민속놀이별 3학년·4학년 그림그래프를 보고, 윷놀이를 좋아하는 4학년 학생은 3학년 학생보다 몇 명 더 많은지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M3-2-u6-C3","difficulty":3,"kind":"sa","stem":"좋아하는 민속놀이별 3학년·4학년 그림그래프를 보고, 윷놀이를 좋아하는 4학년 학생은 3학년 학생보다 몇 명 더 많은지 구하세요. 숫자로 쓰세요.","answer":["3"],"explanation":["3학년 윷놀이는 10명 그림 3개 — 30명이에요.","4학년 윷놀이는 10명 그림 3개와 1명 그림 3개 — 33명이에요.","33 − 30 = 3 — 3명 더 많아요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 4학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[13,33,22,21],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#18','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C3',3,'sa','auto','투호를 좋아하는 3학년과 4학년 학생은 모두 몇 명인가요? 두 그림그래프를 보고 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M3-2-u6-C3","difficulty":3,"kind":"sa","stem":"투호를 좋아하는 3학년과 4학년 학생은 모두 몇 명인가요? 두 그림그래프를 보고 구하세요. 숫자로 쓰세요.","answer":["33"],"explanation":["3학년 투호는 10명 그림 1개와 1명 그림 2개 — 12명이에요.","4학년 투호는 10명 그림 2개와 1명 그림 1개 — 21명이에요.","12 + 21 = 33 — 모두 33명이에요."],"asset":{"type":"picg","title":"좋아하는 민속놀이별 4학년 학생 수","head":"민속놀이","cols":["연날리기","윷놀이","줄다리기","투호"],"counts":[13,33,22,21],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#19','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C3',3,'sa','auto','민서네 학교 3학년 과일 그림그래프에서 매실을 좋아하는 학생 수의 3분의 1은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M3-2-u6-C3","difficulty":3,"kind":"sa","stem":"민서네 학교 3학년 과일 그림그래프에서 매실을 좋아하는 학생 수의 3분의 1은 몇 명인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["매실을 좋아하는 학생은 1명 그림 6개 — 6명이에요.","6을 똑같이 3묶음으로 나눈 것 중의 1묶음이에요.","6 ÷ 3 = 2 — 2명이에요."],"asset":{"type":"picg","title":"좋아하는 과일별 학생 수","head":"과일","cols":["매실","배","사과","포도","한라봉"],"counts":[6,24,null,102,72],"units":[10,1],"icon":"🙂","unit":"명","vh":"학생 수","blank":[2]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#20','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C3',3,'mc','auto','우산 가게 이름 찾기 — 「㉱ 가게는 우산을 가장 적게 판매했습니다.」 ㉱ 가게는 어디인가요?',ARRAY['M3-2-u6-X16','M3-2-u6-X03']::text[],false,'{"seq":20,"concept":"M3-2-u6-C3","difficulty":3,"kind":"mc","stem":"우산 가게 이름 찾기 — 「㉱ 가게는 우산을 가장 적게 판매했습니다.」 ㉱ 가게는 어디인가요?","options":[{"t":"이슬비","correct":true},{"t":"소나기","mis":"M3-2-u6-X16"},{"t":"장맛비","mis":"M3-2-u6-X03"},{"t":"여우비","mis":"M3-2-u6-X03"}],"explanation":["소나기 160개, 여우비 105개, 이슬비 80개, 장맛비 91개예요.","이슬비와 장맛비는 50개 그림이 1개씩 — 10개 그림으로 견줘요(3개, 4개).","가장 적게 판매한 가게는 이슬비예요."],"asset":{"type":"picg","title":"가게별 판매한 우산 수","head":"가게","cols":["소나기","여우비","이슬비","장맛비"],"counts":[160,105,80,91],"units":[50,10,1],"icon":"☂","unit":"개","vh":"우산의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#21','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C2',3,'sa','auto','그림그래프를 보고 ㉢ 프로그램을 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u6-C2","difficulty":3,"kind":"sa","stem":"그림그래프를 보고 ㉢ 프로그램을 좋아하는 사람은 몇 명인지 구하세요. 숫자로 쓰세요.","answer":["14"],"explanation":["그림의 단위를 먼저 봐요 — 큰 그림 10명, 작은 그림 1명.","㉢ 줄은 10명 그림 1개와 1명 그림 4개 — 10 × 1 + 1 × 4 = 14.","㉢ 프로그램을 좋아하는 사람은 14명이에요."],"asset":{"type":"picg","title":"좋아하는 텔레비전 프로그램별 사람 수","head":"프로그램","cols":["㉠","㉡","㉢","㉣"],"counts":[12,21,14,16],"units":[10,1],"icon":"🙂","unit":"명","vh":"사람 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#22','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C9',3,'ox','auto','「그림그래프를 읽을 때는 그림의 크기만 보고 많고 적음을 판단하면 된다.」 맞으면 ○, 틀리면 ×를 고르세요.',ARRAY['M3-2-u6-X15']::text[],false,'{"seq":22,"concept":"M3-2-u6-C9","difficulty":3,"kind":"ox","stem":"「그림그래프를 읽을 때는 그림의 크기만 보고 많고 적음을 판단하면 된다.」 맞으면 ○, 틀리면 ×를 고르세요.","answer":"X","reason_options":[{"t":"그림의 단위를 확인하고, 그림이 나타내는 수로 많고 적음을 판단해요","correct":true},{"t":"큰 그림이 있는 쪽이 언제나 더 많아요","mis":"M3-2-u6-X15"}],"mis":"M3-2-u6-X15","explanation":["그림의 크기만 보면 잘못 해석할 수 있어요.","단위를 확인하고 큰 그림부터 세어 수를 읽어요.","수를 읽은 다음 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#23','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C4',4,'essay','teacher','종류별 꽃의 수 표를 보고 붙임딱지로 그림그래프를 완성하려고 해요. 장미(23송이)와 해바라기(7송이)에는 5송이 그림과 1송이 그림을 각각 몇 개 붙여야 하는지 쓰고, 다 붙인 뒤 확인할 점을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u6-C4","difficulty":4,"kind":"essay","stem":"종류별 꽃의 수 표를 보고 붙임딱지로 그림그래프를 완성하려고 해요. 장미(23송이)와 해바라기(7송이)에는 5송이 그림과 1송이 그림을 각각 몇 개 붙여야 하는지 쓰고, 다 붙인 뒤 확인할 점을 써 보세요.","answer_guide":{"answer":"장미: 5송이 그림 4개, 1송이 그림 3개. 해바라기: 5송이 그림 1개, 1송이 그림 2개. 확인할 점: 그림이 나타내는 수가 표의 수와 같은지, 빠진 항목이 없는지 확인한다(그림이 나타내는 수의 합이 합계 101송이와 같은지).","scoring_points":["장미 4개·3개를 구했는가","해바라기 1개·2개를 구했는가","표와 같은지 확인할 점을 썼는가"]},"explanation":["23 = 5 × 4 + 1 × 3이에요.","7 = 5 × 1 + 1 × 2예요.","다 붙인 뒤 표의 내용과 일치하는지 확인해요."],"asset":{"type":"picg","title":"종류별 꽃의 수","head":"종류","cols":["백합","장미","카네이션","튤립","해바라기"],"counts":[18,23,31,22,7],"units":[5,1],"icon":"🌸","unit":"송이","vh":"꽃의 수","table":true,"blank":[1,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#24','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C4',4,'essay','teacher','은비네 학교 학년별 학생 수(1학년 105명, 2학년 100명, 3학년 110명, 4학년 92명, 5학년 90명, 6학년 101명)를 그림그래프로 나타내려고 해요. 그림의 단위를 정하고, 그 단위로 1학년과 4학년을 어떻게 나타내는지 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u6-C4","difficulty":4,"kind":"essay","stem":"은비네 학교 학년별 학생 수(1학년 105명, 2학년 100명, 3학년 110명, 4학년 92명, 5학년 90명, 6학년 101명)를 그림그래프로 나타내려고 해요. 그림의 단위를 정하고, 그 단위로 1학년과 4학년을 어떻게 나타내는지 써 보세요.","answer_guide":{"answer":"예: 100명·10명·1명으로 정하면 1학년은 100명 그림 1개와 1명 그림 5개, 4학년은 10명 그림 9개와 1명 그림 2개로 나타낸다. (50명·10명·1명으로 정하면 1학년은 50명 그림 2개와 1명 그림 5개, 4학년은 50명 그림 1개, 10명 그림 4개, 1명 그림 2개.)","scoring_points":["자료의 수에 알맞은 단위를 정했는가","1학년을 정한 단위로 바르게 나타냈는가","4학년을 정한 단위로 바르게 나타냈는가"]},"explanation":["자료의 수가 100 안팎이라 세 가지 그림이 알맞아요.","100명·10명·1명이면 105 = 100 + 5, 92 = 10 × 9 + 2예요.","50명·10명·1명이면 105 = 50 × 2 + 5, 92 = 50 + 10 × 4 + 2예요."],"asset":{"type":"picg","title":"학년별 학생 수","head":"학년","cols":["1학년","2학년","3학년","4학년","5학년","6학년"],"counts":[105,100,110,92,90,101],"units":[50,10,1],"icon":"🙂","unit":"명","vh":"학생 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u6_review_d#25','math',3,2,'u6','','tb_g3_2_math_u6_review_d','unit_review','M3-2-u6-C5',4,'essay','teacher','음식별 들어 있는 각설탕의 수 그림그래프(도넛 한 개, 떡볶이 일 인분, 콜라 한 캔)를 보고 알 수 있는 내용을 쓰고, 건강한 식습관을 위해 어떻게 하면 좋을지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u6-C5","difficulty":4,"kind":"essay","stem":"음식별 들어 있는 각설탕의 수 그림그래프(도넛 한 개, 떡볶이 일 인분, 콜라 한 캔)를 보고 알 수 있는 내용을 쓰고, 건강한 식습관을 위해 어떻게 하면 좋을지 써 보세요.","answer_guide":{"answer":"예: 도넛 한 개에는 각설탕 5개, 떡볶이 일 인분에는 17개, 콜라 한 캔에는 9개가 들어 있다. 떡볶이 일 인분에 각설탕이 가장 많이 들어 있다. 설탕을 많이 먹으면 충치, 비만 등 문제가 생길 수 있으므로 단 음식을 너무 많이 먹지 않고 음식을 골고루 먹는다.","scoring_points":["그림의 단위(10개·1개)로 수를 바르게 읽었는가","가장 많은 음식 등 알 수 있는 내용을 썼는가","그림그래프의 사실을 근거로 식습관을 썼는가"]},"explanation":["큰 그림은 10개, 작은 그림은 1개예요.","떡볶이 일 인분은 10개 그림 1개와 1개 그림 7개 — 17개로 가장 많아요.","그림그래프에서 읽은 사실로 생활 습관을 정해요."],"asset":{"type":"picg","title":"음식별 들어 있는 각설탕의 수","head":"음식","cols":["도넛 한 개","떡볶이 일 인분","콜라 한 캔"],"counts":[5,17,9],"units":[10,1],"icon":"■","unit":"개","vh":"각설탕의 수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
